export default "s.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    assert any(isinstance(m, WatsonXPlaceholderMiddleware) for m in middleware), (\\n        \\\"WatsonX must get WatsonXPlaceholderMiddleware to recover from placeholder tool args\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_not_attach_watsonx_placeholder_middleware_for_non_watsonx_providers() -> None:\\n    \\\"\\\"\\\"Don't pay the placeholder-detection cost on providers that don't have this quirk.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.agent_helpers.placeholder_corrective_middleware import (\\n        WatsonXPlaceholderMiddleware,\\n    )\\n\\n    fake_openai = MagicMock(name=\\\"ChatOpenAI_fake\\\")\\n    type(fake_openai).__name__ = \\\"ChatOpenAI\\\"\\n\\n    captured: dict = {}\\n\\n    def _capture_create_agent(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    component = _build_component()\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=fake_openai),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    assert not any(isinstance(m, WatsonXPlaceholderMiddleware) for m in middleware)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_order_single_tool_call_middleware_outside_watsonx_placeholder_middleware() -> None:\\n    \\\"\\\"\\\"SingleToolCallMiddleware must wrap WatsonXPlaceholderMiddleware.\\n\\n    The clamp is applied to the final response \u2014 including any corrective\\n    re-invoke. Per langchain's middleware composition, the first item in the\\n    list is the outermost layer.\\n    \\\"\\\"\\\"\\n    from lfx.components.models_and_agents.agent_helpers.placeholder_corrective_middleware import (\\n        WatsonXPlaceholderMiddleware,\\n    )\\n    from lfx.components.models_and_agents.agent_helpers.single_tool_call_middleware import (\\n        SingleToolCallMiddleware,\\n    )\\n\\n    fake_watsonx = MagicMock(name=\\\"ChatWatsonx_fake\\\")\\n    type(fake_watsonx).__name__ = \\\"ChatWatsonx\\\"\\n\\n    captured: dict = {}\\n\\n    def _capture_create_agent(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    component = _build_component()\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=fake_watsonx),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    single_idx = next(i for i, m in enumerate(middleware) if isinstance(m, SingleToolCallMiddleware))\\n    placeholder_idx = next(i for i, m in enumerate(middleware) if isinstance(m, WatsonXPlaceholderMiddleware))\\n    assert single_idx < placeholder_idx, (\\n        \\\"SingleToolCallMiddleware must come before WatsonXPlaceholderMiddleware (outermost wraps innermost)\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_yield_clean_single_tool_call_when_watsonx_response_has_placeholders_and_multiple_tools() -> None:\\n    \\\"\\\"\\\"End-state composition test: verifies BEHAVIOR, not list-index ordering.\\n\\n    A future refactor that flips both the list ordering AND langchain's composition\\n    convention would pass the index-based test but break the contract. This test\\n    feeds a response that needs BOTH protections (placeholders + multi tool-calls)\\n    through the real middleware chain and asserts the final state: one tool call,\\n    no placeholders, no leakage of the corrective re-invoke into the user-visible\\n    output.\\n    \\\"\\\"\\\"\\n    from langchain.agents.middleware import ModelResponse\\n    from langchain_core.messages import AIMessage\\n    from lfx.components.models_and_agents.agent_helpers.placeholder_corrective_middleware import (\\n        WatsonXPlaceholderMiddleware,\\n    )\\n    from lfx.components.models_and_agents.agent_helpers.single_tool_call_middleware import (\\n        SingleToolCallMiddleware,\\n    )\\n\\n    placeholder_call = {\\n        \\\"id\\\": \\\"call_1\\\",\\n        \\\"name\\\": \\\"search\\\",\\n        \\\"args\\\": {\\\"query\\\": \\\"<result-from-previous-search>\\\"},\\n        \\\"type\\\": \\\"tool_call\\\",\\n    }\\n    extra_call_one = {\\\"id\\\": \\\"call_2\\\", \\\"name\\\": \\\"fetch\\\", \\\"args\\\": {\\\"url\\\": \\\"https://x\\\"}, \\\"type\\\": \\\"tool_call\\\"}\\n    extra_call_two = {\\\"id\\\": \\\"call_3\\\", \\\"name\\\": \\\"calc\\\", \\\"args\\\": {\\\"expr\\\": \\\"1+1\\\"}, \\\"type\\\": \\\"tool_call\\\"}\\n\\n    # First handler call: response with placeholder + 3 tool calls (worst-case\\n    # watsonx response). Second call (corrective re-invoke): same multi-call shape\\n    # but placeholders cleaned up.\\n    bad = ModelResponse(result=[AIMessage(content=\\\"\\\", tool_calls=[placeholder_call, extra_call_one, extra_call_two])])\\n    cleaned = ModelResponse(\\n        result=[\\n            AIMessage(\\n                content=\\\"\\\",\\n                tool_calls=[\\n                    {**placeholder_call, \\\"args\\\": {\\\"query\\\": \\\"real value\\\"}},\\n                    extra_call_one,\\n                    extra_call_two,\\n                ],\\n            )\\n        ]\\n    )\\n    handler_calls: list = []\\n\\n    def model_call(request):\\n        handler_calls.append(request)\\n        return cleaned if len(handler_calls) > 1 else bad\\n\\n    # Compose as `_build_middleware` produces: SingleToolCall outermost,\\n    # WatsonXPlaceholder innermost. Outer wraps inner wraps the raw model call.\\n    placeholder_mw = WatsonXPlaceholderMiddleware()\\n    single_mw = SingleToolCallMiddleware()\\n\\n    def _override(**kw):\\n        return SimpleNamespace(messages=kw[\\\"messages\\\"], override=lambda **_kw: None)\\n\\n    request = SimpleNamespace(messages=[], override=_override)\\n\\n    def inner_wrapped(req):\\n        return placeholder_mw.wrap_model_call(req, model_call)\\n\\n    final = single_mw.wrap_model_call(request, inner_wrapped)\\n\\n    final_msg = final.result[0]\\n    assert len(final_msg.tool_calls) == 1, \\\"SingleToolCall must clamp to one\\\"\\n    assert final_msg.tool_calls[0][\\\"args\\\"] == {\\\"query\\\": \\\"real value\\\"}, \\\"placeholder must be replaced before clamp\\\"\\n    # Sanity: corrective re-invoke happened exactly once.\\n    assert len(handler_calls) == 2\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_recover_when_llm_emits_malformed_tool_args() -> None:\\n    \\\"\\\"\\\"Pydantic ValidationError from bad tool args must NOT crash the agent build.\\n\\n    Small/local models (Ollama, llama, etc.) often emit malformed tool calls \u2014 e.g.\\n    a string `\\\"http://x\\\"` for a parameter typed `list[str]`. The agent must recover\\n    via `ToolRetryMiddleware` (default `retry_on=(Exception,)`, `on_failure='continue'`)\\n    so the LLM sees the error and can correct on retry, rather than crashing the\\n    whole component build.\\n    \\\"\\\"\\\"\\n    from langchain.agents.middleware import ToolRetryMiddleware\\n\\n    captured: dict = {}\\n\\n    def _capture_create_agent(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    component = _build_component()  # handle_parsing_errors=True\\n    component.set_attributes({\\\"tools\\\": [MagicMock(name=\\\"some_tool\\\")]})\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    retry = next((m for m in middleware if isinstance(m, ToolRetryMiddleware)), None)\\n    assert retry is not None, \\\"ToolRetryMiddleware must be wired when handle_parsing_errors=True\\\"\\n    # Defaults: retry_on=(Exception,), on_failure='continue'.\\n    # Both are required for recovery from Pydantic ValidationError on tool args.\\n    assert Exception in retry.retry_on, \\\"Must retry on Exception (covers ValidationError)\\\"\\n    assert retry.on_failure == \\\"continue\\\", \\\"Must convert exhausted retries into a retry-message, not crash\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_attach_token_usage_handler_and_set_usage_on_result_properties() -> None:\\n    \\\"\\\"\\\"Parity with `LCAgentComponent.run_agent`: TokenUsageCallbackHandler must be wired.\\n\\n    Legacy behavior at base/agents/agent.py:265-308:\\n      1. TokenUsageCallbackHandler() is added to callbacks.\\n      2. After process_agent_events, handler.get_usage() is read.\\n      3. Usage is set on `self._token_usage` AND `result.properties.usage`.\\n    Without this, billing/observability that reads `result.properties.usage` breaks.\\n    \\\"\\\"\\\"\\n    from lfx.schema.message import Message as _Msg\\n\\n    fake_usage = {\\\"input_tokens\\\": 12, \\\"output_tokens\\\": 34, \\\"total_tokens\\\": 46}\\n    handler_instance = MagicMock()\\n    handler_instance.get_usage.return_value = fake_usage\\n    captured_callbacks: list = []\\n\\n    def _capture_astream(_input_dict, *, config, **_kwargs):\\n        captured_callbacks.extend(config.get(\\\"callbacks\\\") or [])\\n        return _empty_event_stream()\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = _capture_astream\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n    final_message = _Msg(text=\\\"bye\\\")\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.TokenUsageCallbackHandler\\\",\\n            return_value=handler_instance,\\n        ),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(return_value=final_message),\\n        ),\\n    ):\\n        result = await component.run_agent(fake_graph)\\n\\n    assert handler_instance in captured_callbacks\\n    assert result.properties.usage == fake_usage\\n    assert getattr(component, \\\"_token_usage\\\", None) == fake_usage\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_update_stored_message_and_send_event_when_token_usage_and_result_has_id() -> None:\\n    \\\"\\\"\\\"Parity with legacy lines 304-308: only round-trip the DB when the message was stored.\\n\\n    A message has an `id` only when emitted to a Chat Output (otherwise `_should_skip_message`\\n    is True). Skipping this branch means the stored Message in the DB never gets the usage\\n    field \u2014 observability sees an empty `usage` even when tokens were consumed.\\n    \\\"\\\"\\\"\\n    fake_usage = {\\\"input_tokens\\\": 5, \\\"output_tokens\\\": 7, \\\"total_tokens\\\": 12}\\n    handler_instance = MagicMock()\\n    handler_instance.get_usage.return_value = fake_usage\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    initial_result = MagicMock()\\n    initial_result.get_id.return_value = \\\"msg-stored-123\\\"\\n    initial_result.properties = MagicMock()\\n    stored_result = MagicMock()\\n    stored_result.get_id.return_value = \\\"msg-stored-123\\\"\\n    stored_result.properties = MagicMock()\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    update_stored = AsyncMock(return_value=stored_result)\\n    send_event = AsyncMock()\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch.object(type(component), \\\"_update_stored_message\\\", new=update_stored),\\n        patch.object(type(component), \\\"_send_message_event\\\", new=send_event),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.TokenUsageCallbackHandler\\\",\\n            return_value=handler_instance,\\n        ),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(return_value=initial_result),\\n        ),\\n    ):\\n        result = await component.run_agent(fake_graph)\\n\\n    update_stored.assert_awaited_once_with(initial_result)\\n    send_event.assert_awaited_once_with(stored_result)\\n    assert result is stored_result\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_skip_db_round_trip_when_result_has_no_id() -> None:\\n    \\\"\\\"\\\"Regression guard: when the Message wasn't stored (no ID) we must NOT hit the DB.\\n\\n    `_should_skip_message=True` happens when AgentComponent isn't wired to a Chat Output;\\n    calling `_update_stored_message` on an unstored message would create a phantom row.\\n    \\\"\\\"\\\"\\n    fake_usage = {\\\"input_tokens\\\": 1, \\\"output_tokens\\\": 2, \\\"total_tokens\\\": 3}\\n    handler_instance = MagicMock()\\n    handler_instance.get_usage.return_value = fake_usage\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    unstored_result = MagicMock()\\n    unstored_result.get_id.return_value = None\\n    unstored_result.properties = MagicMock()\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    update_stored = AsyncMock()\\n    send_event = AsyncMock()\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch.object(type(component), \\\"_update_stored_message\\\", new=update_stored),\\n        patch.object(type(component), \\\"_send_message_event\\\", new=send_event),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.TokenUsageCallbackHandler\\\",\\n            return_value=handler_instance,\\n        ),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(return_value=unstored_result),\\n        ),\\n    ):\\n        result = await component.run_agent(fake_graph)\\n\\n    update_stored.assert_not_awaited()\\n    send_event.assert_not_awaited()\\n    # Usage is still set on the in-memory result even when not persisted.\\n    assert unstored_result.properties.usage == fake_usage\\n    assert result is unstored_result\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_event_manager_on_token_callback_to_process_agent_events() -> None:\\n    \\\"\\\"\\\"Parity with legacy lines 261-263, 283: stream tokens to the event manager.\\n\\n    When the component is wired to an event_manager (typical when running inside the\\n    Langflow runtime), `process_agent_events` must receive a callback that pipes each\\n    token chunk to `event_manager.on_token`. Without this, the frontend's live-typing\\n    view stops working for the AgentComponent.\\n    \\\"\\\"\\\"\\n    captured: dict = {}\\n\\n    async def _capture_process(stream, _agent_message, _send_message_callback, on_token_callback=None, **_kw):\\n        # consume the stream so the adapter doesn't leak\\n        async for _ in stream:\\n            pass\\n        captured[\\\"on_token\\\"] = on_token_callback\\n        return MagicMock(get_id=lambda: None, properties=MagicMock())\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    on_token_fn = MagicMock(name=\\\"event_manager_on_token\\\")\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n    component._event_manager = MagicMock()\\n    component._event_manager.on_token = on_token_fn\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch(\\\"lfx.components.models_and_agents.agent.process_agent_events\\\", side_effect=_capture_process),\\n    ):\\n        await component.run_agent(fake_graph)\\n\\n    assert captured.get(\\\"on_token\\\") is on_token_fn\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_none_on_token_callback_when_event_manager_is_absent() -> None:\\n    \\\"\\\"\\\"Regression guard: no event_manager \u2192 on_token_callback must be None, not a stub.\\\"\\\"\\\"\\n    captured: dict = {}\\n\\n    async def _capture_process(stream, _agent_message, _send_message_callback, on_token_callback=None, **_kw):\\n        async for _ in stream:\\n            pass\\n        captured[\\\"on_token\\\"] = on_token_callback\\n        return MagicMock(get_id=lambda: None, properties=MagicMock())\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n    component._event_manager = None\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch(\\\"lfx.components.models_and_agents.agent.process_agent_events\\\", side_effect=_capture_process),\\n    ):\\n        await component.run_agent(fake_graph)\\n\\n    assert captured.get(\\\"on_token\\\") is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_delete_stored_message_and_emit_remove_event_on_exception_with_message_error() -> None:\\n    \\\"\\\"\\\"Parity with legacy lines 285-293: clean up half-stored messages on hard failure.\\n\\n    When `process_agent_events` raises `ExceptionWithMessageError`, the partial agent\\n    Message may already exist in the DB. Without cleanup, the orphaned row stays\\n    visible in the chat history. The legacy run_agent deletes it AND fires a\\n    `remove_message` event so the frontend drops the stale bubble.\\n    \\\"\\\"\\\"\\n    from lfx.base.agents.events import ExceptionWithMessageError as _ExcWithMsg\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    # Use a MagicMock for agent_message \u2014 Pydantic's Message restricts instance-level\\n    # method overrides, but ExceptionWithMessageError doesn't enforce the type at runtime.\\n    half_stored = MagicMock()\\n    half_stored.get_id.return_value = \\\"msg-half-stored-456\\\"\\n    raised_exc = _ExcWithMsg(half_stored, \\\"boom\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    delete_message_mock = AsyncMock()\\n    send_event = AsyncMock()\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch.object(type(component), \\\"_send_message_event\\\", new=send_event),\\n        patch(\\\"lfx.components.models_and_agents.agent.delete_message\\\", new=delete_message_mock),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(side_effect=raised_exc),\\n        ),\\n        pytest.raises(_ExcWithMsg),\\n    ):\\n        await component.run_agent(fake_graph)\\n\\n    delete_message_mock.assert_awaited_once_with(id_=\\\"msg-half-stored-456\\\")\\n    send_event.assert_awaited_once_with(half_stored, category=\\\"remove_message\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_skip_delete_message_on_exception_when_message_was_not_stored() -> None:\\n    \\\"\\\"\\\"Regression guard: don't call delete_message on a Message with no ID.\\\"\\\"\\\"\\n    from lfx.base.agents.events import ExceptionWithMessageError as _ExcWithMsg\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    unstored = MagicMock()\\n    unstored.get_id.return_value = None\\n    raised_exc = _ExcWithMsg(unstored, \\\"boom\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    delete_message_mock = AsyncMock()\\n    send_event = AsyncMock()\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch.object(type(component), \\\"_send_message_event\\\", new=send_event),\\n        patch(\\\"lfx.components.models_and_agents.agent.delete_message\\\", new=delete_message_mock),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(side_effect=raised_exc),\\n        ),\\n        pytest.raises(_ExcWithMsg),\\n    ):\\n        await component.run_agent(fake_graph)\\n\\n    delete_message_mock.assert_not_awaited()\\n    # The remove_message event still fires so the frontend drops the partial bubble.\\n    send_event.assert_awaited_once_with(unstored, category=\\\"remove_message\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_return_final_ai_text_when_message_response_runs_end_to_end() -> None:\\n    \\\"\\\"\\\"Smoke: full path from message_response \u2192 graph \u2192 final Message.\\n\\n    Uses a fake tool-capable chat model that responds with a single AIMessage. The\\n    test verifies the public API of AgentComponent is preserved: an awaitable\\n    `message_response()` that returns a Message whose text is the AI's answer.\\n    \\\"\\\"\\\"\\n    from langchain_core.language_models.fake_chat_models import FakeMessagesListChatModel\\n    from langchain_core.messages import AIMessage\\n\\n    class _ToolCapableFakeChat(FakeMessagesListChatModel):\\n        \\\"\\\"\\\"Minimal LLM that pretends to support tool binding (no-op).\\\"\\\"\\\"\\n\\n        def bind_tools(self, _tools, **_kwargs):  # type: ignore[override]\\n            return self\\n\\n    fake_llm = _ToolCapableFakeChat(responses=[AIMessage(content=\\\"The answer is 4.\\\")])\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"what's 2+2?\\\", \\\"chat_history\\\": []})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=fake_llm),\\n        patch.object(type(component), \\\"get_agent_requirements\\\", new=AsyncMock(return_value=(fake_llm, [], []))),\\n        # We don't store / send messages in this isolated unit test.\\n        patch.object(type(component), \\\"send_message\\\", new=AsyncMock(side_effect=lambda message, **_kw: message)),\\n    ):\\n        result = await component.message_response()\\n\\n    from lfx.schema.message import Message as _Msg\\n\\n    assert isinstance(result, _Msg)\\n    assert \\\"answer is 4\\\" in (result.text or \\\"\\\")\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.skipif(not os.getenv(\\\"OPENAI_API_KEY\\\"), reason=\\\"OpenAI API key required\\\")\\nasync def test_should_call_tool_and_populate_token_usage_when_running_against_real_openai_model() -> None:\\n    \\\"\\\"\\\"Drives `message_response()` end-to-end against a real model with one tool attached.\\n\\n    Validates the bind_tools \u2192 create_agent \u2192 graph \u2192 token callback \u2192\\n    result.properties.usage chain in a single shot \u2014 fakes can't validate\\n    streaming order, real bind_tools, or the token callback wiring at the\\n    same time.\\n\\n    Skipped without `OPENAI_API_KEY`; uses `gpt-4o-mini` to keep the run cheap.\\n    \\\"\\\"\\\"\\n    from langchain_core.tools import tool\\n\\n    langchain_openai = pytest.importorskip(\\\"langchain_openai\\\")\\n\\n    @tool\\n    def echo(text: str) -> str:\\n        \\\"\\\"\\\"Echo the given text back verbatim.\\\"\\\"\\\"\\n        return text\\n\\n    llm = langchain_openai.ChatOpenAI(model=\\\"gpt-4o-mini\\\", temperature=0)\\n\\n    component = _build_component()\\n    component.set_attributes(\\n        {\\n            \\\"input_value\\\": \\\"Use the echo tool to echo the literal word 'pong', then tell me what it returned.\\\",\\n            \\\"chat_history\\\": [],\\n        }\\n    )\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=llm),\\n        patch.object(type(component), \\\"get_agent_requirements\\\", new=AsyncMock(return_value=(llm, [echo], []))),\\n        patch.object(type(component), \\\"send_message\\\", new=AsyncMock(side_effect=lambda message, **_kw: message)),\\n    ):\\n        result = await component.message_response()\\n\\n    from lfx.schema.message import Message as _Msg\\n\\n    assert isinstance(result, _Msg)\\n    # Token usage was populated by TokenUsageCallbackHandler on a real call.\\n    usage = getattr(getattr(result, \\\"properties\\\", None), \\\"usage\\\", None)\\n    assert usage is not None, \\\"result.properties.usage must be populated for billing/observability\\\"\\n    assert (usage.get(\\\"input_tokens\\\") or 0) > 0, \\\"input_tokens must be reported by the real model\\\"\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.skipif(not os.getenv(\\\"OPENAI_API_KEY\\\"), reason=\\\"OpenAI API key required\\\")\\nasync def test_should_stream_multiple_token_chunks_to_event_manager_when_running_against_real_openai_model() -> None:\\n    \\\"\\\"\\\"E2E proof that the streaming pipeline works against a real OpenAI model.\\n\\n    Hard-coding ``stream=True`` in ``_get_llm`` is only useful if the pipeline that\\n    consumes those chunks (``astream_events(v2)`` \u2192 ``handle_on_chain_stream`` \u2192\\n    ``event_manager.on_token``) is intact. This test exercises the full chain against\\n    a real model and asserts that multiple token callbacks fire \u2014 meaning real\\n    token-by-token streaming, not a single bulk delivery.\\n\\n    A failure here would indicate either: (a) the underlying chat model is not built\\n    with ``streaming=True``, or (b) ``handle_on_chain_stream`` stopped forwarding\\n    ``on_chat_model_stream`` chunks to the event manager.\\n    \\\"\\\"\\\"\\n    langchain_openai = pytest.importorskip(\\\"langchain_openai\\\")\\n\\n    llm = langchain_openai.ChatOpenAI(\\n        model=\\\"gpt-4o-mini\\\",\\n        temperature=0,\\n        streaming=True,\\n        stream_usage=True,\\n    )\\n\\n    component = _build_component()\\n    component.set_attributes(\\n        {\\n            \\\"input_value\\\": \\\"Count from 1 to 8 in English, one number per line.\\\",\\n            \\\"chat_history\\\": [],\\n        }\\n    )\\n\\n    token_chunks: list[str] = []\\n\\n    def _on_token(*, data):\\n        chunk = data.get(\\\"chunk\\\")\\n        if chunk:\\n            token_chunks.append(chunk)\\n\\n    component._event_manager = SimpleNamespace(\\n        on_token=_on_token,\\n        on_message=lambda **_kw: None,\\n        on_remove_message=lambda **_kw: None,\\n    )\\n\\n    # Simulate the production send_message callback: it stores the message and\\n    # assigns an ID. handle_on_chain_stream short-circuits when ``message_id`` is\\n    # falsy, so without this the streaming path never fires the on_token callback.\\n    async def _send_message_with_id(message, **_kw):\\n        if not message.get_id():\\n            message.id = \\\"stub-message-id\\\"\\n        return message\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=llm),\\n        patch.object(type(component), \\\"get_agent_requirements\\\", new=AsyncMock(return_value=(llm, [], []))),\\n        patch.object(type(component), \\\"send_message\\\", new=AsyncMock(side_effect=_send_message_with_id)),\\n    ):\\n        result = await component.message_response()\\n\\n    from lfx.schema.message import Message as _Msg\\n\\n    assert isinstance(result, _Msg)\\n    assert (result.text or \\\"\\\").strip(), \\\"real model must return some text\\\"\\n    assert len(token_chunks) > 1, (\\n        f\\\"Expected multiple streamed token chunks; got {len(token_chunks)} chunk(s). \\\"\\n        \\\"When ChatOpenAI is instantiated with streaming=False, LangGraph delivers the \\\"\\n        \\\"response in a single on_chat_model_end event and on_token never fires \u2014 the \\\"\\n        \\\"Playground's live-typing UX is silently disabled in that case.\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_invoke_graph_astream_events_with_messages_input_when_run_agent_called() -> None:\\n    \\\"\\\"\\\"`run_agent(graph)` must feed the graph a `{\\\"messages\\\": [...]}` dict.\\n\\n    LangGraph's `CompiledStateGraph` accepts state-shaped input; this is the contract\\n    that distinguishes the new path from the legacy `{\\\"input\\\": str, ...}` shape. If\\n    this assertion regresses, the agent will silently fail or the LLM will see no\\n    user input.\\n    \\\"\\\"\\\"\\n    from langchain_core.messages import HumanMessage\\n    from lfx.schema.message import Message\\n\\n    captured_input: dict = {}\\n\\n    def _capture_astream(input_dict, **_kwargs):\\n        captured_input[\\\"payload\\\"] = input_dict\\n        return _empty_event_stream()\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = _capture_astream\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": Message(text=\\\"ping\\\", sender=\\\"User\\\")})\\n    fake_result = Message(text=\\\"pong\\\")\\n\\n    with (\\n        patch(\\\"lfx.components.models_and_agents.agent.process_agent_events\\\", new=AsyncMock(return_value=fake_result)),\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n    ):\\n        result = await component.run_agent(fake_graph)\\n\\n    assert result is fake_result\\n    payload = captured_input.get(\\\"payload\\\")\\n    assert isinstance(payload, dict)\\n    assert \\\"messages\\\" in payload\\n    assert isinstance(payload[\\\"messages\\\"], list)\\n    # The user's fresh turn must be present as a HumanMessage.\\n    assert any(isinstance(m, HumanMessage) and \\\"ping\\\" in str(m.content) for m in payload[\\\"messages\\\"])\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_apply_max_iterations_via_model_call_limit_middleware() -> None:\\n    \\\"\\\"\\\"`max_iterations` from the user input maps to ModelCallLimitMiddleware.run_limit.\\n\\n    LangGraph create_agent has no `max_iterations` param \u2014 it expresses the same idea\\n    via middleware. Without this wiring, the legacy \\\"Max Iterations\\\" input becomes a\\n    silent no-op.\\n    \\\"\\\"\\\"\\n    from langchain.agents.middleware import ModelCallLimitMiddleware\\n\\n    captured: dict = {}\\n\\n    def _capture_create_agent(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    component = _build_component()  # max_iterations=7, handle_parsing_errors=True\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    limiters = [m for m in middleware if isinstance(m, ModelCallLimitMiddleware)]\\n    assert limiters, \\\"ModelCallLimitMiddleware must be present when max_iterations is set\\\"\\n    assert limiters[0].run_limit == 7\\n\\n\\n# ===== Eager bind_tools validation ============================================\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_raise_at_build_time_when_llm_does_not_support_tool_calling() -> None:\\n    \\\"\\\"\\\"Tool-incapable models must fail at flow-build time, not at runtime.\\n\\n    `langchain.agents.create_agent` is lazy about validating `bind_tools` support.\\n    Without an explicit eager check, an LLM that doesn't support tool calling\\n    builds the graph fine and only fails on the first user message \u2014 much worse\\n    UX than a clear error in the canvas. The legacy `create_tool_calling_agent`\\n    raised `NotImplementedError` at build time; we preserve that contract.\\n    \\\"\\\"\\\"\\n    bad_llm = MagicMock(name=\\\"bad_llm\\\")\\n    bad_llm.bind_tools.side_effect = NotImplementedError(\\\"provider doesn't support bind_tools\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [MagicMock(name=\\\"some_tool\\\")]})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=bad_llm),\\n        pytest.raises(NotImplementedError, match=\\\"does not support tool calling\\\"),\\n    ):\\n        component.create_agent_runnable()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_through_other_bind_tools_exceptions_unchanged() -> None:\\n    \\\"\\\"\\\"Only the documented \\\"no tool calling\\\" exceptions are mapped to the user-facing message.\\n\\n    `ValueError` from a misconfigured tool, for example, should propagate untouched\\n    so it surfaces its real cause in the logs.\\n    \\\"\\\"\\\"\\n    bad_llm = MagicMock(name=\\\"bad_llm\\\")\\n    bad_llm.bind_tools.side_effect = ValueError(\\\"tool x is missing arg schema\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [MagicMock(name=\\\"some_tool\\\")]})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=bad_llm),\\n        pytest.raises(ValueError, match=\\\"missing arg schema\\\"),\\n    ):\\n        component.create_agent_runnable()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_skip_eager_bind_tools_validation_when_no_tools_attached() -> None:\\n    \\\"\\\"\\\"An Agent without tools doesn't need a tool-calling capable model.\\n\\n    Forcing `bind_tools(...)` on a no-tools flow would shut out plain chat models\\n    (which legitimately don't implement bind_tools), so the eager validation is\\n    gated behind a non-empty tools list.\\n    \\\"\\\"\\\"\\n    chat_only_llm = MagicMock(name=\\\"chat_only\\\")\\n    chat_only_llm.bind_tools.side_effect = NotImplementedError(\\\"no bind_tools support\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": []})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=chat_only_llm),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", return_value=MagicMock()),\\n    ):\\n        # Must not raise \u2014 validation skipped because tools is empty.\\n        component.create_agent_runnable()\\n\\n    chat_only_llm.bind_tools.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_map_attribute_error_from_bind_tools_to_user_message() -> None:\\n    \\\"\\\"\\\"Some providers don't expose `bind_tools` at all (raises AttributeError).\\\"\\\"\\\"\\n    bad_llm = MagicMock(name=\\\"bad_llm\\\")\\n    bad_llm.bind_tools.side_effect = AttributeError(\\\"'X' object has no attribute 'bind_tools'\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [MagicMock(name=\\\"some_tool\\\")]})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=bad_llm),\\n        pytest.raises(NotImplementedError, match=\\\"does not support tool calling\\\"),\\n    ):\\n        component.create_agent_runnable()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_map_type_error_from_bind_tools_to_user_message() -> None:\\n    \\\"\\\"\\\"Some providers raise TypeError on signature mismatches; same UX failure.\\\"\\\"\\\"\\n    bad_llm = MagicMock(name=\\\"bad_llm\\\")\\n    bad_llm.bind_tools.side_effect = TypeError(\\\"bind_tools() got unexpected kwarg\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [MagicMock(name=\\\"some_tool\\\")]})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=bad_llm),\\n        pytest.raises(NotImplementedError, match=\\\"does not support tool calling\\\"),\\n    ):\\n        component.create_agent_runnable()\\n\\n\\n# ===== Input info-text overrides ==============================================\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_not_mutate_shared_base_inputs_when_overriding_info_text() -> None:\\n    \\\"\\\"\\\"`_agent_base_inputs()` substitutes new instances; it must not edit the shared list.\\n\\n    `LCToolsAgentComponent.get_base_inputs()` returns the same list object every call\\n    (via the `_base_inputs` class attribute). Mutating those instances would leak the\\n    AgentComponent-specific info text into every other LCAgentComponent subclass.\\n    \\\"\\\"\\\"\\n    from lfx.base.agents.agent import LCToolsAgentComponent\\n    from lfx.components.models_and_agents.agent import _agent_base_inputs\\n\\n    pristine_before = {inp.name: inp.info for inp in LCToolsAgentComponent.get_base_inputs()}\\n\\n    customized = _agent_base_inputs()\\n    customized_info = {inp.name: inp.info for inp in customized}\\n    # The override actually changed the info text on the customized copy.\\n    assert customized_info[\\\"handle_parsing_errors\\\"] != pristine_before[\\\"handle_parsing_errors\\\"]\\n    assert customized_info[\\\"max_iterations\\\"] != pristine_before[\\\"max_iterations\\\"]\\n\\n    pristine_after = {inp.name: inp.info for inp in LCToolsAgentComponent.get_base_inputs()}\\n    assert pristine_after == pristine_before, (\\n        \\\"AgentComponent's input overrides leaked into the shared LCToolsAgentComponent base list\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_drop_verbose_input_from_agent_component() -> None:\\n    \\\"\\\"\\\"`verbose` is a no-op on the create_agent path and must be removed from the schema.\\n\\n    The legacy AgentExecutor honored `verbose=True` by dumping reasoning steps to\\n    stdout. Under create_agent, every step is already surfaced via the \\\"Agent Steps\\\"\\n    content blocks in the chat panel \u2014 `verbose` has nothing to toggle. Keeping a\\n    deprecated boolean in the input schema would just confuse users, so we drop it\\n    entirely. Saved flows that carry a `verbose` value ignore it on load.\\n    \\\"\\\"\\\"\\n    from lfx.base.agents.agent import LCToolsAgentComponent\\n    from lfx.components.models_and_agents.agent import AgentComponent, _agent_base_inputs\\n\\n    # Sanity check: the parent class still declares verbose (we're scoping the\\n    # removal to AgentComponent, not yanking it from every LCAgentComponent subclass).\\n    parent_input_names = {inp.name for inp in LCToolsAgentComponent.get_base_inputs()}\\n    assert \\\"verbose\\\" in parent_input_names, \\\"test premise broken \u2014 base class no longer declares verbose\\\"\\n\\n    # `_agent_base_inputs()` filters it out.\\n    customized_names = {inp.name for inp in _agent_base_inputs()}\\n    assert \\\"verbose\\\" not in customized_names\\n\\n    # The full AgentComponent inputs list also lacks verbose.\\n    component_input_names = {inp.name for inp in AgentComponent.inputs}\\n    assert \\\"verbose\\\" not in component_input_names\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_not_require_verbose_in_update_build_config() -> None:\\n    \\\"\\\"\\\"`update_build_config` must not require `verbose` after the input was dropped.\\n\\n    Regression: when the user changes the model in the canvas, the FE re-sends\\n    the build_config. After dropping `verbose` from the input set, that\\n    build_config no longer carries the key, and the legacy required-keys check\\n    raised ``Missing required keys in build_config: ['verbose']`` on every\\n    model change. The validator must accept a build_config without `verbose`.\\n    \\\"\\\"\\\"\\n    component = _build_component()\\n\\n    # Build a build_config that has every key the validator requires *except* verbose.\\n    from lfx.schema.dotdict import dotdict\\n\\n    build_config = dotdict(\\n        {\\n            \\\"code\\\": {\\\"value\\\": \\\"\\\"},\\n            \\\"_type\\\": {\\\"value\\\": \\\"AgentComponent\\\"},\\n            \\\"model\\\": {\\\"value\\\": \\\"fake-model\\\"},\\n            \\\"tools\\\": {\\\"value\\\": []},\\n            \\\"input_value\\\": {\\\"value\\\": \\\"\\\"},\\n            \\\"add_current_date_tool\\\": {\\\"value\\\": False},\\n            \\\"add_calculator_tool\\\": {\\\"value\\\": False},\\n            \\\"system_prompt\\\": {\\\"value\\\": \\\"\\\"},\\n            \\\"agent_description\\\": {\\\"value\\\": \\\"\\\"},\\n            \\\"max_iterations\\\": {\\\"value\\\": 15},\\n            \\\"handle_parsing_errors\\\": {\\\"value\\\": True},\\n        }\\n    )\\n\\n    # Patch the helpers that touch the network / option cache so we isolate\\n    # the validator branch.\\n    with (\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.handle_model_input_update\\\",\\n            side_effect=lambda **kwargs: kwargs[\\\"build_config\\\"],\\n        ),\\n        patch.object(type(component), \\\"update_input_types\\\", side_effect=lambda bc: bc),\\n    ):\\n        # Should NOT raise. If it does, the canvas surfaces \\\"Error while updating\\n        # the Component \u2014 Missing required keys in build_config: ['verbose']\\\".\\n        await component.update_build_config(build_config, [], field_name=\\\"model\\\")\\n\\n\\n# ===== _inject_dynamic_prompt_values: connected (Message) system_prompt =========\\n# CodeRabbit PR #12992 (comment 3266521738): `system_prompt` is a MultilineInput\\n# that accepts connections (e.g. a Prompt node in Invoice Summarizer wires into\\n# Agent.system_prompt). When the connected value arrives as a Message, the old\\n# `prompt.replace(...)` raised AttributeError before the agent could run.\\n\\n\\ndef test_should_replace_placeholders_when_system_prompt_arrives_as_a_message() -> None:\\n    \\\"\\\"\\\"A connected `Message` system_prompt must be normalized to text, not crash.\\n\\n    `_inject_dynamic_prompt_values` did `prompt.replace(...)` directly; a Message has\\n    no `.replace`, so a connected Prompt node blew up the agent build with\\n    AttributeError. The helper must reuse `_extract_text_content` first.\\n    \\\"\\\"\\\"\\n    from lfx.schema.message import Message\\n\\n    component = _build_component()\\n    with patch.object(type(component), \\\"_get_resolved_model_name\\\", return_value=\\\"gpt-test\\\"):\\n        result = component._inject_dynamic_prompt_values(Message(text=\\\"Model {model_name} on {current_date}.\\\"))\\n\\n    assert isinstance(result, str)\\n    assert \\\"{model_name}\\\" not in result\\n    assert \\\"gpt-test\\\" in result\\n    assert \\\"{current_date}\\\" not in result\\n\\n\\ndef test_should_return_none_when_system_prompt_is_none() -> None:\\n    \\\"\\\"\\\"Preserve the original contract: None in \u2192 None out (callers rely on `or ''`).\\\"\\\"\\\"\\n    component = _build_component()\\n\\n    assert component._inject_dynamic_prompt_values(None) is None\\n\\n\\ndef test_should_render_default_system_prompt_at_agent_runtime_seam() -> None:\\n    \\\"\\\"\\\"The component must resolve the default prompt's runtime environment fields.\\\"\\\"\\\"\\n    from lfx.base.agents.default_system_prompt import DEFAULT_SYSTEM_PROMPT_TEMPLATE\\n\\n    component = _build_component()\\n    with patch.object(type(component), \\\"_get_resolved_model_name\\\", return_value=\\\"loopback-model\\\"):\\n        result = component._inject_dynamic_prompt_values(DEFAULT_SYSTEM_PROMPT_TEMPLATE)\\n\\n    assert result is not None\\n    assert \\\"{current_date}\\\" not in result\\n    assert \\\"{model_name}\\\" not in result\\n    assert \\\"loopback-model\\\" in result\\n    assert \\\"# Environment\\\" in result\\n\\n\\ndef test_should_pass_custom_system_prompt_through_unchanged_without_opt_in_placeholders() -> None:\\n    \\\"\\\"\\\"Custom prompts are byte-preserved unless they opt in with a known placeholder.\\\"\\\"\\\"\\n    component = _build_component()\\n    custom = 'Keep this JSON literal unchanged: {\\\"answer\\\": 42}.'\\n\\n    assert component._inject_dynamic_prompt_values(custom) == custom\\n\\n\\ndef test_should_replace_known_placeholders_in_opted_in_custom_system_prompt() -> None:\\n    \\\"\\\"\\\"A custom prompt can independently opt into date/model substitution.\\\"\\\"\\\"\\n    component = _build_component()\\n    custom = 'Model {model_name} on {current_date}; JSON: {\\\"answer\\\": 42}.'\\n    with patch.object(type(component), \\\"_get_resolved_model_name\\\", return_value=\\\"m1\\\"):\\n        result = component._inject_dynamic_prompt_values(custom)\\n\\n    assert result is not None\\n    assert \\\"{model_name}\\\" not in result\\n    assert \\\"{current_date}\\\" not in result\\n    assert \\\"Model m1 on \\\" in result\\n    assert '{\\\"answer\\\": 42}' in result\\n\\n\\n# ===== max_iterations must never silently disable the call cap =================\\n# CodeRabbit PR #12992 (comment 3266521785): `if max_iterations:` treats a saved\\n# `0` as \\\"no limit\\\", removing the ModelCallLimitMiddleware guard entirely and\\n# allowing unbounded model/tool calls (DoS-via-loop).\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_still_cap_model_calls_when_max_iterations_is_zero() -> None:\\n    \\\"\\\"\\\"A saved `max_iterations=0` must NOT remove the iteration cap.\\n\\n    `0` is falsy, so `if max_iterations:` skipped ModelCallLimitMiddleware and the\\n    agent could loop unbounded. A non-positive value must be clamped to a real cap.\\n    \\\"\\\"\\\"\\n    from langchain.agents.middleware import ModelCallLimitMiddleware\\n\\n    captured: dict = {}\\n\\n    def _capture_create_agent(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"max_iterations\\\": 0})\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    limiters = [m for m in middleware if isinstance(m, ModelCallLimitMiddleware)]\\n    assert limiters, \\\"ModelCallLimitMiddleware must remain when max_iterations is 0 (no unbounded loop)\\\"\\n    assert limiters[0].run_limit >= 1\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_skip_tool_retry_middleware_when_no_tools_attached() -> None:\\n    \\\"\\\"\\\"Trivial-prompt latency guard (QA UI-003).\\n\\n    `ToolRetryMiddleware` exists to recover from runtime errors in tool execution.\\n    With an empty tools list it has nothing to retry, but its presence still\\n    inflates the compiled graph and adds per-invocation middleware overhead on\\n    every model call. For \\\"Say hello\\\"-style prompts (no tools, gpt-4o-mini) the\\n    baseline expectation is 1-2s wall and we currently observe 4.8-14.2s. The\\n    middleware audit is one cheap, low-risk improvement: don't wire what can't\\n    fire.\\n    \\\"\\\"\\\"\\n    from langchain.agents.middleware import ToolRetryMiddleware\\n\\n    captured: dict = {}\\n\\n    def _capture_create_agent(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [], \\\"handle_parsing_errors\\\": True})\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_create_agent),\\n    ):\\n        component.create_agent_runnable()\\n\\n    middleware = captured.get(\\\"middleware\\\") or []\\n    assert not any(isinstance(m, ToolRetryMiddleware) for m in middleware), (\\n        \\\"ToolRetryMiddleware must NOT be attached when there are no tools \u2014 it cannot fire and only \\\"\\n        \\\"adds per-call middleware overhead, contributing to the UI-003 trivial-prompt latency.\\\"\\n    )\\n\\n\\ndef test_should_declare_min_one_range_spec_on_max_iterations_input() -> None:\\n    \\\"\\\"\\\"The UI must not let users set `max_iterations` below 1.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.agent import _agent_base_inputs\\n\\n    max_iter = next(inp for inp in _agent_base_inputs() if inp.name == \\\"max_iterations\\\")\\n\\n    assert max_iter.range_spec is not None, \\\"max_iterations needs a RangeSpec to block sub-1 values\\\"\\n    assert max_iter.range_spec.min == 1\\n\\n\\n# ===== recursion_limit must be tied to max_iterations =========================\\n# QA UI-009/UI-010 (PR #12992): malformed prompts loop on tool calls until\\n# LangGraph's default `recursion_limit=25` fires (\u224812 model+tool iterations),\\n# regardless of the user-set `max_iterations`. The ModelCallLimitMiddleware\\n# alone is insufficient because the graph-level recursion guard trips first.\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_recursion_limit_derived_from_max_iterations_when_streaming_events() -> None:\\n    \\\"\\\"\\\"`run_agent` must pass a `recursion_limit` aligned with `max_iterations`.\\n\\n    Without this, an Agent with `max_iterations=15` crashes at LangGraph's default\\n    25 graph steps (\u224812 model+tool iterations) with `GraphRecursionError: Recursion\\n    limit of 25 reached` \u2014 long before the ModelCallLimitMiddleware's 15-call cap\\n    would have taken effect. The graph guard MUST sit above the middleware so the\\n    middleware's user-facing cap is what bounds the loop.\\n\\n    Each iteration is roughly 2 graph steps (model node + tools node) plus a small\\n    constant overhead, so `recursion_limit >= max_iterations * 2 + 5` is the bare\\n    minimum that lets the middleware fire first.\\n    \\\"\\\"\\\"\\n    captured_config: dict = {}\\n\\n    def _capture_astream(_input_dict, *, config, **_kwargs):\\n        captured_config.update(config or {})\\n        return _empty_event_stream()\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = _capture_astream\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"max_iterations\\\": 15, \\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    final_message = MagicMock()\\n    final_message.get_id.return_value = None\\n    final_message.properties = MagicMock()\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(return_value=final_message),\\n        ),\\n    ):\\n        await component.run_agent(fake_graph)\\n\\n    assert \\\"recursion_limit\\\" in captured_config, (\\n        \\\"run_agent must pass `recursion_limit` to astream_events; otherwise LangGraph's \\\"\\n        \\\"default of 25 fires before ModelCallLimitMiddleware reaches the user-set cap \\\"\\n        \\\"(UI-009/UI-010 regression).\\\"\\n    )\\n    # Each user-visible iteration is ~2 graph steps (model + tools), plus overhead.\\n    assert captured_config[\\\"recursion_limit\\\"] >= 15 * 2 + 5, (\\n        f\\\"recursion_limit must sit above max_iterations * 2 + safety; got \\\"\\n        f\\\"{captured_config['recursion_limit']} for max_iterations=15\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_complete_run_agent_synchronously_before_returning_so_downstream_agents_see_final_state() -> None:\\n    \\\"\\\"\\\"Regression guard for QA UI-012 (multi-agent chains).\\n\\n    The QA report claimed \\\"tools of downstream agents fire concurrently with\\n    Agent 1 still running\\\", evidenced by chain spans aggregating to ~474s while\\n    wall time was ~207s. Investigation found:\\n      - `agent.py`'s `run_agent` `await`s `process_agent_events` fully before\\n        returning a Message; it does NOT spawn unawaited tasks.\\n      - `lfx/graph/graph/base.py` runs vertices in topological layers; each\\n        layer's `asyncio.gather(*tasks)` must resolve before the next layer\\n        starts. So downstream `Agent` vertices wired by `input_value` cannot\\n        start until upstream agents complete.\\n      - The 474s vs 207s discrepancy in the QA trace is consistent with\\n        nested-span accounting in LangGraph (parent spans wrap child spans,\\n        and aggregate sums double-count), NOT with concurrent agent execution.\\n\\n    This test pins the agent-side contract: `message_response` only returns\\n    when run_agent has fully resolved. If a future refactor introduces a\\n    fire-and-forget pattern, this test catches it before the regression ships.\\n    \\\"\\\"\\\"\\n    captured_calls: list[tuple[str, float]] = []\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n\\n    async def _record_then_return(_stream, agent_message, *_args, **_kwargs):\\n        from time import perf_counter\\n\\n        captured_calls.append((\\\"process_start\\\", perf_counter()))\\n        captured_calls.append((\\\"process_end\\\", perf_counter()))\\n        return agent_message\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            side_effect=_record_then_return,\\n        ),\\n    ):\\n        from time import perf_counter\\n\\n        before = perf_counter()\\n        await component.run_agent(fake_graph)\\n        after = perf_counter()\\n\\n    process_start_ts = next(ts for name, ts in captured_calls if name == \\\"process_start\\\")\\n    process_end_ts = next(ts for name, ts in captured_calls if name == \\\"process_end\\\")\\n\\n    assert before <= process_start_ts <= process_end_ts <= after, (\\n        \\\"run_agent must fully await process_agent_events before returning. A future change \\\"\\n        \\\"that fires this off as a background task would break multi-agent chain semantics.\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_recursion_limit_when_max_iterations_is_clamped_from_zero() -> None:\\n    \\\"\\\"\\\"`recursion_limit` must use the clamped `max_iterations`, not the raw user input.\\n\\n    A saved `max_iterations=0` is clamped to >=1 by `_build_middleware`; the\\n    recursion_limit derived in `run_agent` must use that same clamped value, not\\n    the raw user input. Otherwise we'd pass `recursion_limit=5` (5 = safety only)\\n    and the agent couldn't run even one iteration.\\n    \\\"\\\"\\\"\\n    captured_config: dict = {}\\n\\n    def _capture_astream(_input_dict, *, config, **_kwargs):\\n        captured_config.update(config or {})\\n        return _empty_event_stream()\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = _capture_astream\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"max_iterations\\\": 0, \\\"input_value\\\": \\\"hi\\\", \\\"chat_history\\\": []})\\n\\n    final_message = MagicMock()\\n    final_message.get_id.return_value = None\\n    final_message.properties = MagicMock()\\n\\n    with (\\n        patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]),\\n        patch(\\n            \\\"lfx.components.models_and_agents.agent.process_agent_events\\\",\\n            new=AsyncMock(return_value=final_message),\\n        ),\\n    ):\\n        await component.run_agent(fake_graph)\\n\\n    # Clamped max_iterations=1 \u2192 at least 1*2+5 = 7 graph steps must be allowed.\\n    assert captured_config.get(\\\"recursion_limit\\\", 0) >= 7, (\\n        \\\"Clamped max_iterations of 1 must still permit at least one model+tool round-trip\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_stream_true_to_get_llm_when_self_stream_toggle_is_false() -> None:\\n    \\\"\\\"\\\"Streaming is mandatory for AgentComponent.\\n\\n    The LLM must always be instantiated with ``stream=True`` so ``astream_events(v2)``\\n    emits ``on_chat_model_stream`` chunks.\\n\\n    Bug: when ``self.stream`` (the legacy BoolInput toggle introduced in PR #13155) is\\n    False, ``_get_llm`` forwards ``stream=False`` to ``get_llm`` and ChatOpenAI is built\\n    with ``streaming=False``. LangGraph then accumulates the response and only emits\\n    ``on_chat_model_end``, so the Playground/API surface stops receiving tokens\\n    incrementally \u2014 i.e. the live-typing UX is silently disabled.\\n\\n    The Agent has no opt-out from streaming (see\\n    ``reference_agent_streaming_mandatory.md``); the toggle is a leftover and the\\n    underlying ``get_llm`` call must always use ``stream=True``.\\n    \\\"\\\"\\\"\\n    captured: dict[str, Any] = {}\\n\\n    def _capture_get_llm(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"fake_chat_model\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"stream\\\": False})\\n\\n    with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\", side_effect=_capture_get_llm):\\n        component._get_llm()\\n\\n    assert captured.get(\\\"stream\\\") is True, (\\n        \\\"AgentComponent._get_llm must hard-code stream=True regardless of the BoolInput \\\"\\n        f\\\"toggle value \u2014 got stream={captured.get('stream')!r}. Without it the underlying \\\"\\n        \\\"ChatOpenAI is built with streaming=False and astream_events stops emitting \\\"\\n        \\\"on_chat_model_stream chunks.\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_stream_true_to_get_llm_when_self_stream_toggle_is_true() -> None:\\n    \\\"\\\"\\\"Sanity check that an explicit stream=True toggle still reaches get_llm.\\n\\n    When the user explicitly toggles stream=True, get_llm must still receive stream=True.\\n    This guards against a regression where the toggle inverts the flag or is consumed\\n    elsewhere before reaching get_llm.\\n    \\\"\\\"\\\"\\n    captured: dict[str, Any] = {}\\n\\n    def _capture_get_llm(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"fake_chat_model\\\")\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"stream\\\": True})\\n\\n    with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\", side_effect=_capture_get_llm):\\n        component._get_llm()\\n\\n    assert captured.get(\\\"stream\\\") is True\\n\\n\\ndef _gated_tool(name: str):\\n    \\\"\\\"\\\"A connected tool whose action was marked 'Require approval' on the tool.\\\"\\\"\\\"\\n    return SimpleNamespace(name=name, metadata={\\\"approval_actions\\\": [\\\"approve\\\", \\\"reject\\\"]})\\n\\n\\ndef test_should_attach_hitl_middleware_when_a_tool_is_gated() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 1: a tool whose action requires approval adds HumanInTheLoopMiddleware.\\\"\\\"\\\"\\n    from langchain.agents.middleware import HumanInTheLoopMiddleware\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [_gated_tool(\\\"search\\\")]})\\n\\n    middleware = component._build_middleware(MagicMock(name=\\\"fake_llm\\\"))\\n\\n    hitl = [m for m in middleware if isinstance(m, HumanInTheLoopMiddleware)]\\n    assert len(hitl) == 1\\n    assert component._gated_interrupt_on() == {\\\"search\\\": {\\\"allowed_decisions\\\": [\\\"approve\\\", \\\"reject\\\"]}}\\n\\n\\ndef test_should_omit_hitl_middleware_when_no_tools_gated() -> None:\\n    \\\"\\\"\\\"A tool with no approval flag keeps the existing graph shape (no HITL middleware).\\\"\\\"\\\"\\n    from langchain.agents.middleware import HumanInTheLoopMiddleware\\n\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [SimpleNamespace(name=\\\"search\\\", metadata={})]})\\n\\n    middleware = component._build_middleware(MagicMock(name=\\\"fake_llm\\\"))\\n\\n    assert not any(isinstance(m, HumanInTheLoopMiddleware) for m in middleware)\\n\\n\\ndef test_gates_only_tools_marked_for_approval() -> None:\\n    \\\"\\\"\\\"Only tools whose metadata lists approval_actions are gated; others run freely.\\\"\\\"\\\"\\n    component = _build_component()\\n    component.set_attributes(\\n        {\\\"tools\\\": [_gated_tool(\\\"transfer\\\"), SimpleNamespace(name=\\\"search\\\", metadata={\\\"approval_actions\\\": []})]}\\n    )\\n\\n    assert component._gated_interrupt_on() == {\\\"transfer\\\": {\\\"allowed_decisions\\\": [\\\"approve\\\", \\\"reject\\\"]}}\\n\\n\\ndef test_gated_interrupt_on_empty_when_no_tool_marked() -> None:\\n    component = _build_component()\\n    component.set_attributes({\\\"tools\\\": [SimpleNamespace(name=\\\"search\\\", metadata=None)]})\\n\\n    assert component._gated_interrupt_on() == {}\\n\\n\\ndef _capture_kwargs(captured: dict):\\n    def _capture(**kwargs):\\n        captured.update(kwargs)\\n        return MagicMock(name=\\\"compiled_state_graph\\\")\\n\\n    return _capture\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_pass_durable_checkpointer_when_gated_with_run_context() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 3: a gated tool + a per-run id wires the durable saver + thread_id.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.agent_helpers.job_checkpoint_saver import JobCheckpointSaver\\n\\n    captured: dict = {}\\n    component = _build_component()\\n    component._run_id = \\\"job-1\\\"\\n    component.set_attributes(\\n        {\\\"tools\\\": [SimpleNamespace(name=\\\"transfer\\\", metadata={\\\"approval_actions\\\": [\\\"approve\\\", \\\"reject\\\"]})]}\\n    )\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_kwargs(captured)),\\n    ):\\n        component.create_agent_runnable()\\n\\n    assert isinstance(captured.get(\\\"checkpointer\\\"), JobCheckpointSaver)\\n    assert component._agent_thread_id() == \\\"job-1\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_omit_checkpointer_when_no_tools_gated() -> None:\\n    captured: dict = {}\\n    component = _build_component()\\n    component._run_id = \\\"job-1\\\"\\n    component.set_attributes({\\\"tools\\\": [SimpleNamespace(name=\\\"transfer\\\", metadata={})]})\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_kwargs(captured)),\\n    ):\\n        component.create_agent_runnable()\\n\\n    assert captured.get(\\\"checkpointer\\\") is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_omit_checkpointer_and_hitl_when_allow_interrupts_false() -> None:\\n    \\\"\\\"\\\"The structured-output path disables interrupts: no checkpointer, no HITL middleware.\\\"\\\"\\\"\\n    from langchain.agents.middleware import HumanInTheLoopMiddleware\\n\\n    captured: dict = {}\\n    component = _build_component()\\n    component._run_id = \\\"job-1\\\"\\n    component.set_attributes(\\n        {\\\"tools\\\": [SimpleNamespace(name=\\\"transfer\\\", metadata={\\\"approval_actions\\\": [\\\"approve\\\", \\\"reject\\\"]})]}\\n    )\\n    with (\\n        patch.object(type(component), \\\"_get_llm\\\", return_value=MagicMock(name=\\\"fake_llm\\\")),\\n        patch(\\\"lfx.components.models_and_agents.agent.create_agent\\\", side_effect=_capture_kwargs(captured)),\\n    ):\\n        component.create_agent_runnable(allow_interrupts=False)\\n\\n    assert captured.get(\\\"checkpointer\\\") is None\\n    assert not any(isinstance(m, HumanInTheLoopMiddleware) for m in (captured.get(\\\"middleware\\\") or []))\\n\\n\\n_INTERRUPT_VALUE = {\\n    \\\"action_requests\\\": [{\\\"name\\\": \\\"transfer\\\", \\\"args\\\": {\\\"amount\\\": 100}, \\\"description\\\": \\\"Transfer $100 to Bob\\\"}],\\n    \\\"review_configs\\\": [{\\\"action_name\\\": \\\"transfer\\\", \\\"allowed_decisions\\\": [\\\"approve\\\", \\\"reject\\\"]}],\\n}\\n\\n\\ndef test_should_map_middleware_interrupt_to_tool_approval_request() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 4: a HumanInTheLoopMiddleware interrupt maps to the HITL pause contract.\\\"\\\"\\\"\\n    component = _build_component()\\n    component._vertex = SimpleNamespace(graph=SimpleNamespace(run_id=\\\"job-1\\\"))\\n\\n    request = component._map_interrupt_to_request(_INTERRUPT_VALUE)\\n\\n    assert request[\\\"kind\\\"] == \\\"tool_approval\\\"\\n    assert request[\\\"request_id\\\"].endswith(\\\":job-1\\\")\\n    assert request[\\\"prompt\\\"] == \\\"Transfer $100 to Bob\\\"\\n    assert request[\\\"allowed_decisions\\\"] == [\\\"approve\\\", \\\"reject\\\"]\\n    assert request[\\\"options\\\"] == [\\n        {\\\"action_id\\\": \\\"approve\\\", \\\"label\\\": \\\"Approve\\\"},\\n        {\\\"action_id\\\": \\\"reject\\\", \\\"label\\\": \\\"Reject\\\"},\\n    ]\\n    assert request[\\\"action_requests\\\"] == _INTERRUPT_VALUE[\\\"action_requests\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_request_pause_when_agent_stops_on_tool_approval_interrupt() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 4: a pending interrupt makes run_agent suspend instead of completing.\\n\\n    The drained stream leaves the interrupt in the checkpointer; `process_agent_events`\\n    queries it via the getter and raises, so `run_agent` requests a graph pause carrying\\n    the tool-approval request rather than writing a 'complete' message.\\n    \\\"\\\"\\\"\\n    component = _build_component()\\n    component._run_id = \\\"job-1\\\"\\n    component.set_attributes(\\n        {\\\"tools\\\": [SimpleNamespace(name=\\\"transfer\\\", metadata={\\\"approval_actions\\\": [\\\"approve\\\", \\\"reject\\\"]})]}\\n    )\\n    langflow_graph = MagicMock(run_id=\\\"job-1\\\", session_id=\\\"11111111-1111-1111-1111-111111111111\\\")\\n    component._vertex = SimpleNamespace(graph=langflow_graph)\\n    component.send_message = AsyncMock(side_effect=lambda message, **_kwargs: message)\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n    fake_graph.aget_state = AsyncMock(\\n        return_value=SimpleNamespace(interrupts=[SimpleNamespace(value=_INTERRUPT_VALUE)], tasks=[])\\n    )\\n\\n    with patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]):\\n        result = await component.run_agent(fake_graph)\\n\\n    langflow_graph.request_pause.assert_called_once()\\n    _, kwargs = langflow_graph.request_pause.call_args\\n    assert kwargs[\\\"reason\\\"] == \\\"human_input_required\\\"\\n    assert kwargs[\\\"data\\\"][\\\"kind\\\"] == \\\"tool_approval\\\"\\n    assert kwargs[\\\"data\\\"][\\\"allowed_decisions\\\"] == [\\\"approve\\\", \\\"reject\\\"]\\n    assert result.properties.state != \\\"complete\\\"\\n\\n\\ndef test_should_translate_each_action_id_to_its_middleware_decision_shape() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 5: approve/edit/reject/respond map to the HITL middleware resume shape.\\\"\\\"\\\"\\n    component = _build_component()\\n    action_request = {\\\"name\\\": \\\"transfer\\\", \\\"args\\\": {\\\"amount\\\": 100}}\\n\\n    assert component._to_langgraph_decision({\\\"action_id\\\": \\\"approve\\\"}, action_request) == {\\\"type\\\": \\\"approve\\\"}\\n    assert component._to_langgraph_decision({\\\"action_id\\\": \\\"reject\\\", \\\"values\\\": {\\\"message\\\": \\\"no\\\"}}, action_request) == {\\n        \\\"type\\\": \\\"reject\\\",\\n        \\\"message\\\": \\\"no\\\",\\n    }\\n    assert component._to_langgraph_decision(\\n        {\\\"action_id\\\": \\\"respond\\\", \\\"values\\\": {\\\"message\\\": \\\"use 50\\\"}}, action_request\\n    ) == {\\\"type\\\": \\\"respond\\\", \\\"message\\\": \\\"use 50\\\"}\\n    assert component._to_langgraph_decision(\\n        {\\\"action_id\\\": \\\"edit\\\", \\\"values\\\": {\\\"args\\\": {\\\"amount\\\": 50}}}, action_request\\n    ) == {\\n        \\\"type\\\": \\\"edit\\\",\\n        \\\"edited_action\\\": {\\\"name\\\": \\\"transfer\\\", \\\"args\\\": {\\\"amount\\\": 50}},\\n    }\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_stream_resume_command_when_a_human_decision_is_injected() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 5: on resume, run_agent feeds the graph a Command(resume=...), not the input.\\n\\n    The injected decision plus the checkpointed interrupt produce one Decision per pending\\n    tool call so LangGraph continues the paused thread instead of starting over.\\n    \\\"\\\"\\\"\\n    from langgraph.types import Command\\n\\n    component = _build_component()\\n    component._run_id = \\\"job-1\\\"\\n    component.set_attributes(\\n        {\\\"tools\\\": [SimpleNamespace(name=\\\"transfer\\\", metadata={\\\"approval_actions\\\": [\\\"approve\\\", \\\"reject\\\"]})]}\\n    )\\n    langflow_graph = MagicMock(run_id=\\\"job-1\\\", session_id=\\\"11111111-1111-1111-1111-111111111111\\\")\\n    langflow_graph.human_input_decisions = {f\\\"{component._id}:job-1\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n    component._vertex = SimpleNamespace(graph=langflow_graph)\\n    component.send_message = AsyncMock(side_effect=lambda message, **_kwargs: message)\\n\\n    captured: dict = {}\\n\\n    def _astream(stream_input, *, config, **_kwargs):  # noqa: ARG001\\n        captured[\\\"input\\\"] = stream_input\\n        return _empty_event_stream()\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.astream_events = _astream\\n    fake_graph.aget_state = AsyncMock(\\n        return_value=SimpleNamespace(interrupts=[SimpleNamespace(value=_INTERRUPT_VALUE)], tasks=[])\\n    )\\n\\n    with patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]):\\n        await component.run_agent(fake_graph)\\n\\n    assert isinstance(captured[\\\"input\\\"], Command)\\n    assert captured[\\\"input\\\"].resume == {\\\"decisions\\\": [{\\\"type\\\": \\\"approve\\\"}]}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_should_not_probe_interrupts_when_agent_has_no_checkpointer() -> None:\\n    \\\"\\\"\\\"LE-1447 Slice 6: the structured-output path builds without a checkpointer.\\n\\n    Even on a gated component, run_agent must not query interrupt state (which would\\n    raise on a checkpointer-less graph) and must complete normally.\\n    \\\"\\\"\\\"\\n    component = _build_component()\\n    component._run_id = \\\"job-1\\\"\\n    component.set_attributes(\\n        {\\\"tools\\\": [SimpleNamespace(name=\\\"transfer\\\", metadata={\\\"approval_actions\\\": [\\\"approve\\\", \\\"reject\\\"]})]}\\n    )\\n    langflow_graph = MagicMock(run_id=\\\"job-1\\\", session_id=\\\"11111111-1111-1111-1111-111111111111\\\")\\n    component._vertex = SimpleNamespace(graph=langflow_graph)\\n    component.send_message = AsyncMock(side_effect=lambda message, **_kwargs: message)\\n\\n    fake_graph = MagicMock(spec=CompiledStateGraph)\\n    fake_graph.checkpointer = None\\n    fake_graph.astream_events = lambda *_args, **_kwargs: _empty_event_stream()\\n    fake_graph.aget_state = AsyncMock(side_effect=AssertionError(\\\"aget_state must not run without a checkpointer\\\"))\\n\\n    with patch.object(type(component), \\\"_get_shared_callbacks\\\", return_value=[]):\\n        result = await component.run_agent(fake_graph)\\n\\n    langflow_graph.request_pause.assert_not_called()\\n    assert result.properties.state == \\\"complete\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_legacy_agent_llm_selection_participates_in_async_provider_policy(monkeypatch) -> None:\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n    from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n    component = AgentComponent(\\n        model=[],\\n        agent_llm=\\\"Anthropic\\\",\\n        model_name=\\\"claude-test\\\",\\n        _user_id=\\\"resource-owner\\\",\\n        _parameters={\\\"model\\\": [], \\\"agent_llm\\\": \\\"Anthropic\\\", \\\"model_name\\\": \\\"claude-test\\\"},\\n    )\\n    denial = ModelProviderPolicyError(\\\"anthropic\\\", ModelProviderPolicyPurpose.USE)\\n    snapshot = SimpleNamespace(require=MagicMock(side_effect=denial))\\n    resolve_policy = AsyncMock(return_value=snapshot)\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await component.arequire_model_provider_policy(\\n            ModelProviderPolicyPurpose.USE,\\n            user_id=\\\"policy-actor\\\",\\n            parameters={\\\"model\\\": [], \\\"agent_llm\\\": \\\"Anthropic\\\", \\\"model_name\\\": \\\"claude-test\\\"},\\n        )\\n\\n    resolve_policy.assert_awaited_once_with(\\n        user_id=\\\"policy-actor\\\",\\n        providers=[\\\"anthropic\\\"],\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_historical_embedded_agent_llm_selection_uses_base_provider_policy(monkeypatch) -> None:\\n    \\\"\\\"\\\"A saved 1.6 Agent lacks today's override but inherits the current base gate.\\\"\\\"\\\"\\n    from lfx.base.models import model_input_constants\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.custom.utils import build_custom_component_template\\n    from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n    fixture = Path(__file__).parents[3] / \\\"data\\\" / \\\"starter_projects_1_6_0\\\" / \\\"News Aggregator.json\\\"\\n    flow = json.loads(fixture.read_text(encoding=\\\"utf-8\\\"))[\\\"data\\\"]\\n    agent_template = next(\\n        node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"] for node in flow[\\\"nodes\\\"] if \\\"agent_llm\\\" in node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    )\\n    source = agent_template[\\\"code\\\"][\\\"value\\\"]\\n    # The fixture's provider catalog predates the current compatibility module.\\n    # Supply only the inert metadata needed to evaluate its class definition.\\n    monkeypatch.setattr(\\n        model_input_constants,\\n        \\\"MODEL_PROVIDERS_DICT\\\",\\n        {provider: {\\\"inputs\\\": []} for provider in (\\\"Anthropic\\\", \\\"Google Generative AI\\\", \\\"OpenAI\\\")},\\n    )\\n    monkeypatch.setattr(\\n        model_input_constants,\\n        \\\"MODELS_METADATA\\\",\\n        {provider: {} for provider in (\\\"Anthropic\\\", \\\"Google Generative AI\\\", \\\"OpenAI\\\")},\\n    )\\n    _frontend_node, historical_agent = build_custom_component_template(Component(_code=source))\\n\\n    denial = ModelProviderPolicyError(\\\"openai\\\", ModelProviderPolicyPurpose.USE)\\n    snapshot = SimpleNamespace(require=MagicMock(side_effect=denial))\\n    resolve_policy = AsyncMock(return_value=snapshot)\\n    credential_read = MagicMock(side_effect=AssertionError(\\\"credential read reached after policy denial\\\"))\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", credential_read)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await historical_agent.arequire_model_provider_policy(\\n            ModelProviderPolicyPurpose.USE,\\n            user_id=\\\"policy-actor\\\",\\n            parameters={\\\"agent_llm\\\": \\\"OpenAI\\\", \\\"model_name\\\": \\\"gpt-4o\\\"},\\n        )\\n\\n    resolve_policy.assert_awaited_once_with(\\n        user_id=\\\"policy-actor\\\",\\n        providers=[\\\"openai\\\"],\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n    credential_read.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_legacy_agent_runtime_denial_precedes_model_resolution(monkeypatch) -> None:\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n    from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n    component = AgentComponent(model=[], agent_llm=\\\"Anthropic\\\", model_name=\\\"claude-test\\\", _user_id=\\\"policy-actor\\\")\\n    denial = ModelProviderPolicyError(\\\"anthropic\\\", ModelProviderPolicyPurpose.USE)\\n    require_policy = AsyncMock(side_effect=denial)\\n    resolve_model = MagicMock(side_effect=AssertionError(\\\"legacy model resolved after policy denial\\\"))\\n    monkeypatch.setattr(component, \\\"arequire_model_provider_policy\\\", require_policy)\\n    monkeypatch.setattr(component, \\\"_resolve_selected_model\\\", resolve_model)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await component.get_agent_requirements()\\n\\n    require_policy.assert_awaited_once_with(ModelProviderPolicyPurpose.USE)\\n    resolve_model.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_legacy_agent_config_denial_precedes_model_update_hook(monkeypatch) -> None:\\n    from lfx.components.models_and_agents import agent as agent_module\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n    from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n    component = AgentComponent(model=[], agent_llm=\\\"Anthropic\\\", _user_id=\\\"policy-actor\\\")\\n    denial = ModelProviderPolicyError(\\\"anthropic\\\", ModelProviderPolicyPurpose.CONFIGURE)\\n    require_policy = AsyncMock(side_effect=denial)\\n    update_hook = MagicMock(side_effect=AssertionError(\\\"model update hook reached after policy denial\\\"))\\n    monkeypatch.setattr(component, \\\"arequire_model_provider_policy\\\", require_policy)\\n    monkeypatch.setattr(agent_module, \\\"handle_model_input_update\\\", update_hook)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await component.update_build_config({}, \\\"Anthropic\\\", \\\"agent_llm\\\")\\n\\n    require_policy.assert_awaited_once_with(\\n        ModelProviderPolicyPurpose.CONFIGURE,\\n        parameters={\\\"model\\\": [], \\\"agent_llm\\\": \\\"Anthropic\\\"},\\n    )\\n    update_hook.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_legacy_agent_provider_options_are_filtered_by_active_scope(monkeypatch) -> None:\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    component = AgentComponent(_user_id=\\\"policy-actor\\\")\\n    snapshot = SimpleNamespace(filter=lambda providers: [provider for provider in providers if provider == \\\"OpenAI\\\"])\\n    resolve_policy = AsyncMock(return_value=snapshot)\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n    build_config = {\\n        \\\"agent_llm\\\": {\\n            \\\"options\\\": [\\\"Anthropic\\\", \\\"OpenAI\\\"],\\n            \\\"options_metadata\\\": [{\\\"icon\\\": \\\"Anthropic\\\"}, {\\\"icon\\\": \\\"OpenAI\\\"}],\\n        }\\n    }\\n\\n    await component._filter_legacy_provider_options(build_config)\\n\\n    assert build_config[\\\"agent_llm\\\"][\\\"options\\\"] == [\\\"OpenAI\\\"]\\n    assert build_config[\\\"agent_llm\\\"][\\\"options_metadata\\\"] == [{\\\"icon\\\": \\\"OpenAI\\\"}]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/models_and_agents/test_agent_model_remediation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"098ca06466f03f0c0216bb610b7b44de8e2defffdb90df539c4c8860ce452c7a\",\"content\":\"\\\"\\\"\\\"AgentComponent retries with an error-driven model remediation.\\n\\nWhen the selected model rejects the request with a recognized constraint\\n(e.g. OpenAI gpt-5.6 needs the Responses API for tools), message_response must\\nrebuild the model with the remediation override, retry once, and remember the\\nwinning override for the model (discover-once).\\n\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, call, patch\\n\\nimport pytest\\nfrom langchain_core.language_models.fake_chat_models import FakeListChatModel\\nfrom lfx.schema.message import Message\\n\\nGPT56_RESPONSES_API_ERROR = RuntimeError(\\n    \\\"Error building Component Agent: Error code: 400 - Function tools with \\\"\\n    \\\"reasoning_effort are not supported for gpt-5.6-luna in /v1/chat/completions. \\\"\\n    \\\"To use function tools, use /v1/responses or set reasoning_effort to 'none'.\\\"\\n)\\n\\n\\nclass ChatOpenAI(FakeListChatModel):\\n    \\\"\\\"\\\"Dependency-free ChatOpenAI stand-in for the isolated LFX test suite.\\\"\\\"\\\"\\n\\n    model_name: str = \\\"gpt-5.6-luna\\\"\\n    use_responses_api: bool = False\\n\\n\\ndef _attach_connected_model_source(\\n    agent,\\n    display_name: str | None = None,\\n    *,\\n    provider: str | None = None,\\n    model: list[dict] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Attach minimal graph provenance for a model wired into the Agent input.\\\"\\\"\\\"\\n    source = SimpleNamespace(\\n        custom_component=SimpleNamespace(\\n            provider=provider,\\n            model=model or [],\\n            display_name=display_name,\\n        ),\\n    )\\n    graph = MagicMock()\\n    graph.get_vertex.return_value = source\\n    vertex = MagicMock()\\n    vertex.graph = graph\\n    vertex.get_incoming_edge_by_target_param.return_value = \\\"model-source\\\"\\n    agent.set_vertex(vertex)\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"source_kwargs\\\", \\\"expected_provider\\\"),\\n    [\\n        ({\\\"provider\\\": \\\"OpenAI\\\", \\\"model\\\": [{\\\"provider\\\": \\\"OpenRouter\\\"}], \\\"display_name\\\": \\\"Language Model\\\"}, \\\"OpenAI\\\"),\\n        ({\\\"model\\\": [{\\\"provider\\\": \\\"OpenAI\\\"}], \\\"display_name\\\": \\\"Language Model\\\"}, \\\"OpenAI\\\"),\\n        ({\\\"display_name\\\": \\\"OpenAI\\\"}, \\\"OpenAI\\\"),\\n    ],\\n)\\ndef test_connected_model_provider_uses_source_component_provenance(source_kwargs, expected_provider):\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    connected_model = ChatOpenAI(responses=[\\\"unused\\\"])\\n    agent = AgentComponent()\\n    agent.model = connected_model\\n    _attach_connected_model_source(agent, **source_kwargs)\\n\\n    assert agent._selected_model_remediation_context() == (\\n        expected_provider,\\n        \\\"gpt-5.6-luna\\\",\\n        connected_model,\\n    )\\n\\n\\ndef test_connected_model_provider_requires_matching_source_and_model_class():\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    connected_model = FakeListChatModel(responses=[\\\"unused\\\"])\\n    agent = AgentComponent()\\n    agent.model = connected_model\\n    _attach_connected_model_source(agent, \\\"OpenAI\\\")\\n\\n    assert agent._selected_model_remediation_context() == (None, None, connected_model)\\n\\n\\nasync def test_message_response_runs_when_connected_model_source_is_missing():\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    connected_model = ChatOpenAI(responses=[\\\"unused\\\"])\\n    agent = AgentComponent()\\n    agent.model = connected_model\\n    agent.input_value = \\\"hi\\\"\\n    agent.system_prompt = \\\"\\\"\\n    agent.tools = []\\n    agent.add_current_date_tool = False\\n    agent.add_calculator_tool = False\\n    _attach_connected_model_source(agent, \\\"OpenAI\\\")\\n    agent._vertex.graph.get_vertex.side_effect = ValueError(\\\"Vertex model-source not found\\\")\\n    mocked_run_agent = AsyncMock(return_value=Message(text=\\\"ok\\\"))\\n\\n    with (\\n        patch.object(\\n            AgentComponent,\\n            \\\"get_memory_data\\\",\\n            new=AsyncMock(return_value=[]),\\n        ),\\n        patch.object(AgentComponent, \\\"create_agent_runnable\\\", return_value=MagicMock()),\\n        patch.object(AgentComponent, \\\"run_agent\\\", new=mocked_run_agent),\\n    ):\\n        result = await agent.message_response()\\n\\n    assert result.text == \\\"ok\\\"\\n    assert mocked_run_agent.await_count == 1\\n\\n\\nasync def test_message_response_remediates_responses_api_error_and_remembers():\\n    from lfx.base.models import model_remediation\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    model_remediation.reset_remediation_cache()\\n    try:\\n        agent = AgentComponent()\\n        agent.input_value = \\\"hi\\\"\\n        agent.system_prompt = \\\"\\\"\\n        agent.tools = []\\n\\n        run_agent = AsyncMock(side_effect=[GPT56_RESPONSES_API_ERROR, Message(text=\\\"ok\\\")])\\n\\n        with (\\n            patch.object(\\n                AgentComponent,\\n                \\\"_resolve_selected_model\\\",\\n                return_value=[{\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": \\\"gpt-5.6-luna\\\"}],\\n            ),\\n            patch.object(\\n                AgentComponent,\\n                \\\"get_agent_requirements\\\",\\n                new=AsyncMock(return_value=(MagicMock(), [], [])),\\n            ),\\n            patch.object(AgentComponent, \\\"create_agent_runnable\\\", return_value=MagicMock()),\\n            patch.object(AgentComponent, \\\"_inject_dynamic_prompt_values\\\", return_value=\\\"\\\"),\\n            patch.object(AgentComponent, \\\"set\\\", new=MagicMock()),\\n            patch.object(AgentComponent, \\\"run_agent\\\", new=run_agent),\\n        ):\\n            result = await agent.message_response()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"ok\\\"\\n        assert run_agent.await_count == 2\\n        assert agent._model_overrides == {\\\"use_responses_api\\\": True}\\n        assert model_remediation.cached_overrides(\\\"OpenAI\\\", \\\"gpt-5.6-luna\\\") == {\\\"use_responses_api\\\": True}\\n    finally:\\n        model_remediation.reset_remediation_cache()\\n\\n\\nasync def test_message_response_remediates_a_connected_model_in_place_without_caching():\\n    from lfx.base.models import model_remediation\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    model_remediation.reset_remediation_cache()\\n    try:\\n        connected_model = ChatOpenAI(responses=[\\\"unused\\\"])\\n        agent = AgentComponent()\\n        agent.model = connected_model\\n        agent.input_value = \\\"hi\\\"\\n        agent.system_prompt = \\\"\\\"\\n        agent.tools = []\\n        agent.add_current_date_tool = False\\n        agent.add_calculator_tool = False\\n        _attach_connected_model_source(agent, \\\"OpenAI\\\")\\n        seen_values: list[bool] = []\\n\\n        assert agent._selected_model_remediation_context() == (\\n            \\\"OpenAI\\\",\\n            \\\"gpt-5.6-luna\\\",\\n            connected_model,\\n        )\\n\\n        async def run_agent(_agent):\\n            assert agent.llm is connected_model\\n            seen_values.append(connected_model.use_responses_api)\\n            if not connected_model.use_responses_api:\\n                raise GPT56_RESPONSES_API_ERROR\\n            return Message(text=\\\"ok\\\")\\n\\n        mocked_run_agent = AsyncMock(side_effect=run_agent)\\n        with (\\n            patch.object(model_remediation, \\\"remember\\\") as remember,\\n            patch.object(\\n                AgentComponent,\\n                \\\"get_memory_data\\\",\\n                new=AsyncMock(return_value=[]),\\n            ),\\n            patch.object(AgentComponent, \\\"create_agent_runnable\\\", return_value=MagicMock()),\\n            patch.object(AgentComponent, \\\"run_agent\\\", new=mocked_run_agent),\\n        ):\\n            result = await agent.message_response()\\n\\n        assert result.text == \\\"ok\\\"\\n        assert seen_values == [False, True]\\n        assert mocked_run_agent.await_count == 2\\n        assert connected_model.use_responses_api is True\\n        remember.assert_not_called()\\n        assert model_remediation.cached_overrides(\\\"OpenAI\\\", \\\"gpt-5.6-luna\\\") == {}\\n    finally:\\n        model_remediation.reset_remediation_cache()\\n\\n\\nasync def test_message_response_does_not_retry_for_a_non_openai_connected_model():\\n    from lfx.base.models import model_remediation\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    model_remediation.reset_remediation_cache()\\n    try:\\n        # OpenRouter also uses ChatOpenAI, so the class name alone must not opt\\n        # a connected model into an OpenAI-only remediation.\\n        connected_model = ChatOpenAI(responses=[\\\"unused\\\"])\\n        agent = AgentComponent()\\n        agent.model = connected_model\\n        agent.input_value = \\\"hi\\\"\\n        agent.system_prompt = \\\"\\\"\\n        agent.tools = []\\n        agent.add_current_date_tool = False\\n        agent.add_calculator_tool = False\\n        _attach_connected_model_source(agent, \\\"OpenRouter\\\")\\n        mocked_run_agent = AsyncMock(side_effect=GPT56_RESPONSES_API_ERROR)\\n\\n        assert agent._selected_model_remediation_context() == (\\n            \\\"OpenRouter\\\",\\n            \\\"gpt-5.6-luna\\\",\\n            connected_model,\\n        )\\n\\n        with (\\n            patch.object(\\n                AgentComponent,\\n                \\\"get_memory_data\\\",\\n                new=AsyncMock(return_value=[]),\\n            ),\\n            patch.object(AgentComponent, \\\"create_agent_runnable\\\", return_value=MagicMock()),\\n            patch.object(AgentComponent, \\\"run_agent\\\", new=mocked_run_agent),\\n            pytest.raises(RuntimeError, match=r\\\"gpt-5\\\\.6-luna\\\"),\\n        ):\\n            await agent.message_response()\\n\\n        assert mocked_run_agent.await_count == 1\\n        assert model_remediation.cached_overrides(\\\"OpenAI\\\", \\\"gpt-5.6-luna\\\") == {}\\n    finally:\\n        model_remediation.reset_remediation_cache()\\n\\n\\nasync def test_message_response_does_not_retry_unrelated_errors():\\n    from lfx.base.models import model_remediation\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    model_remediation.reset_remediation_cache()\\n    try:\\n        agent = AgentComponent()\\n        agent.input_value = \\\"hi\\\"\\n        agent.system_prompt = \\\"\\\"\\n        agent.tools = []\\n\\n        run_agent = AsyncMock(side_effect=RuntimeError(\\\"rate limit exceeded\\\"))\\n\\n        with (\\n            patch.object(\\n                AgentComponent,\\n                \\\"_resolve_selected_model\\\",\\n                return_value=[{\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": \\\"gpt-5.6-luna\\\"}],\\n            ),\\n            patch.object(\\n                AgentComponent,\\n                \\\"get_agent_requirements\\\",\\n                new=AsyncMock(return_value=(MagicMock(), [], [])),\\n            ),\\n            patch.object(AgentComponent, \\\"create_agent_runnable\\\", return_value=MagicMock()),\\n            patch.object(AgentComponent, \\\"_inject_dynamic_prompt_values\\\", return_value=\\\"\\\"),\\n            patch.object(AgentComponent, \\\"set\\\", new=MagicMock()),\\n            patch.object(AgentComponent, \\\"run_agent\\\", new=run_agent),\\n            pytest.raises(RuntimeError, match=\\\"rate limit\\\"),\\n        ):\\n            await agent.message_response()\\n\\n        assert run_agent.await_count == 1\\n        assert model_remediation.cached_overrides(\\\"OpenAI\\\", \\\"gpt-5.6-luna\\\") == {}\\n    finally:\\n        model_remediation.reset_remediation_cache()\\n\\n\\nasync def test_json_response_remediates_a_connected_model_prompt_fallback():\\n    from lfx.base.models import model_remediation\\n    from lfx.components.models_and_agents.agent import AgentComponent\\n\\n    model_remediation.reset_remediation_cache()\\n    try:\\n        connected_model = ChatOpenAI(responses=[\\\"unused\\\"])\\n        agent = AgentComponent()\\n        agent.model = connected_model\\n        agent.input_value = \\\"hi\\\"\\n        agent.system_prompt = \\\"\\\"\\n        agent.tools = [MagicMock(name=\\\"tool\\\")]\\n        agent.add_current_date_tool = False\\n        agent.add_calculator_tool = False\\n        agent.output_schema = [{\\\"name\\\": \\\"answer\\\", \\\"type\\\": \\\"str\\\", \\\"multiple\\\": False}]\\n        agent.format_instructions = \\\"\\\"\\n        _attach_connected_model_source(agent, \\\"OpenAI\\\")\\n        seen_values: list[bool] = []\\n        tool_effects: list[str] = []\\n\\n        async def run_agent(_agent):\\n            assert agent.llm is connected_model\\n            seen_values.append(connected_model.use_responses_api)\\n            if not connected_model.use_responses_api:\\n                raise GPT56_RESPONSES_API_ERROR\\n            tool_effects.append(\\\"executed\\\")\\n            return Message(text='{\\\"answer\\\": \\\"ok\\\"}')\\n\\n        mocked_run_agent = AsyncMock(side_effect=run_agent)\\n        mocked_create_agent = MagicMock()\\n        with (\\n            patch.object(model_remediation, \\\"remember\\\") as remember,\\n            patch.object(\\n                AgentComponent,\\n                \\\"get_memory_data\\\",\\n                new=AsyncMock(return_value=[]),\\n            ),\\n            patch.object(AgentComponent, \\\"create_agent_runnable\\\", new=mocked_create_agent),\\n            patch.object(AgentComponent, \\\"run_agent\\\", new=mocked_run_agent),\\n        ):\\n            result = await agent.json_response()\\n\\n        assert result.data == {\\\"answer\\\": \\\"ok\\\"}\\n        assert seen_values == [False, True]\\n        assert tool_effects == [\\\"executed\\\"]\\n        assert mocked_run_agent.await_count == 2\\n        assert mocked_create_agent.call_args_list == [\\n            call(allow_interrupts=False),\\n            call(allow_interrupts=False),\\n        ]\\n        remember.assert_not_called()\\n        assert model_remediation.cached_overrides(\\\"OpenAI\\\", \\\"gpt-5.6-luna\\\") == {}\\n    finally:\\n        model_remediation.reset_remediation_cache()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/models_and_agents/test_job_checkpoint_saver.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9d4027c204c513743e59d248f770b39215e49afc864fcf37c37d0e6fd9abb14b\",\"content\":\"\\\"\\\"\\\"LE-1447 Slice 2: durable agent checkpoint saver round-trip.\\n\\nA scripted tool-calling model requests a gated tool (pause), the paused thread is\\nserialized into a plain blob store via msgpack\u2192base64\u2192JSON, a FRESH saver is rebuilt\\nfrom that blob alone, and `Command(resume=approve)` runs the gated tool to completion.\\nNo mocks of the serializer \u2014 the `__interrupt__` write is non-JSON and must survive.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport sys\\n\\nimport pytest\\nfrom langchain.agents import create_agent\\nfrom langchain.agents.middleware import HumanInTheLoopMiddleware\\nfrom langchain_core.language_models import BaseChatModel\\nfrom langchain_core.messages import AIMessage, ToolMessage\\nfrom langchain_core.outputs import ChatGeneration, ChatResult\\nfrom langchain_core.tools import tool\\nfrom langgraph.types import Command\\nfrom lfx.components.models_and_agents.agent_helpers.job_checkpoint_saver import (\\n    JobCheckpointSaver,\\n)\\n\\n\\n@tool\\ndef transfer_money(amount: int) -> str:\\n    \\\"\\\"\\\"Transfer money (gated tool).\\\"\\\"\\\"\\n    return f\\\"transferred {amount}\\\"\\n\\n\\nclass ScriptedModel(BaseChatModel):\\n    \\\"\\\"\\\"Request the gated tool until a tool result exists, then answer.\\\"\\\"\\\"\\n\\n    @property\\n    def _llm_type(self) -> str:\\n        return \\\"scripted\\\"\\n\\n    def bind_tools(self, tools, **kwargs):  # noqa: ARG002\\n        return self\\n\\n    def _generate(self, messages, stop=None, run_manager=None, **kwargs):  # noqa: ARG002\\n        answered = any(isinstance(m, ToolMessage) for m in messages)\\n        msg = (\\n            AIMessage(content=\\\"Done \u2014 transferred.\\\")\\n            if answered\\n            else AIMessage(\\n                content=\\\"\\\",\\n                tool_calls=[{\\\"name\\\": \\\"transfer_money\\\", \\\"args\\\": {\\\"amount\\\": 200}, \\\"id\\\": \\\"call_1\\\"}],\\n            )\\n        )\\n        return ChatResult(generations=[ChatGeneration(message=msg)])\\n\\n\\ndef _store():\\n    blobs: dict[tuple[str, str], str] = {}\\n\\n    async def save_blob(job_id: str, kind: str, blob: str) -> None:\\n        blobs[(job_id, kind)] = blob\\n\\n    async def load_blob(job_id: str, kind: str) -> str | None:\\n        return blobs.get((job_id, kind))\\n\\n    return blobs, save_blob, load_blob\\n\\n\\ndef _agent(saver):\\n    return create_agent(\\n        model=ScriptedModel(),\\n        tools=[transfer_money],\\n        system_prompt=\\\"Use the tool.\\\",\\n        middleware=[HumanInTheLoopMiddleware(interrupt_on={\\\"transfer_money\\\": True})],\\n        checkpointer=saver,\\n    )\\n\\n\\n# langgraph's interrupt() reads get_config(), which is only populated inside the node when langgraph\\n# runs it via asyncio.create_task(context=...) \u2014 gated on ASYNCIO_ACCEPTS_CONTEXT (Python >= 3.11).\\n# On 3.10 the config ContextVar is never set, so any HITL interrupt raises \\\"Called get_config outside\\n# of a runnable context\\\" (confirmed on langgraph 1.1.10 and 1.2.6). The durable-saver round trip needs\\n# a real interrupt, so it can only run on 3.11+; the blob serde itself is exercised version-agnostically\\n# by test_durable_saver_async_only.\\n@pytest.mark.skipif(\\n    sys.version_info < (3, 11),\\n    reason=\\\"langgraph HITL interrupt() needs asyncio create_task context= (Python 3.11+)\\\",\\n)\\n@pytest.mark.asyncio\\nasync def test_durable_saver_round_trip_pauses_persists_and_resumes() -> None:\\n    blobs, save_blob, load_blob = _store()\\n    config = {\\\"configurable\\\": {\\\"thread_id\\\": \\\"job-1\\\"}}\\n\\n    # Run 1: pauses at the gated tool; the paused thread is persisted to the blob store.\\n    saver = JobCheckpointSaver(\\\"job-1\\\", save_blob, load_blob)\\n    async for _ in _agent(saver).astream_events({\\\"messages\\\": [(\\\"user\\\", \\\"send 200\\\")]}, version=\\\"v2\\\", config=config):\\n        pass\\n\\n    assert (\\\"job-1\\\", \\\"agent\\\") in blobs, \\\"paused thread was not persisted\\\"\\n\\n    # Rebuild a FRESH saver from the stored blob alone (simulates a restart).\\n    saver2 = JobCheckpointSaver(\\\"job-1\\\", save_blob, load_blob)\\n    restored = await saver2.aget_tuple(config)\\n    assert restored is not None\\n    assert any(channel == \\\"__interrupt__\\\" for _task, channel, _value in restored.pending_writes)\\n\\n    # Resume approve on the rebuilt thread \u2192 the gated tool runs and the run completes.\\n    agent2 = _agent(saver2)\\n    async for _ in agent2.astream_events(\\n        Command(resume={\\\"decisions\\\": [{\\\"type\\\": \\\"approve\\\"}]}), version=\\\"v2\\\", config=config\\n    ):\\n        pass\\n\\n    final = await agent2.aget_state(config)\\n    messages = final.values.get(\\\"messages\\\", [])\\n    assert any(isinstance(m, ToolMessage) and \\\"transferred 200\\\" in m.content for m in messages)\\n    assert any(isinstance(m, AIMessage) and \\\"Done\\\" in m.content for m in messages)\\n    assert not final.interrupts\\n\\n\\n@pytest.mark.asyncio\\nasync def test_durable_saver_async_only() -> None:\\n    _blobs, save_blob, load_blob = _store()\\n    saver = JobCheckpointSaver(\\\"job-1\\\", save_blob, load_blob)\\n    with pytest.raises(NotImplementedError):\\n        saver.get_tuple({\\\"configurable\\\": {\\\"thread_id\\\": \\\"job-1\\\"}})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/models_and_agents/test_model_selection_overrides.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e5d3a51bcb901a9f36ca170057abfb0c1dafe74fa4fd370ba8c861ea4cc233ff\",\"content\":\"from __future__ import annotations\\n\\nfrom unittest.mock import patch\\n\\n\\ndef _openai_language_selection() -> list[dict]:\\n    return [\\n        {\\n            \\\"name\\\": \\\"gpt-4o\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\n                \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                \\\"model_name_param\\\": \\\"model\\\",\\n            },\\n        }\\n    ]\\n\\n\\ndef _openai_embedding_selection() -> list[dict]:\\n    return [\\n        {\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n                \\\"param_mapping\\\": {\\n                    \\\"model\\\": \\\"model\\\",\\n                },\\n                \\\"model_type\\\": \\\"embeddings\\\",\\n            },\\n        }\\n    ]\\n\\n\\ndef test_language_model_override_fields_accept_literals_by_default() -> None:\\n    from lfx.components.models_and_agents.language_model import LanguageModelComponent\\n\\n    inputs = {component_input.name: component_input for component_input in LanguageModelComponent.inputs}\\n\\n    assert inputs[\\\"model\\\"].field_type.value == \\\"model\\\"\\n    assert inputs[\\\"model_name\\\"].field_type.value == \\\"str\\\"\\n    assert inputs[\\\"model_name\\\"].load_from_db is False\\n    assert inputs[\\\"provider\\\"].field_type.value == \\\"str\\\"\\n    assert inputs[\\\"provider\\\"].load_from_db is False\\n\\n\\ndef test_language_model_uses_model_name_override_before_building_llm() -> None:\\n    from lfx.components.models_and_agents import language_model as language_model_module\\n    from lfx.components.models_and_agents.language_model import LanguageModelComponent\\n\\n    component = LanguageModelComponent()\\n    component.set_attributes(\\n        {\\n            \\\"model\\\": _openai_language_selection(),\\n            \\\"model_name\\\": \\\"gpt-4o-mini\\\",\\n            \\\"provider\\\": \\\"\\\",\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"temperature\\\": 0.1,\\n            \\\"stream\\\": False,\\n            \\\"max_tokens\\\": None,\\n            \\\"base_url_ibm_watsonx\\\": None,\\n            \\\"project_id\\\": None,\\n            \\\"ollama_base_url\\\": None,\\n        }\\n    )\\n\\n    override_option = {\\n        **_openai_language_selection()[0],\\n        \\\"name\\\": \\\"gpt-4o-mini\\\",\\n    }\\n    with (\\n        patch.object(\\n            language_model_module, \\\"get_language_model_options\\\", return_value=[override_option]\\n        ) as mock_get_options,\\n        patch.object(language_model_module, \\\"get_llm\\\", return_value=object()) as mock_get_llm,\\n    ):\\n        component.build_model()\\n\\n    mock_get_options.assert_called_once_with(user_id=component.user_id)\\n    model_arg = mock_get_llm.call_args.kwargs[\\\"model\\\"]\\n    assert model_arg == [override_option]\\n\\n\\ndef test_language_model_provider_override_drops_stale_metadata_when_option_lookup_misses() -> None:\\n    from lfx.components.models_and_agents import language_model as language_model_module\\n    from lfx.components.models_and_agents.language_model import LanguageModelComponent\\n\\n    component = LanguageModelComponent()\\n    component.set_attributes(\\n        {\\n            \\\"model\\\": _openai_language_selection(),\\n            \\\"model_name\\\": \\\"claude-3-5-sonnet-latest\\\",\\n            \\\"provider\\\": \\\"Anthropic\\\",\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"temperature\\\": 0.1,\\n            \\\"stream\\\": False,\\n            \\\"max_tokens\\\": None,\\n            \\\"base_url_ibm_watsonx\\\": None,\\n            \\\"project_id\\\": None,\\n            \\\"ollama_base_url\\\": None,\\n        }\\n    )\\n\\n    with (\\n        patch.object(language_model_module, \\\"get_language_model_options\\\", return_value=[]) as mock_get_options,\\n        patch.object(language_model_module, \\\"get_llm\\\", return_value=object()) as mock_get_llm,\\n    ):\\n        component.build_model()\\n\\n    mock_get_options.assert_called_once_with(user_id=component.user_id)\\n    model_arg = mock_get_llm.call_args.kwargs[\\\"model\\\"]\\n    assert model_arg == [\\n        {\\n            \\\"metadata\\\": {},\\n            \\\"name\\\": \\\"claude-3-5-sonnet-latest\\\",\\n            \\\"provider\\\": \\\"Anthropic\\\",\\n            \\\"category\\\": \\\"Anthropic\\\",\\n        }\\n    ]\\n\\n\\ndef test_embedding_model_override_fields_accept_literals_by_default() -> None:\\n    from lfx.components.models_and_agents.embedding_model import EmbeddingModelComponent\\n\\n    inputs = {component_input.name: component_input for component_input in EmbeddingModelComponent.inputs}\\n\\n    assert inputs[\\\"model\\\"].field_type.value == \\\"model\\\"\\n    assert inputs[\\\"model_name\\\"].field_type.value == \\\"str\\\"\\n    assert inputs[\\\"model_name\\\"].load_from_db is False\\n    assert inputs[\\\"provider\\\"].field_type.value == \\\"str\\\"\\n    assert inputs[\\\"provider\\\"].load_from_db is False\\n\\n\\ndef test_embedding_model_uses_model_name_override_before_building_embeddings() -> None:\\n    from lfx.components.models_and_agents import embedding_model as embedding_model_module\\n    from lfx.components.models_and_agents.embedding_model import EmbeddingModelComponent\\n\\n    component = EmbeddingModelComponent()\\n    component.set_attributes(\\n        {\\n            \\\"model\\\": _openai_embedding_selection(),\\n            \\\"model_name\\\": \\\"text-embedding-3-large\\\",\\n            \\\"provider\\\": \\\"\\\",\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"api_base\\\": \\\"\\\",\\n            \\\"dimensions\\\": None,\\n            \\\"chunk_size\\\": 1000,\\n            \\\"request_timeout\\\": None,\\n            \\\"max_retries\\\": 3,\\n            \\\"show_progress_bar\\\": False,\\n            \\\"model_kwargs\\\": {},\\n            \\\"base_url_ibm_watsonx\\\": None,\\n            \\\"project_id\\\": \\\"\\\",\\n            \\\"truncate_input_tokens\\\": None,\\n            \\\"input_text\\\": True,\\n            \\\"ollama_base_url\\\": None,\\n        }\\n    )\\n\\n    override_option = {\\n        **_openai_embedding_selection()[0],\\n        \\\"name\\\": \\\"text-embedding-3-large\\\",\\n    }\\n    with (\\n        patch.object(\\n            embedding_model_module, \\\"get_embedding_model_options\\\", return_value=[override_option]\\n        ) as mock_get_options,\\n        patch.object(embedding_model_module, \\\"get_embeddings\\\", return_value=object()) as mock_get_embeddings,\\n    ):\\n        component.build_embeddings()\\n\\n    mock_get_options.assert_called_once_with(user_id=component.user_id)\\n    model_arg = mock_get_embeddings.call_args.kwargs[\\\"model\\\"]\\n    assert model_arg == [override_option]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_bundle_shims.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f4b34a0e980e1393f8d19ee7a34868271f73c1e6c48ac084dace2a594dd3af61\",\"content\":\"\\\"\\\"\\\"Contract tests for the lfx-bundles import shims under ``lfx/components/``.\\n\\nProviders consolidated into the lfx-bundles metapackage (and partners\\ngraduated to standalone ``lfx-<provider>`` distributions) leave a one-file\\nmodule-aliasing shim at their old in-tree location.  The shim contract,\\nlocked here:\\n\\n  1. First line is the ``# lfx-bundles-shim`` marker -- the in-tree component\\n     walk (:func:`lfx.interface.components._discover_shimmed_component_dirs`)\\n     keys on it to avoid double registration.\\n  2. The shim dir contains exactly one ``.py`` file (no implementations, no\\n     third-party deps) -- this is how \\\"lfx ships no components\\\" coexists with\\n     working legacy imports.\\n  3. ``sys.modules[__name__]`` is aliased to the bundle package (module\\n     aliasing, not star-import, so submodule trees resolve).\\n  4. When the bundle distribution itself is missing, the shim raises an\\n     actionable ``ModuleNotFoundError`` naming exactly what to install --\\n     the WORDING IS PART OF THE CONTRACT (docs reference it).\\n  5. A missing *transitive* dependency (bundle present, SDK absent) is\\n     re-raised untouched so a real bug is never misreported as \\\"install\\n     missing\\\".\\n\\nThe mechanism tests run against a synthetic shim + synthetic target so they\\nare hermetic; the source-level tests sweep every real shim without importing\\nit (env-independent); one adaptive live test exercises whichever branch the\\ncurrent environment is in.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport builtins\\nimport importlib\\nimport importlib.util\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n# tests/unit/components/<this file> -> parents[3] = the src/lfx package root.\\nCOMPONENTS_DIR = Path(__file__).resolve().parents[3] / \\\"src\\\" / \\\"lfx\\\" / \\\"components\\\"\\nSHIM_MARKER = \\\"# lfx-bundles-shim\\\"\\n\\n# The two install-message shapes the shims are allowed to emit.\\n_METAPACKAGE_MSG = \\\"Install it with: pip install lfx-bundles.\\\"\\n_PARTNER_MSG_PREFIX = \\\"pip install lfx-\\\"\\n\\n\\ndef _shim_dirs() -> list[Path]:\\n    \\\"\\\"\\\"Every provider dir under lfx/components whose __init__ carries the marker.\\\"\\\"\\\"\\n    found = []\\n    for child in sorted(COMPONENTS_DIR.iterdir()):\\n        init_py = child / \\\"__init__.py\\\"\\n        if child.is_dir() and init_py.is_file():\\n            try:\\n                head = init_py.read_text(encoding=\\\"utf-8\\\").lstrip()\\n            except OSError:\\n                continue\\n            if head.startswith(SHIM_MARKER):\\n                found.append(child)\\n    return found\\n\\n\\nSHIM_DIRS = _shim_dirs()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Source-level contract sweep (no imports; env-independent)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shims_exist() -> None:\\n    \\\"\\\"\\\"The consolidation left shims behind; an empty list means the sweep is broken.\\\"\\\"\\\"\\n    assert SHIM_DIRS, f\\\"no marker shims found under {COMPONENTS_DIR}\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"shim_dir\\\", SHIM_DIRS, ids=lambda p: p.name)\\ndef test_shim_is_one_file_stub(shim_dir: Path) -> None:\\n    \\\"\\\"\\\"Contract #2: a shim dir ships exactly one .py file and no subpackages.\\\"\\\"\\\"\\n    py_files = list(shim_dir.rglob(\\\"*.py\\\"))\\n    assert py_files == [shim_dir / \\\"__init__.py\\\"], (\\n        f\\\"{shim_dir.name}: shim dir must contain exactly __init__.py, found {py_files}\\\"\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"shim_dir\\\", SHIM_DIRS, ids=lambda p: p.name)\\ndef test_shim_source_contract(shim_dir: Path) -> None:\\n    \\\"\\\"\\\"Contracts #1, #3, #4 at the source level, for every real shim.\\n\\n    The alias target must be ``lfx_bundles.<provider>`` (metapackage) or\\n    ``lfx_<provider>.components.<provider>`` (graduated partner), the\\n    name-check must guard the matching top-level package, and the install\\n    message must name the matching distribution.\\n    \\\"\\\"\\\"\\n    provider = shim_dir.name\\n    # Bundle names are lowercase (BUNDLE_NAME_RE), so a mixed-case in-tree dir\\n    # (e.g. FAISS, Notion) aliases to its lowercased bundle (faiss, notion).\\n    # A few dirs are cross-bundle shims: their lone component lives in a\\n    # differently-named bundle (e.g. vectorstores' LocalDBComponent is\\n    # Chroma-backed, so it aliases the ``chroma`` bundle).\\n    cross_bundle = {\\\"vectorstores\\\": \\\"chroma\\\"}\\n    slug = cross_bundle.get(provider, provider.lower())\\n    src = (shim_dir / \\\"__init__.py\\\").read_text(encoding=\\\"utf-8\\\")\\n\\n    assert src.startswith(SHIM_MARKER), f\\\"{provider}: first line must be the {SHIM_MARKER!r} marker\\\"\\n    assert \\\"sys.modules[__name__] = importlib.import_module(\\\" in src, f\\\"{provider}: must module-alias\\\"\\n\\n    meta_target = f'importlib.import_module(\\\"lfx_bundles.{slug}\\\")'\\n    partner_target = f'importlib.import_module(\\\"lfx_{slug}.components.{slug}\\\")'\\n    is_meta = meta_target in src\\n    is_partner = partner_target in src\\n    assert is_meta or is_partner, f\\\"{provider}: alias target is neither metapackage nor partner shape\\\"\\n\\n    if is_meta:\\n        assert 'exc.name == \\\"lfx_bundles\\\"' in src, f\\\"{provider}: name-check must guard lfx_bundles\\\"\\n        assert _METAPACKAGE_MSG in src, f\\\"{provider}: locked install message missing ({_METAPACKAGE_MSG!r})\\\"\\n    else:\\n        assert f'exc.name == \\\"lfx_{slug}\\\"' in src, f\\\"{provider}: name-check must guard lfx_{slug}\\\"\\n        assert f\\\"{_PARTNER_MSG_PREFIX}{slug}\\\" in src, (\\n            f\\\"{provider}: locked install message missing ('pip install lfx-{slug}')\\\"\\n        )\\n    # Contract #5: anything other than the bundle-missing case re-raises.\\n    assert src.rstrip().endswith(\\\"raise\\\"), f\\\"{provider}: must re-raise non-bundle import errors untouched\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# lfx.base shims (shared-base trees moved with their bundle, e.g. datastax)\\n# ---------------------------------------------------------------------------\\n\\nBASE_PKG_DIR = COMPONENTS_DIR.parent / \\\"base\\\"\\n\\n\\ndef _base_shim_dirs() -> list[Path]:\\n    \\\"\\\"\\\"Every dir under lfx/base whose __init__ carries the shim marker.\\\"\\\"\\\"\\n    found = []\\n    for child in sorted(BASE_PKG_DIR.iterdir()):\\n        init_py = child / \\\"__init__.py\\\"\\n        if child.is_dir() and init_py.is_file():\\n            try:\\n                head = init_py.read_text(encoding=\\\"utf-8\\\").lstrip()\\n            except OSError:\\n                continue\\n            if head.startswith(SHIM_MARKER):\\n                found.append(child)\\n    return found\\n\\n\\nBASE_SHIM_DIRS = _base_shim_dirs()\\n\\n\\ndef test_base_shims_exist() -> None:\\n    \\\"\\\"\\\"The datastax graduation moved lfx.base.datastax; its shim must exist.\\n\\n    Stored flow code fields (starter projects, saved user flows) embed\\n    ``from lfx.base.datastax... import ...`` and are re-executed verbatim\\n    at build time, so moved base trees need shims exactly like moved\\n    component trees do.\\n    \\\"\\\"\\\"\\n    assert BASE_SHIM_DIRS, f\\\"no marker shims found under {BASE_PKG_DIR}\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"shim_dir\\\", BASE_SHIM_DIRS, ids=lambda p: p.name)\\ndef test_base_shim_is_one_file_stub(shim_dir: Path) -> None:\\n    py_files = list(shim_dir.rglob(\\\"*.py\\\"))\\n    assert py_files == [shim_dir / \\\"__init__.py\\\"], (\\n        f\\\"{shim_dir.name}: base shim dir must contain exactly __init__.py, found {py_files}\\\"\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"shim_dir\\\", BASE_SHIM_DIRS, ids=lambda p: p.name)\\ndef test_base_shim_source_contract(shim_dir: Path) -> None:\\n    \\\"\\\"\\\"Base shims alias to the bundle's base subpackage with the same guards.\\\"\\\"\\\"\\n    provider = shim_dir.name\\n    src = (shim_dir / \\\"__init__.py\\\").read_text(encoding=\\\"utf-8\\\")\\n\\n    assert src.startswith(SHIM_MARKER), f\\\"{provider}: first line must be the {SHIM_MARKER!r} marker\\\"\\n    assert \\\"sys.modules[__name__] = importlib.import_module(\\\" in src, f\\\"{provider}: must module-alias\\\"\\n\\n    meta_target = f'importlib.import_module(\\\"lfx_bundles.{provider}.base\\\")'\\n    partner_target = f'importlib.import_module(\\\"lfx_{provider}.base\\\")'\\n    is_meta = meta_target in src\\n    is_partner = partner_target in src\\n    assert is_meta or is_partner, f\\\"{provider}: alias target is neither metapackage nor partner base shape\\\"\\n\\n    if is_meta:\\n        assert 'exc.name == \\\"lfx_bundles\\\"' in src, f\\\"{provider}: name-check must guard lfx_bundles\\\"\\n        assert _METAPACKAGE_MSG in src, f\\\"{provider}: locked install message missing ({_METAPACKAGE_MSG!r})\\\"\\n    else:\\n        assert f'exc.name == \\\"lfx_{provider}\\\"' in src, f\\\"{provider}: name-check must guard lfx_{provider}\\\"\\n        assert f\\\"{_PARTNER_MSG_PREFIX}{provider}\\\" in src, (\\n            f\\\"{provider}: locked install message missing ('pip install lfx-{provider}')\\\"\\n        )\\n    assert src.rstrip().endswith(\\\"raise\\\"), f\\\"{provider}: must re-raise non-bundle import errors untouched\\\"\\n\\n\\ndef test_walk_skip_detects_every_shim() -> None:\\n    \\\"\\\"\\\"The in-tree walk's shim detector and the marker sweep agree exactly.\\\"\\\"\\\"\\n    from lfx.interface.components import _discover_shimmed_component_dirs\\n\\n    detected = _discover_shimmed_component_dirs([str(COMPONENTS_DIR)])\\n    assert detected == {d.name for d in SHIM_DIRS}\\n\\n\\ndef test_component_walk_skip_includes_compat_shims() -> None:\\n    \\\"\\\"\\\"Compatibility-only packages stay importable but do not become palette categories.\\\"\\\"\\\"\\n    from lfx.interface.components import _discover_component_skip_dirs\\n\\n    detected = _discover_component_skip_dirs([str(COMPONENTS_DIR)])\\n    assert {d.name for d in SHIM_DIRS}.issubset(detected)\\n    assert \\\"knowledge_bases\\\" in detected\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"shim\\\", \\\"extension_package\\\", \\\"import_style\\\"),\\n    [\\n        pytest.param(COMPONENTS_DIR / \\\"cassandra\\\" / \\\"__init__.py\\\", \\\"lfx_datastax\\\", \\\"importlib\\\", id=\\\"cassandra\\\"),\\n        pytest.param(\\n            COMPONENTS_DIR / \\\"models_and_agents\\\" / \\\"policies\\\" / \\\"__init__.py\\\",\\n            \\\"lfx_toolguard\\\",\\n            \\\"importlib\\\",\\n            id=\\\"policies-helpers\\\",\\n        ),\\n        pytest.param(\\n            COMPONENTS_DIR / \\\"models_and_agents\\\" / \\\"policies_component.py\\\",\\n            \\\"lfx_toolguard\\\",\\n            \\\"builtin\\\",\\n            id=\\\"policies-component\\\",\\n        ),\\n    ],\\n)\\ndef test_compat_shims_preserve_transitive_import_errors(\\n    shim: Path,\\n    extension_package: str,\\n    import_style: str,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"A broken extension install must not be misreported as an absent extension.\\\"\\\"\\\"\\n    missing_dependency = \\\"extension_runtime_dependency\\\"\\n\\n    def _raise_transitive_import_error(_name: str):\\n        message = f\\\"No module named '{missing_dependency}'\\\"\\n        raise ModuleNotFoundError(message, name=missing_dependency)\\n\\n    if import_style == \\\"importlib\\\":\\n        monkeypatch.setattr(importlib, \\\"import_module\\\", _raise_transitive_import_error)\\n    else:\\n        original_import = builtins.__import__\\n\\n        def _import_with_transitive_error(name: str, *args, **kwargs):\\n            if name.partition(\\\".\\\")[0] == extension_package:\\n                _raise_transitive_import_error(name)\\n            return original_import(name, *args, **kwargs)\\n\\n        monkeypatch.setattr(builtins, \\\"__import__\\\", _import_with_transitive_error)\\n\\n    with pytest.raises(ModuleNotFoundError, match=missing_dependency) as exc_info:\\n        _import_file_as(f\\\"synthetic_compat_{shim.parent.name}\\\", shim)\\n\\n    assert exc_info.value.name == missing_dependency\\n\\n\\n# ---------------------------------------------------------------------------\\n# Mechanism tests against a synthetic shim (hermetic)\\n# ---------------------------------------------------------------------------\\n\\n_SYNTHETIC_SHIM = '''# lfx-bundles-shim\\n\\\"\\\"\\\"Synthetic shim used by the contract tests.\\\"\\\"\\\"\\n\\nimport importlib\\nimport sys\\n\\ntry:\\n    sys.modules[__name__] = importlib.import_module(\\\"fake_lfx_target.alpha\\\")\\nexcept ModuleNotFoundError as exc:\\n    if exc.name is not None and (exc.name == \\\"fake_lfx_target\\\" or exc.name.startswith(\\\"fake_lfx_target.\\\")):\\n        msg = (\\n            \\\"The 'alpha' components moved to the 'fake-lfx-target' distribution. \\\"\\n            \\\"Install it with: pip install fake-lfx-target\\\"\\n        )\\n        raise ModuleNotFoundError(msg, name=\\\"fake_lfx_target\\\") from exc\\n    raise\\n'''\\n\\n\\ndef _import_file_as(name: str, path: Path):\\n    \\\"\\\"\\\"Import ``path`` under module name ``name`` (and clean up afterwards).\\\"\\\"\\\"\\n    spec = importlib.util.spec_from_file_location(name, path)\\n    module = importlib.util.module_from_spec(spec)\\n    sys.modules[name] = module\\n    try:\\n        spec.loader.exec_module(module)\\n    except BaseException:\\n        sys.modules.pop(name, None)\\n        raise\\n    # Module aliasing replaces the sys.modules entry; return what's installed.\\n    return sys.modules[name]\\n\\n\\n@pytest.fixture\\ndef synthetic_shim(tmp_path: Path):\\n    \\\"\\\"\\\"A synthetic shim file + cleanup of every module this test family installs.\\\"\\\"\\\"\\n    shim_file = tmp_path / \\\"shim\\\" / \\\"__init__.py\\\"\\n    shim_file.parent.mkdir()\\n    shim_file.write_text(_SYNTHETIC_SHIM, encoding=\\\"utf-8\\\")\\n    yield shim_file\\n    for mod in [m for m in sys.modules if m.startswith((\\\"fake_lfx_target\\\", \\\"synthetic_shim_\\\"))]:\\n        sys.modules.pop(mod, None)\\n\\n\\ndef test_alias_resolves_when_target_installed(synthetic_shim: Path, tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"Contract #3: with the bundle present, the shim IS the target module.\\\"\\\"\\\"\\n    target = tmp_path / \\\"fake_lfx_target\\\" / \\\"alpha\\\"\\n    target.mkdir(parents=True)\\n    (tmp_path / \\\"fake_lfx_target\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (target / \\\"__init__.py\\\").write_text(\\\"class AlphaComponent:\\\\n    pass\\\\n\\\", encoding=\\\"utf-8\\\")\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n\\n    module = _import_file_as(\\\"synthetic_shim_present\\\", synthetic_shim)\\n    assert module.__name__ == \\\"fake_lfx_target.alpha\\\"  # aliased, not the shim itself\\n    assert module.AlphaComponent.__name__ == \\\"AlphaComponent\\\"\\n\\n\\ndef test_locked_message_when_bundle_missing(synthetic_shim: Path) -> None:\\n    \\\"\\\"\\\"Contract #4: bundle absent -> actionable ModuleNotFoundError, locked wording.\\\"\\\"\\\"\\n    with pytest.raises(ModuleNotFoundError) as excinfo:\\n        _import_file_as(\\\"synthetic_shim_missing\\\", synthetic_shim)\\n    assert excinfo.value.name == \\\"fake_lfx_target\\\"\\n    assert \\\"pip install fake-lfx-target\\\" in str(excinfo.value)\\n    # The original import failure is chained for debugging.\\n    assert isinstance(excinfo.value.__cause__, ModuleNotFoundError)\\n\\n\\ndef test_transitive_dep_error_reraised_untouched(synthetic_shim: Path, tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"Contract #5: bundle present but its SDK missing -> the REAL error surfaces.\\\"\\\"\\\"\\n    target = tmp_path / \\\"fake_lfx_target\\\" / \\\"alpha\\\"\\n    target.mkdir(parents=True)\\n    (tmp_path / \\\"fake_lfx_target\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (target / \\\"__init__.py\\\").write_text(\\\"import some_missing_sdk\\\\n\\\", encoding=\\\"utf-8\\\")\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n\\n    with pytest.raises(ModuleNotFoundError) as excinfo:\\n        _import_file_as(\\\"synthetic_shim_transitive\\\", synthetic_shim)\\n    assert excinfo.value.name == \\\"some_missing_sdk\\\"  # NOT rewritten to the install message\\n    assert \\\"pip install fake-lfx-target\\\" not in str(excinfo.value)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Adaptive live test against a real shim (exercises whichever env we're in)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_real_metapackage_shim_live() -> None:\\n    \\\"\\\"\\\"In a bundle-installed env the alias works; bare-engine gets the locked message.\\\"\\\"\\\"\\n    bundle_installed = importlib.util.find_spec(\\\"lfx_bundles\\\") is not None\\n    if bundle_installed:\\n        module = importlib.import_module(\\\"lfx.components.tavily\\\")\\n        assert module.__name__ == \\\"lfx_bundles.tavily\\\"\\n        assert hasattr(module, \\\"TavilySearchComponent\\\")\\n    else:\\n        with pytest.raises(ModuleNotFoundError, match=\\\"pip install lfx-bundles\\\"):\\n            importlib.import_module(\\\"lfx.components.tavily\\\")\\n        sys.modules.pop(\\\"lfx.components.tavily\\\", None)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_chat_litellm_model_provider_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"175e5c38f9499bc4134e6f78da2ebad9df7c87daaa34a36c2479d37b7671fcb1\",\"content\":\"from types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, Mock\\n\\nimport pytest\\nfrom lfx.components.deactivated.chat_litellm_model import ChatLiteLLMModelComponent\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n\\nclass _UnhydratedSecret:\\n    def __bool__(self) -> bool:\\n        raise AssertionError\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"provider\\\", \\\"provider_id\\\"),\\n    [(\\\"OpenAI\\\", \\\"openai\\\"), (\\\"Azure\\\", \\\"azure-openai\\\")],\\n)\\n@pytest.mark.parametrize(\\n    \\\"purpose\\\",\\n    [ModelProviderPolicyPurpose.CONFIGURE, ModelProviderPolicyPurpose.USE],\\n)\\nasync def test_saved_litellm_uses_raw_selected_provider_before_secret_hydration(\\n    monkeypatch,\\n    purpose,\\n    provider,\\n    provider_id,\\n) -> None:\\n    component = ChatLiteLLMModelComponent(_user_id=\\\"resource-owner\\\")\\n    denial = ModelProviderPolicyError(provider_id, purpose)\\n    snapshot = SimpleNamespace(require=Mock(side_effect=denial))\\n    resolve_policy = AsyncMock(return_value=snapshot)\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await component.arequire_model_provider_policy(\\n            purpose,\\n            user_id=\\\"policy-actor\\\",\\n            parameters={\\n                \\\"provider\\\": provider,\\n                \\\"api_key\\\": _UnhydratedSecret(),\\n            },\\n        )\\n\\n    resolve_policy.assert_awaited_once_with(\\n        user_id=\\\"policy-actor\\\",\\n        providers=[provider_id],\\n        purpose=purpose,\\n    )\\n    snapshot.require.assert_called_once_with(provider_id)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_component_display_names.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b2317fd1fe256241004afcfc21b5056a209b8ed58ea345fb1cd38367a06f4c6\",\"content\":\"\\\"\\\"\\\"Tests that ALL component outputs and inputs use the new display names.\\n\\nValidates the Data->JSON and DataFrame->Table rename migration is complete\\nacross the entire component library. No component should still use the old\\ndisplay names \\\"Data\\\", \\\"DataFrame\\\", or \\\"Data or DataFrame\\\".\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nimport inspect\\nimport os\\nfrom pathlib import Path\\n\\nimport lfx.components\\n\\n# --- Named constants ---\\n\\nDEPRECATED_OUTPUT_DISPLAY_NAME_DATA = \\\"Data\\\"\\nDEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME = \\\"DataFrame\\\"\\nDEPRECATED_DISPLAY_NAME_DATA_OR_DATAFRAME = \\\"Data or DataFrame\\\"\\n\\nEXPECTED_DATA_REPLACEMENT = \\\"JSON\\\"\\nEXPECTED_DATAFRAME_REPLACEMENT = \\\"Table\\\"\\n\\nMINIMUM_EXPECTED_COMPONENTS = 20\\n\\n\\ndef _discover_all_component_classes() -> list[tuple[str, type]]:\\n    \\\"\\\"\\\"Discover all component classes from the lfx.components package.\\n\\n    Finds all .py files under lfx/components, imports them, and collects\\n    all classes that inherit from Component.\\n\\n    Returns:\\n        List of (fully_qualified_name, class) tuples.\\n    \\\"\\\"\\\"\\n    from lfx.custom.custom_component.component import Component\\n\\n    discovered: list[tuple[str, type]] = []\\n    components_pkg_path = Path(lfx.components.__path__[0])\\n    components_pkg_name = lfx.components.__name__\\n\\n    # Walk all .py files to discover component modules without relying\\n    # on pkgutil.walk_packages, which may trigger __init__.py __getattr__\\n    # and fail on components with missing optional dependencies.\\n    for root, _dirs, files in os.walk(components_pkg_path):\\n        for filename in files:\\n            if not filename.endswith(\\\".py\\\") or filename.startswith(\\\"_\\\"):\\n                continue\\n\\n            filepath = Path(root) / filename\\n            # Convert filesystem path to module path\\n            relative = filepath.relative_to(components_pkg_path)\\n            parts = list(relative.with_suffix(\\\"\\\").parts)\\n            module_name = f\\\"{components_pkg_name}.{'.'.join(parts)}\\\"\\n\\n            try:\\n                module = importlib.import_module(module_name)\\n            except Exception:  # noqa: S112 - intentionally skip modules with missing optional deps\\n                continue\\n\\n            for attr_name, attr_value in inspect.getmembers(module, inspect.isclass):\\n                if (\\n                    issubclass(attr_value, Component)\\n                    and attr_value is not Component\\n                    and attr_value.__module__ == module_name\\n                ):\\n                    qualified_name = f\\\"{module_name}.{attr_name}\\\"\\n                    discovered.append((qualified_name, attr_value))\\n\\n    return discovered\\n\\n\\ndef _get_output_display_names(component_class: type) -> list[tuple[str, str]]:\\n    \\\"\\\"\\\"Extract (output_name, display_name) pairs from a component class's outputs.\\n\\n    Returns:\\n        List of (output_name, display_name) tuples.\\n    \\\"\\\"\\\"\\n    outputs = getattr(component_class, \\\"outputs\\\", None)\\n    if not outputs:\\n        return []\\n\\n    results = []\\n    for output in outputs:\\n        display_name = getattr(output, \\\"display_name\\\", None)\\n        name = getattr(output, \\\"name\\\", \\\"unknown\\\")\\n        if display_name is not None:\\n            results.append((name, display_name))\\n    return results\\n\\n\\ndef _get_input_display_names(component_class: type) -> list[tuple[str, str]]:\\n    \\\"\\\"\\\"Extract (input_name, display_name) pairs from a component class's inputs.\\n\\n    Returns:\\n        List of (input_name, display_name) tuples.\\n    \\\"\\\"\\\"\\n    inputs = getattr(component_class, \\\"inputs\\\", None)\\n    if not inputs:\\n        return []\\n\\n    results = []\\n    for inp in inputs:\\n        display_name = getattr(inp, \\\"display_name\\\", None)\\n        name = getattr(inp, \\\"name\\\", \\\"unknown\\\")\\n        if display_name is not None:\\n            results.append((name, display_name))\\n    return results\\n\\n\\n# Discover all components once at module level for reuse across tests\\n_ALL_COMPONENTS = _discover_all_component_classes()\\n\\n\\nclass TestOutputDisplayNames:\\n    \\\"\\\"\\\"Validate that no component output uses deprecated display names.\\\"\\\"\\\"\\n\\n    def test_should_not_have_data_as_output_display_name(self):\\n        \\\"\\\"\\\"No component output should have display_name='Data'.\\n\\n        The correct display name after migration is 'JSON'.\\n        \\\"\\\"\\\"\\n        violations: list[str] = []\\n\\n        for qualified_name, component_class in _ALL_COMPONENTS:\\n            for output_name, display_name in _get_output_display_names(component_class):\\n                if display_name == DEPRECATED_OUTPUT_DISPLAY_NAME_DATA:\\n                    violations.append(\\n                        f\\\"{qualified_name} output '{output_name}' has \\\"\\n                        f\\\"display_name='{DEPRECATED_OUTPUT_DISPLAY_NAME_DATA}' \\\"\\n                        f\\\"(should be '{EXPECTED_DATA_REPLACEMENT}')\\\"\\n                    )\\n\\n        assert not violations, (\\n            f\\\"Found {len(violations)} output(s) still using deprecated \\\"\\n            f\\\"display_name='{DEPRECATED_OUTPUT_DISPLAY_NAME_DATA}':\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  - {v}\\\" for v in violations)\\n        )\\n\\n    def test_should_not_have_dataframe_as_output_display_name(self):\\n        \\\"\\\"\\\"No component output should have display_name='DataFrame'.\\n\\n        The correct display name after migration is 'Table'.\\n        \\\"\\\"\\\"\\n        violations: list[str] = []\\n\\n        for qualified_name, component_class in _ALL_COMPONENTS:\\n            for output_name, display_name in _get_output_display_names(component_class):\\n                if display_name == DEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME:\\n                    violations.append(\\n                        f\\\"{qualified_name} output '{output_name}' has \\\"\\n                        f\\\"display_name='{DEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME}' \\\"\\n                        f\\\"(should be '{EXPECTED_DATAFRAME_REPLACEMENT}')\\\"\\n                    )\\n\\n        assert not violations, (\\n            f\\\"Found {len(violations)} output(s) still using deprecated \\\"\\n            f\\\"display_name='{DEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME}':\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  - {v}\\\" for v in violations)\\n        )\\n\\n    def test_should_not_have_dataframe_as_input_display_name(self):\\n        \\\"\\\"\\\"No component input should have display_name='DataFrame'.\\n\\n        The correct display name after migration is 'Table'.\\n        \\\"\\\"\\\"\\n        violations: list[str] = []\\n\\n        for qualified_name, component_class in _ALL_COMPONENTS:\\n            for input_name, display_name in _get_input_display_names(component_class):\\n                if display_name == DEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME:\\n                    violations.append(\\n                        f\\\"{qualified_name} input '{input_name}' has \\\"\\n                        f\\\"display_name='{DEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME}' \\\"\\n                        f\\\"(should be '{EXPECTED_DATAFRAME_REPLACEMENT}')\\\"\\n                    )\\n\\n        assert not violations, (\\n            f\\\"Found {len(violations)} input(s) still using deprecated \\\"\\n            f\\\"display_name='{DEPRECATED_OUTPUT_DISPLAY_NAME_DATAFRAME}':\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  - {v}\\\" for v in violations)\\n        )\\n\\n    def test_should_not_have_data_or_dataframe_as_display_name(self):\\n        \\\"\\\"\\\"No component output or input should have display_name='Data or DataFrame'.\\\"\\\"\\\"\\n        violations: list[str] = []\\n\\n        for qualified_name, component_class in _ALL_COMPONENTS:\\n            for output_name, display_name in _get_output_display_names(component_class):\\n                if display_name == DEPRECATED_DISPLAY_NAME_DATA_OR_DATAFRAME:\\n                    violations.append(\\n                        f\\\"{qualified_name} output '{output_name}' has \\\"\\n                        f\\\"display_name='{DEPRECATED_DISPLAY_NAME_DATA_OR_DATAFRAME}'\\\"\\n                    )\\n\\n            for input_name, display_name in _get_input_display_names(component_class):\\n                if display_name == DEPRECATED_DISPLAY_NAME_DATA_OR_DATAFRAME:\\n                    violations.append(\\n                        f\\\"{qualified_name} input '{input_name}' has \\\"\\n                        f\\\"display_name='{DEPRECATED_DISPLAY_NAME_DATA_OR_DATAFRAME}'\\\"\\n                    )\\n\\n        assert not violations, (\\n            f\\\"Found {len(violations)} field(s) still using deprecated \\\"\\n            f\\\"display_name='{DEPRECATED_DISPLAY_NAME_DATA_OR_DATAFRAME}':\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  - {v}\\\" for v in violations)\\n        )\\n\\n\\nclass TestComponentDiscoverySanity:\\n    \\\"\\\"\\\"Sanity checks to ensure the test infrastructure itself is working.\\\"\\\"\\\"\\n\\n    def test_should_discover_a_minimum_number_of_components(self):\\n        \\\"\\\"\\\"Ensure we are actually scanning a meaningful number of components.\\n\\n        If this fails, it means the discovery mechanism is broken and the\\n        display name tests above are vacuously passing.\\n        \\\"\\\"\\\"\\n        assert len(_ALL_COMPONENTS) >= MINIMUM_EXPECTED_COMPONENTS, (\\n            f\\\"Only discovered {len(_ALL_COMPONENTS)} components, expected at least \\\"\\n            f\\\"{MINIMUM_EXPECTED_COMPONENTS}. Component discovery may be broken.\\\"\\n        )\\n\\n    def test_should_find_components_with_outputs(self):\\n        \\\"\\\"\\\"At least some discovered components should have outputs defined.\\\"\\\"\\\"\\n        components_with_outputs = [name for name, cls in _ALL_COMPONENTS if getattr(cls, \\\"outputs\\\", None)]\\n        assert len(components_with_outputs) > 0, \\\"No components with outputs found. Output inspection may be broken.\\\"\\n\\n    def test_should_find_components_with_inputs(self):\\n        \\\"\\\"\\\"At least some discovered components should have inputs defined.\\\"\\\"\\\"\\n        components_with_inputs = [name for name, cls in _ALL_COMPONENTS if getattr(cls, \\\"inputs\\\", None)]\\n        assert len(components_with_inputs) > 0, \\\"No components with inputs found. Input inspection may be broken.\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_core_component_imports.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"70675868f5444946e3f9444e2c6eb4d6ffbbe50ee3c03483aef29a1fc4876bd8\",\"content\":\"\\\"\\\"\\\"Import and dependency contracts for the built-in LFX component catalog.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport builtins\\nimport importlib\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\nimport tomli\\nfrom packaging.requirements import Requirement\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"module_name\\\", \\\"blocked_dependency\\\"),\\n    [\\n        (\\\"lfx.base.agents.crewai.crew\\\", \\\"litellm\\\"),\\n        (\\\"lfx.components.tools.calculator\\\", \\\"pytest\\\"),\\n    ],\\n)\\ndef test_core_modules_do_not_import_optional_or_test_dependencies(\\n    monkeypatch: pytest.MonkeyPatch,\\n    module_name: str,\\n    blocked_dependency: str,\\n) -> None:\\n    \\\"\\\"\\\"Core component modules must remain importable in a clean runtime install.\\\"\\\"\\\"\\n    real_import = builtins.__import__\\n\\n    def guarded_import(name, *args, **kwargs):\\n        if name == blocked_dependency or name.startswith(f\\\"{blocked_dependency}.\\\"):\\n            error_message = f\\\"No module named '{blocked_dependency}'\\\"\\n            raise ModuleNotFoundError(error_message, name=blocked_dependency)\\n        return real_import(name, *args, **kwargs)\\n\\n    monkeypatch.setattr(builtins, \\\"__import__\\\", guarded_import)\\n    sys.modules.pop(module_name, None)\\n\\n    importlib.import_module(module_name)\\n\\n\\ndef test_batch_run_toml_writer_is_a_direct_lfx_dependency() -> None:\\n    \\\"\\\"\\\"Batch Run is built in, so its TOML writer must be present in bare LFX.\\\"\\\"\\\"\\n    pyproject_path = Path(__file__).resolve().parents[3] / \\\"pyproject.toml\\\"\\n    pyproject = tomli.loads(pyproject_path.read_text(encoding=\\\"utf-8\\\"))\\n    requirements = [Requirement(value) for value in pyproject[\\\"project\\\"][\\\"dependencies\\\"]]\\n\\n    assert any(requirement.name == \\\"toml\\\" for requirement in requirements)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_legacy_alias_imports.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"876fbdf12e6646bade3b109559dfbe7d0cc02bfa890941b965c9c7d6eecfad6b\",\"content\":\"\\\"\\\"\\\"Regression tests for the legacy component alias modules.\\n\\n``lfx.components.helpers`` and ``lfx.components.logic`` are backwards-compatibility\\nshims: the components they advertise now live in ``utilities``, ``flow_controls`` and\\n``llm_operations``.  Forwarding used to be written as ``from lfx.components import\\nutilities``, which looks harmless but is not -- none of those three target modules is\\nregistered in ``lfx.components._dynamic_imports``, so the ``from ... import`` form falls\\nthrough to ``lfx.components.__getattr__``, which brute-force imports *every* registered\\nbundle module hunting for a name it can never find.\\n\\nThat turned a two-module forward into an eager import of the entire integration tail\\nduring app startup (``langflow.api.v1.knowledge_bases`` reaches here via\\n``memory_base.preprocessing`` -> ``models_and_agents.agent``).  Any third-party package\\nwith an import-time side effect then owns process startup -- see #14227, where mem0's\\n``os.makedirs($HOME/.mem0)`` aborted boot on a read-only Kubernetes filesystem.\\n\\nLocked here:\\n  1. The aliases still resolve to the same classes (no behavioural change).\\n  2. Resolving them does not trigger the package-wide discovery scan.\\n  3. Discovery itself swallows *any* import failure, not just ``ImportError``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport subprocess\\nimport sys\\n\\nimport pytest\\n\\n# Bundle modules that a legacy alias lookup has no business importing. These sit early in\\n# the discovery table, so a reintroduced brute-force scan pulls them in first.\\nCANARY_BUNDLES = (\\n    \\\"lfx.components.mem0\\\",\\n    \\\"lfx.components.openai\\\",\\n    \\\"lfx.components.anthropic\\\",\\n    \\\"lfx.components.chroma\\\",\\n)\\n\\n\\ndef _run_probe(script: str) -> dict:\\n    \\\"\\\"\\\"Execute ``script`` in a clean interpreter and return its JSON stdout.\\n\\n    A subprocess is required: discovery state (``_discovered_modules``,\\n    ``_dynamic_imports``, ``sys.modules``) is process-global, so any earlier test that\\n    touched ``lfx.components`` would mask a regression here.\\n    \\\"\\\"\\\"\\n    result = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", script], capture_output=True, text=True, check=False\\n    )\\n    assert result.returncode == 0, result.stderr\\n    return json.loads(result.stdout.strip().splitlines()[-1])\\n\\n\\nclass TestLegacyAliasesResolve:\\n    \\\"\\\"\\\"The forwards must keep pointing at the modules the components actually live in.\\\"\\\"\\\"\\n\\n    def test_helpers_forwards_to_utilities(self):\\n        from lfx.components.helpers import CalculatorComponent, CurrentDateComponent, IDGeneratorComponent\\n\\n        assert CalculatorComponent.__module__ == \\\"lfx.components.utilities.calculator_core\\\"\\n        assert CurrentDateComponent.__module__ == \\\"lfx.components.utilities.current_date\\\"\\n        assert IDGeneratorComponent.__module__ == \\\"lfx.components.utilities.id_generator\\\"\\n\\n    def test_logic_forwards_to_flow_controls(self):\\n        from lfx.components.logic import ConditionalRouterComponent, LoopComponent\\n\\n        assert ConditionalRouterComponent.__module__ == \\\"lfx.components.flow_controls.conditional_router\\\"\\n        assert LoopComponent.__module__ == \\\"lfx.components.flow_controls.loop\\\"\\n\\n    def test_logic_forwards_smart_router_to_llm_operations(self):\\n        from lfx.components.logic import SmartRouterComponent\\n\\n        assert SmartRouterComponent.__module__.startswith(\\\"lfx.components.llm_operations.\\\")\\n\\n\\nclass TestLegacyAliasesDoNotScanBundles:\\n    \\\"\\\"\\\"Resolving a legacy alias must not drag in the integration tail.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"module\\\", \\\"attr\\\"),\\n        [\\n            (\\\"lfx.components.helpers\\\", \\\"CalculatorComponent\\\"),\\n            (\\\"lfx.components.helpers\\\", \\\"CurrentDateComponent\\\"),\\n            (\\\"lfx.components.logic\\\", \\\"ConditionalRouterComponent\\\"),\\n            (\\\"lfx.components.logic\\\", \\\"SmartRouterComponent\\\"),\\n        ],\\n    )\\n    def test_alias_lookup_skips_package_wide_discovery(self, module: str, attr: str):\\n        probe = _run_probe(\\n            \\\"import importlib, json, sys\\\\n\\\"\\n            \\\"import lfx.components as pkg\\\\n\\\"\\n            f\\\"getattr(importlib.import_module({module!r}), {attr!r})\\\\n\\\"\\n            \\\"print(json.dumps({\\\\n\\\"\\n            '    \\\"discovered\\\": sorted(pkg._discovered_modules),\\\\n'\\n            '    \\\"submodules\\\": sorted(\\\\n'\\n            '        m for m in sys.modules if m.startswith(\\\"lfx.components.\\\") and m.count(\\\".\\\") == 2\\\\n'\\n            \\\"    ),\\\\n\\\"\\n            \\\"}))\\\\n\\\"\\n        )\\n\\n        # An empty discovery set is the real assertion: a single entry means __getattr__\\n        # started walking the table.\\n        assert probe[\\\"discovered\\\"] == [], (\\n            f\\\"resolving {module}.{attr} triggered package-wide discovery of \\\"\\n            f\\\"{len(probe['discovered'])} module(s): {probe['discovered'][:10]}\\\"\\n        )\\n        leaked = sorted(set(CANARY_BUNDLES) & set(probe[\\\"submodules\\\"]))\\n        assert not leaked, f\\\"resolving {module}.{attr} imported unrelated bundles: {leaked}\\\"\\n\\n\\nclass TestDiscoveryIsBestEffort:\\n    \\\"\\\"\\\"A misbehaving integration must not be able to abort the caller's import.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"error\\\", [OSError(30, \\\"Read-only file system\\\"), RuntimeError(\\\"boom\\\"), ValueError(\\\"bad\\\")])\\n    def test_non_import_errors_are_swallowed(self, monkeypatch: pytest.MonkeyPatch, error: Exception):\\n        import lfx.components as pkg\\n\\n        module_name = \\\"_synthetic_failing_module\\\"\\n\\n        def explode(*_args, **_kwargs):\\n            raise error\\n\\n        monkeypatch.setattr(pkg, \\\"import_mod\\\", explode)\\n        monkeypatch.setattr(pkg, \\\"_discovered_modules\\\", set(pkg._discovered_modules))\\n\\n        pkg._discover_components_from_module(module_name)\\n\\n        # Marked discovered so the failure is not retried on every subsequent lookup.\\n        assert module_name in pkg._discovered_modules\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_prompt_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"67f71243f389b5e67e0ed73f1338c3c47812430bf69e73d85372fa023a16c80b\",\"content\":\"\\\"\\\"\\\"Tests for PromptComponent with f-string and double brackets syntax.\\\"\\\"\\\"\\n\\nfrom lfx.components.models_and_agents.prompt import PromptComponent\\n\\n\\nclass TestPromptComponent:\\n    \\\"\\\"\\\"Test the PromptComponent.\\\"\\\"\\\"\\n\\n    def test_update_template_single_variable(self):\\n        \\\"\\\"\\\"Test template update with a single variable.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {name}!\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in result[\\\"template\\\"]\\n\\n    def test_update_template_multiple_variables(self):\\n        \\\"\\\"\\\"Test template with multiple variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"{greeting} {name}!\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert \\\"greeting\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n\\n    def test_update_template_duplicate_variables(self):\\n        \\\"\\\"\\\"Test template with duplicate variables only creates one field.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {name}! How are you {name}?\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert result[\\\"custom_fields\\\"][\\\"template\\\"].count(\\\"name\\\") == 1\\n        assert \\\"name\\\" in result[\\\"template\\\"]\\n\\n    def test_update_template_no_variables(self):\\n        \\\"\\\"\\\"Test template with no variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello World!\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert len(result[\\\"custom_fields\\\"].get(\\\"template\\\", [])) == 0\\n\\n    def test_update_template_escaped_braces(self):\\n        \\\"\\\"\\\"Test template with escaped braces doesn't create variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Result: {{not_a_var}} but {real_var} works\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        # Only {real_var} should be extracted\\n        assert \\\"real_var\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        # {{not_a_var}} should NOT be extracted in f-string mode\\n        assert \\\"not_a_var\\\" not in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n\\n    async def test_build_prompt_basic(self):\\n        \\\"\\\"\\\"Test building a basic prompt.\\\"\\\"\\\"\\n        component = PromptComponent()\\n        component._attributes = {\\n            \\\"template\\\": \\\"Hello {name}!\\\",\\n            \\\"name\\\": \\\"World\\\",\\n        }\\n\\n        result = await component.build_prompt()\\n\\n        assert result.text == \\\"Hello World!\\\"\\n        assert result.template == \\\"Hello {name}!\\\"\\n\\n    async def test_build_prompt_multiple_variables(self):\\n        \\\"\\\"\\\"Test building prompt with multiple variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n        component._attributes = {\\n            \\\"template\\\": \\\"{greeting} {name}! You are {age} years old.\\\",\\n            \\\"greeting\\\": \\\"Hello\\\",\\n            \\\"name\\\": \\\"Alice\\\",\\n            \\\"age\\\": \\\"25\\\",\\n        }\\n\\n        result = await component.build_prompt()\\n\\n        assert result.text == \\\"Hello Alice! You are 25 years old.\\\"\\n\\n    async def test_update_frontend_node(self):\\n        \\\"\\\"\\\"Test update_frontend_node processes template correctly.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        new_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {name}!\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        current_node = {\\n            \\\"template\\\": {\\\"template\\\": {\\\"value\\\": \\\"\\\"}},\\n        }\\n\\n        result = await component.update_frontend_node(new_node, current_node)\\n\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in result[\\\"template\\\"]\\n\\n    async def test_update_frontend_node_creates_variable_fields(self):\\n        \\\"\\\"\\\"Test that update_frontend_node creates fields for template variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        new_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {name} and {greeting}!\\\"},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        current_node = {\\n            \\\"template\\\": {\\\"template\\\": {\\\"value\\\": \\\"\\\"}},\\n        }\\n\\n        result = await component.update_frontend_node(new_node, current_node)\\n\\n        # Both variables should be in custom_fields\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"greeting\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n\\n\\nclass TestPromptComponentDoubleBrackets:\\n    \\\"\\\"\\\"Test the PromptComponent with double brackets (mustache) syntax.\\\"\\\"\\\"\\n\\n    def test_update_template_double_brackets_single_variable(self):\\n        \\\"\\\"\\\"Test template update with a single double-bracket variable.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {{name}}!\\\"},\\n                \\\"use_double_brackets\\\": {\\\"value\\\": True},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in result[\\\"template\\\"]\\n\\n    def test_update_template_double_brackets_multiple_variables(self):\\n        \\\"\\\"\\\"Test template with multiple double-bracket variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"{{greeting}} {{name}}!\\\"},\\n                \\\"use_double_brackets\\\": {\\\"value\\\": True},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert \\\"greeting\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n\\n    def test_update_template_double_brackets_no_variables(self):\\n        \\\"\\\"\\\"Test double-bracket template with no variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello World!\\\"},\\n                \\\"use_double_brackets\\\": {\\\"value\\\": True},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        assert len(result[\\\"custom_fields\\\"].get(\\\"template\\\", [])) == 0\\n\\n    def test_update_template_double_brackets_ignores_single_braces(self):\\n        \\\"\\\"\\\"Test that double-bracket mode ignores single-brace variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {single} and {{double}}!\\\"},\\n                \\\"use_double_brackets\\\": {\\\"value\\\": True},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        result = component._update_template(frontend_node)\\n\\n        # Only {{double}} should be extracted in double-bracket mode\\n        assert \\\"double\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        # {single} should NOT be extracted\\n        assert \\\"single\\\" not in result[\\\"custom_fields\\\"].get(\\\"template\\\", [])\\n\\n    async def test_build_prompt_double_brackets_basic(self):\\n        \\\"\\\"\\\"Test building a basic prompt with double brackets.\\\"\\\"\\\"\\n        component = PromptComponent()\\n        component.use_double_brackets = True\\n        component._attributes = {\\n            \\\"template\\\": \\\"Hello {{name}}!\\\",\\n            \\\"name\\\": \\\"World\\\",\\n            \\\"use_double_brackets\\\": True,\\n        }\\n\\n        result = await component.build_prompt()\\n\\n        assert result.text == \\\"Hello World!\\\"\\n\\n    async def test_build_prompt_double_brackets_multiple_variables(self):\\n        \\\"\\\"\\\"Test building prompt with multiple double-bracket variables.\\\"\\\"\\\"\\n        component = PromptComponent()\\n        component.use_double_brackets = True\\n        component._attributes = {\\n            \\\"template\\\": \\\"{{greeting}} {{name}}! You are {{age}} years old.\\\",\\n            \\\"greeting\\\": \\\"Hello\\\",\\n            \\\"name\\\": \\\"Alice\\\",\\n            \\\"age\\\": \\\"25\\\",\\n            \\\"use_double_brackets\\\": True,\\n        }\\n\\n        result = await component.build_prompt()\\n\\n        assert result.text == \\\"Hello Alice! You are 25 years old.\\\"\\n\\n    async def test_build_prompt_default_is_single_brackets(self):\\n        \\\"\\\"\\\"Test that default mode uses single brackets (f-string).\\\"\\\"\\\"\\n        component = PromptComponent()\\n        # Don't set use_double_brackets - should default to False\\n        component._attributes = {\\n            \\\"template\\\": \\\"Hello {name}!\\\",\\n            \\\"name\\\": \\\"World\\\",\\n        }\\n\\n        result = await component.build_prompt()\\n\\n        assert result.text == \\\"Hello World!\\\"\\n\\n    async def test_update_frontend_node_double_brackets(self):\\n        \\\"\\\"\\\"Test update_frontend_node processes double-bracket template correctly.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        new_node = {\\n            \\\"template\\\": {\\n                \\\"template\\\": {\\\"value\\\": \\\"Hello {{name}}!\\\"},\\n                \\\"use_double_brackets\\\": {\\\"value\\\": True},\\n            },\\n            \\\"custom_fields\\\": {},\\n        }\\n\\n        current_node = {\\n            \\\"template\\\": {\\\"template\\\": {\\\"value\\\": \\\"\\\"}},\\n        }\\n\\n        result = await component.update_frontend_node(new_node, current_node)\\n\\n        assert \\\"name\\\" in result[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in result[\\\"template\\\"]\\n\\n    def test_update_build_config_switches_to_mustache(self):\\n        \\\"\\\"\\\"Test that update_build_config switches field type when enabling double brackets.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        build_config = {\\n            \\\"template\\\": {\\\"type\\\": \\\"prompt\\\", \\\"value\\\": \\\"Hello {{name}}!\\\"},\\n            \\\"custom_fields\\\": {\\\"template\\\": []},\\n        }\\n\\n        result = component.update_build_config(build_config, field_value=True, field_name=\\\"use_double_brackets\\\")\\n\\n        assert result[\\\"template\\\"][\\\"type\\\"] == \\\"mustache\\\"\\n\\n    def test_update_build_config_switches_to_fstring(self):\\n        \\\"\\\"\\\"Test that update_build_config switches field type when disabling double brackets.\\\"\\\"\\\"\\n        component = PromptComponent()\\n\\n        build_config = {\\n            \\\"template\\\": {\\\"type\\\": \\\"MustachePrompt\\\", \\\"value\\\": \\\"Hello {name}!\\\"},\\n            \\\"custom_fields\\\": {\\\"template\\\": []},\\n        }\\n\\n        result = component.update_build_config(build_config, field_value=False, field_name=\\\"use_double_brackets\\\")\\n\\n        assert result[\\\"template\\\"][\\\"type\\\"] == \\\"prompt\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/test_provider_base_url_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1baa9c6fa1ec47728f6c5b512476c6f94ec908ba2cdded618064017cdcd6daf5\",\"content\":\"\\\"\\\"\\\"SSRF regression tests for components that fetch a tenant-controlled base_url.\\n\\nThese cover the multi-tenant hole where Home Assistant, Ollama and LM Studio components\\nfetched a tenant-supplied ``base_url`` (at run time and during build-config edits) with no\\nSSRF guard, enabling cloud-metadata credential theft / internal-network probing.\\n\\nThe key assertion is that the outbound request is NEVER issued when the host is blocked.\\n\\\"\\\"\\\"\\n\\nfrom contextlib import contextmanager\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\n\\n@contextmanager\\ndef ssrf_enabled():\\n    with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get:\\n        s = MagicMock()\\n        s.settings.ssrf_protection_enabled = True\\n        # Explicitly enable the connector flag so the watsonx connector guard runs here too.\\n        # (Home Assistant / Ollama / LM Studio use the always-on validate_url_for_ssrf.)\\n        s.settings.connector_ssrf_validation_enabled = True\\n        s.settings.ssrf_allowed_hosts = []\\n        s.settings.restrict_local_file_access = False\\n        mock_get.return_value = s\\n        yield\\n\\n\\nMETADATA_URL = \\\"http://169.254.169.254\\\"\\n\\n\\ndef test_home_assistant_list_states_blocks_metadata_without_request():\\n    pytest.importorskip(\\\"lfx_bundles.homeassistant\\\")\\n    from lfx.components.homeassistant.list_home_assistant_states import ListHomeAssistantStates\\n\\n    component = ListHomeAssistantStates()\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"httpx.Client.get\\\") as mock_get,\\n    ):\\n        # Trailing '#' would discard the appended /api/states suffix client-side.\\n        result = component._list_states(\\\"token\\\", f\\\"{METADATA_URL}/latest/meta-data/#\\\", \\\"\\\")\\n        assert mock_get.call_count == 0\\n        assert isinstance(result, str)\\n        assert \\\"SSRF\\\" in result\\n\\n\\ndef test_home_assistant_control_blocks_metadata_without_request():\\n    pytest.importorskip(\\\"lfx_bundles.homeassistant\\\")\\n    from lfx.components.homeassistant.home_assistant_control import HomeAssistantControl\\n\\n    component = HomeAssistantControl()\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"httpx.Client.post\\\") as mock_post,\\n    ):\\n        result = component._control_device(\\\"token\\\", f\\\"{METADATA_URL}#\\\", \\\"turn_on\\\", \\\"switch.x\\\")\\n        assert mock_post.call_count == 0\\n        assert isinstance(result, str)\\n        assert \\\"SSRF\\\" in result\\n\\n\\nasync def test_is_valid_ollama_url_blocks_metadata_without_request():\\n    from lfx.base.models import model_utils\\n\\n    with (\\n        ssrf_enabled(),\\n        patch.object(model_utils.httpx, \\\"AsyncClient\\\") as mock_client,\\n    ):\\n        result = await model_utils.is_valid_ollama_url(METADATA_URL)\\n        assert result is False\\n        # The client context manager must never have issued a GET.\\n        assert mock_client.return_value.__aenter__.return_value.get.call_count == 0\\n\\n\\nasync def test_get_ollama_models_blocks_metadata():\\n    from lfx.base.models import model_utils\\n\\n    with (\\n        ssrf_enabled(),\\n        patch.object(model_utils.httpx, \\\"AsyncClient\\\") as mock_client,\\n        pytest.raises(ValueError, match=\\\"Could not get model names\\\"),\\n    ):\\n        await model_utils.get_ollama_models(\\n            base_url_value=METADATA_URL,\\n            desired_capability=\\\"completion\\\",\\n            json_models_key=\\\"models\\\",\\n            json_name_key=\\\"name\\\",\\n            json_capabilities_key=\\\"capabilities\\\",\\n        )\\n    assert mock_client.return_value.__aenter__.return_value.get.call_count == 0\\n\\n\\nasync def test_lmstudio_get_model_blocks_metadata():\\n    pytest.importorskip(\\\"lfx_bundles.lmstudio\\\")\\n    pytest.importorskip(\\\"langchain_openai\\\")\\n    from lfx.components.lmstudio.lmstudiomodel import LMStudioModelComponent\\n\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx.utils.ssrf_httpx.httpx.AsyncClient\\\") as mock_client,\\n        pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n    ):\\n        await LMStudioModelComponent.get_model(f\\\"{METADATA_URL}/v1\\\")\\n    assert mock_client.call_count == 0\\n\\n\\nasync def test_lmstudio_embeddings_get_model_blocks_metadata():\\n    pytest.importorskip(\\\"lfx_bundles.lmstudio\\\")\\n    from lfx.components.lmstudio.lmstudioembeddings import LMStudioEmbeddingsComponent\\n\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx.utils.ssrf_httpx.httpx.AsyncClient\\\") as mock_client,\\n        pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n    ):\\n        await LMStudioEmbeddingsComponent.get_model(f\\\"{METADATA_URL}/v1\\\")\\n    assert mock_client.call_count == 0\\n\\n\\ndef test_get_watsonx_llm_models_blocks_metadata_without_request():\\n    \\\"\\\"\\\"WatsonX model discovery (returns-defaults-on-block) must not hit a blocked host.\\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n\\n    with ssrf_enabled(), patch.object(model_utils.requests, \\\"get\\\") as mock_get:\\n        result = model_utils.get_watsonx_llm_models(base_url=METADATA_URL, default_models=[\\\"fallback-llm\\\"])\\n        assert mock_get.call_count == 0  # request never issued to the blocked host\\n        assert result == [\\\"fallback-llm\\\"]  # falls back instead\\n\\n\\ndef test_get_watsonx_embedding_models_blocks_metadata_without_request():\\n    from lfx.base.models import model_utils\\n\\n    with ssrf_enabled(), patch.object(model_utils.requests, \\\"get\\\") as mock_get:\\n        result = model_utils.get_watsonx_embedding_models(base_url=METADATA_URL, default_models=[\\\"fallback-emb\\\"])\\n        assert mock_get.call_count == 0\\n        assert result == [\\\"fallback-emb\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"401905a769940c8f2883a9cb40d6b1773446a48d11df8369447c8b20fdbb8c05\",\"content\":\"\\\"\\\"\\\"Unit tests for FileSystemToolComponent (sandboxed filesystem agent tool).\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n\\n@pytest.fixture\\ndef sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    \\\"\\\"\\\"Pre-populated sandbox directory used by filesystem-tool tests.\\n\\n    Uses AUTO_LOGIN=True (shared mode) by default so the test fixture lands\\n    files under ``<BASE>/shared/`` and the component points at the same root\\n    via an empty sub_path. Tests that need isolated mode override\\n    ``_resolve_auto_login`` directly.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    shared = tmp_path / \\\"shared\\\"\\n    shared.mkdir(parents=True, exist_ok=True)\\n    (shared / \\\"hello.txt\\\").write_text(\\\"line1\\\\nline2\\\\nline3\\\\n\\\", encoding=\\\"utf-8\\\")\\n    nested = shared / \\\"nested\\\"\\n    nested.mkdir()\\n    (nested / \\\"deep.py\\\").write_text(\\\"def foo():\\\\n    return 1\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (shared / \\\"binary.bin\\\").write_bytes(b\\\"\\\\x00\\\\x01\\\\x02\\\\x03BIN\\\\x00\\\")\\n    return shared\\n\\n\\n@pytest.fixture\\ndef component(sandbox: Path) -> FileSystemToolComponent:  # noqa: ARG001 \u2014 sandbox sets BASE_DIR via monkeypatch\\n    component = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n    component._resolve_auto_login = lambda: True  # type: ignore[method-assign]\\n    return component\\n\\n\\nclass TestComponentSkeleton:\\n    \\\"\\\"\\\"Slice 1 \u2014 component boots with required configuration inputs.\\\"\\\"\\\"\\n\\n    def test_should_expose_required_inputs_when_instantiated(self, component: FileSystemToolComponent) -> None:\\n        input_names = {inp.name for inp in component.inputs}\\n        assert {\\\"root_path\\\", \\\"read_only\\\"}.issubset(input_names)\\n\\n    def test_should_have_display_metadata(self) -> None:\\n        assert FileSystemToolComponent.display_name == \\\"File System\\\"\\n        assert FileSystemToolComponent.icon == \\\"folder\\\"\\n        assert FileSystemToolComponent.name == \\\"FileSystemTool\\\"\\n\\n\\nclass TestValidatePath:\\n    \\\"\\\"\\\"Slices 2-6 \u2014 every operation MUST resolve paths through _validate_path.\\\"\\\"\\\"\\n\\n    def test_should_return_resolved_path_when_path_is_inside_sandbox(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        resolved = component._validate_path(\\\"hello.txt\\\")\\n        assert resolved == (sandbox / \\\"hello.txt\\\").resolve()\\n\\n    def test_should_return_resolved_path_when_path_is_nested(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        resolved = component._validate_path(\\\"nested/deep.py\\\")\\n        assert resolved == (sandbox / \\\"nested\\\" / \\\"deep.py\\\").resolve()\\n\\n    def test_should_reject_when_path_escapes_via_dotdot(self, component: FileSystemToolComponent) -> None:\\n        with pytest.raises(PermissionError):\\n            component._validate_path(\\\"../outside.txt\\\")\\n\\n    def test_should_reject_when_path_is_absolute_outside_root(self, component: FileSystemToolComponent) -> None:\\n        with pytest.raises(PermissionError):\\n            component._validate_path(\\\"/etc/passwd\\\")\\n\\n    def test_should_reject_when_symlink_points_outside_root(\\n        self, component: FileSystemToolComponent, sandbox: Path, tmp_path: Path\\n    ) -> None:\\n        outside = tmp_path.parent / f\\\"{tmp_path.name}-outside-secret.txt\\\"\\n        outside.write_text(\\\"secret\\\", encoding=\\\"utf-8\\\")\\n        symlink = sandbox / \\\"escape_link\\\"\\n        symlink.symlink_to(outside)\\n        with pytest.raises(PermissionError):\\n            component._validate_path(\\\"escape_link\\\")\\n\\n    def test_should_reject_path_containing_null_byte(self, component: FileSystemToolComponent) -> None:\\n        with pytest.raises(PermissionError):\\n            component._validate_path(\\\"hello\\\\x00.txt\\\")\\n\\n\\nclass TestWindowsPortability:\\n    \\\"\\\"\\\"Slice 26 \u2014 proactively reject paths that would fail on Windows.\\n\\n    These checks are pure-string and equally valid on every host OS, so flows\\n    authored on macOS/Linux do not silently break when run on Windows.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"name\\\", [\\\"CON\\\", \\\"PRN\\\", \\\"AUX\\\", \\\"NUL\\\", \\\"COM1\\\", \\\"COM9\\\", \\\"LPT1\\\", \\\"LPT9\\\"])\\n    def test_should_reject_basename_that_is_a_windows_reserved_name(\\n        self, component: FileSystemToolComponent, name: str\\n    ) -> None:\\n        result = component._read_file(name)\\n        assert \\\"error\\\" in result\\n        assert \\\"reserved\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_reject_reserved_name_with_extension(self, component: FileSystemToolComponent) -> None:\\n        # CON.txt is just as reserved as bare CON on Windows.\\n        result = component._read_file(\\\"CON.txt\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"reserved\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_reject_reserved_name_in_nested_path(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"nested/PRN.json\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"reserved\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_be_case_insensitive_for_reserved_names(self, component: FileSystemToolComponent) -> None:\\n        # Lowercase \\\"con\\\" is treated identically by Windows.\\n        result = component._read_file(\\\"con.log\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"reserved\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_accept_reserved_name_as_substring(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        # MyCon.txt is NOT reserved \u2014 only the exact stem CON is.\\n        (sandbox / \\\"MyCon.txt\\\").write_text(\\\"data\\\", encoding=\\\"utf-8\\\")\\n        result = component._read_file(\\\"MyCon.txt\\\")\\n        assert \\\"error\\\" not in result, f\\\"Unexpected error: {result.get('error')}\\\"\\n\\n    @pytest.mark.parametrize(\\\"char\\\", [\\\"<\\\", \\\">\\\", '\\\"', \\\"|\\\", \\\"?\\\", \\\"*\\\"])\\n    def test_should_reject_path_with_forbidden_windows_character(\\n        self, component: FileSystemToolComponent, char: str\\n    ) -> None:\\n        result = component._read_file(f\\\"bad{char}name.txt\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"forbidden\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_reject_path_with_trailing_dot(self, component: FileSystemToolComponent) -> None:\\n        # Windows silently strips trailing \\\".\\\" \u2014 ambiguous and bug-prone.\\n        result = component._write_file(\\\"badname.\\\", \\\"x\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"trailing\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_reject_path_with_trailing_space(self, component: FileSystemToolComponent) -> None:\\n        result = component._write_file(\\\"badname \\\", \\\"x\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"trailing\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_not_trigger_on_dotdot_relative_marker(self, component: FileSystemToolComponent) -> None:\\n        # `..` IS a path component but it is the parent-dir marker, not a\\n        # filename with a trailing dot. It should pass the portability check\\n        # and be caught only by the sandbox-boundary check downstream.\\n        result = component._read_file(\\\"../outside.txt\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"trailing\\\" not in result[\\\"error\\\"].lower()\\n        assert \\\"boundary\\\" in result[\\\"error\\\"].lower() or \\\"escape\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_not_trigger_on_single_dot(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        # `./hello.txt` is just `hello.txt`. Should not trigger trailing-dot\\n        # rule, and should resolve to the existing file.\\n        assert (sandbox / \\\"hello.txt\\\").exists()\\n        result = component._read_file(\\\"./hello.txt\\\")\\n        assert result.get(\\\"status\\\") == \\\"ok\\\", f\\\"Got: {result}\\\"\\n\\n\\nclass TestReadFile:\\n    \\\"\\\"\\\"Slices 7-9 \u2014 read_file returns content with metadata + adversarial cases.\\\"\\\"\\\"\\n\\n    def test_should_return_content_with_metadata(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"hello.txt\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"total_lines\\\"] == 3\\n        assert result[\\\"start_line\\\"] == 1\\n        assert result[\\\"num_lines\\\"] == 3\\n        assert \\\"line1\\\" in result[\\\"content\\\"]\\n        assert \\\"line2\\\" in result[\\\"content\\\"]\\n        assert \\\"line3\\\" in result[\\\"content\\\"]\\n\\n    def test_should_prefix_lines_with_line_numbers(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"hello.txt\\\")\\n        assert \\\"1\\\" in result[\\\"content\\\"].splitlines()[0]\\n        assert \\\"line1\\\" in result[\\\"content\\\"].splitlines()[0]\\n\\n    def test_should_respect_offset_and_limit_window(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"hello.txt\\\", offset=2, limit=1)\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"start_line\\\"] == 2\\n        assert result[\\\"num_lines\\\"] == 1\\n        assert result[\\\"total_lines\\\"] == 3\\n        assert \\\"line2\\\" in result[\\\"content\\\"]\\n        assert \\\"line1\\\" not in result[\\\"content\\\"]\\n        assert \\\"line3\\\" not in result[\\\"content\\\"]\\n\\n    def test_should_reject_binary_file_on_read(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"binary.bin\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"binary\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_reject_read_when_file_exceeds_size_limit(\\n        self, component: FileSystemToolComponent, sandbox: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        from lfx.components.files_and_knowledge import filesystem as fs_mod\\n\\n        (sandbox / \\\"big.txt\\\").write_text(\\\"x\\\" * 128, encoding=\\\"utf-8\\\")\\n        monkeypatch.setattr(fs_mod, \\\"MAX_FILE_SIZE_BYTES\\\", 64)\\n        result = component._read_file(\\\"big.txt\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"size\\\" in result[\\\"error\\\"].lower() or \\\"limit\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_file_does_not_exist(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"does_not_exist.txt\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" in result[\\\"error\\\"].lower() or \\\"no such\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_path_is_a_directory(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"nested\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"directory\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_path_escapes_sandbox(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"../outside.txt\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestWriteFile:\\n    \\\"\\\"\\\"Slices 10-12 \u2014 write_file creates/updates with size + OS error guards.\\\"\\\"\\\"\\n\\n    def test_should_create_new_file(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        result = component._write_file(\\\"new.txt\\\", \\\"hello world\\\")\\n        assert result[\\\"status\\\"] == \\\"created\\\"\\n        assert (sandbox / \\\"new.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"hello world\\\"\\n\\n    def test_should_overwrite_existing_file(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        result = component._write_file(\\\"hello.txt\\\", \\\"replaced\\\")\\n        assert result[\\\"status\\\"] == \\\"updated\\\"\\n        assert (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"replaced\\\"\\n\\n    def test_should_reject_write_when_content_exceeds_size_limit(\\n        self, component: FileSystemToolComponent, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        from lfx.components.files_and_knowledge import filesystem as fs_mod\\n\\n        monkeypatch.setattr(fs_mod, \\\"MAX_FILE_SIZE_BYTES\\\", 8)\\n        result = component._write_file(\\\"too_big.txt\\\", \\\"this content exceeds eight bytes\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"size\\\" in result[\\\"error\\\"].lower() or \\\"limit\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_create_parent_directories_when_writing_to_nested_path(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # BUG-1: agent filesystem tools must create missing parent directories\\n        # automatically (standard mkdir(parents=True) behavior). Previously this\\n        # returned {\\\"error\\\": \\\"Parent directory does not exist: ...\\\"} which forced\\n        # agents to issue a separate mkdir tool call we do not expose.\\n        result = component._write_file(\\\"subdir/nested/file.txt\\\", \\\"hello\\\")\\n        assert result[\\\"status\\\"] == \\\"created\\\"\\n        assert result[\\\"bytes_written\\\"] == len(b\\\"hello\\\")\\n        assert (sandbox / \\\"subdir\\\" / \\\"nested\\\" / \\\"file.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"hello\\\"\\n\\n    def test_should_return_structured_error_when_path_escapes_sandbox(self, component: FileSystemToolComponent) -> None:\\n        result = component._write_file(\\\"../escape.txt\\\", \\\"x\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_target_is_a_directory(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        result = component._write_file(\\\"nested\\\", \\\"x\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"directory\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestEditFile:\\n    \\\"\\\"\\\"Slices 13-15 \u2014 edit_file uses exact string match (not line numbers).\\\"\\\"\\\"\\n\\n    def test_should_replace_single_occurrence(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        result = component._edit_file(\\\"hello.txt\\\", old_string=\\\"line2\\\", new_string=\\\"LINE_TWO\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"replacements\\\"] == 1\\n        assert (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"line1\\\\nLINE_TWO\\\\nline3\\\\n\\\"\\n\\n    def test_should_replace_all_when_replace_all_true(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        (sandbox / \\\"repeat.txt\\\").write_text(\\\"foo\\\\nfoo\\\\nfoo\\\\n\\\", encoding=\\\"utf-8\\\")\\n        result = component._edit_file(\\\"repeat.txt\\\", old_string=\\\"foo\\\", new_string=\\\"bar\\\", replace_all=True)\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"replacements\\\"] == 3\\n        assert (sandbox / \\\"repeat.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"bar\\\\nbar\\\\nbar\\\\n\\\"\\n\\n    def test_should_reject_edit_when_old_string_not_found(self, component: FileSystemToolComponent) -> None:\\n        result = component._edit_file(\\\"hello.txt\\\", old_string=\\\"absent\\\", new_string=\\\"whatever\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_reject_edit_when_old_string_matches_multiple_times_and_replace_all_false(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        (sandbox / \\\"repeat.txt\\\").write_text(\\\"foo\\\\nfoo\\\\n\\\", encoding=\\\"utf-8\\\")\\n        result = component._edit_file(\\\"repeat.txt\\\", old_string=\\\"foo\\\", new_string=\\\"bar\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"multiple\\\" in result[\\\"error\\\"].lower() or \\\"ambiguous\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_file_does_not_exist(self, component: FileSystemToolComponent) -> None:\\n        result = component._edit_file(\\\"missing.txt\\\", old_string=\\\"x\\\", new_string=\\\"y\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_path_escapes(self, component: FileSystemToolComponent) -> None:\\n        result = component._edit_file(\\\"../escape.txt\\\", old_string=\\\"x\\\", new_string=\\\"y\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestGlobSearch:\\n    \\\"\\\"\\\"Slices 16-17 \u2014 glob_search lists matching paths with truncation flag.\\\"\\\"\\\"\\n\\n    def test_should_list_paths_matching_pattern(self, component: FileSystemToolComponent) -> None:\\n        result = component._glob_search(\\\"**/*.py\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"truncated\\\"] is False\\n        assert any(p.endswith(\\\"deep.py\\\") for p in result[\\\"matches\\\"])\\n\\n    def test_should_return_empty_list_when_no_matches(self, component: FileSystemToolComponent) -> None:\\n        result = component._glob_search(\\\"**/*.nonexistent\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"matches\\\"] == []\\n        assert result[\\\"truncated\\\"] is False\\n\\n    def test_should_truncate_glob_results_at_one_hundred_and_set_flag(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        bulk = sandbox / \\\"bulk\\\"\\n        bulk.mkdir()\\n        for i in range(150):\\n            (bulk / f\\\"f{i:03d}.log\\\").write_text(\\\"x\\\", encoding=\\\"utf-8\\\")\\n        result = component._glob_search(\\\"bulk/*.log\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"truncated\\\"] is True\\n        assert len(result[\\\"matches\\\"]) == 100\\n\\n    def test_should_scope_glob_to_path_argument(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        (sandbox / \\\"nested\\\" / \\\"only_here.md\\\").write_text(\\\"x\\\", encoding=\\\"utf-8\\\")\\n        (sandbox / \\\"top.md\\\").write_text(\\\"x\\\", encoding=\\\"utf-8\\\")\\n        result = component._glob_search(\\\"*.md\\\", path=\\\"nested\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert any(\\\"only_here.md\\\" in p for p in result[\\\"matches\\\"])\\n        assert not any(\\\"top.md\\\" in p for p in result[\\\"matches\\\"])\\n\\n    def test_should_return_structured_error_when_scope_path_escapes(self, component: FileSystemToolComponent) -> None:\\n        result = component._glob_search(\\\"*.txt\\\", path=\\\"../\\\")\\n        assert \\\"error\\\" in result\\n\\n    def test_should_return_structured_error_when_glob_pattern_is_empty(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        # BUG-2: Path.glob(\\\"\\\") raises ValueError(\\\"Unacceptable pattern: ''\\\") which\\n        # propagates uncaught and crashes the agent. The tool surface contract is\\n        # to return a structured error dict for every misuse.\\n        result = component._glob_search(\\\"\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"empty\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_glob_pattern_contains_dotdot_traversal(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        # BUG-3: a \\\"../*\\\" pattern silently slipped through because each match\\n        # was resolved and compared against the sandbox root, but `shared/../shared`\\n        # resolves back to the root itself and surfaced as \\\".\\\" in matches.\\n        # Must be rejected up-front \u2014 same posture as `_validate_path`.\\n        result = component._glob_search(\\\"../*\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"..\\\" in result[\\\"error\\\"] or \\\"traversal\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_glob_pattern_contains_nested_dotdot(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        # Variant of BUG-3 \u2014 `..` mid-pattern is equally a traversal attempt.\\n        result = component._glob_search(\\\"foo/../*\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"..\\\" in result[\\\"error\\\"] or \\\"traversal\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestGrepSearch:\\n    \\\"\\\"\\\"Slices 18-21 \u2014 grep_search supports files_with_matches | content | count.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def _populate(self, sandbox: Path) -> None:\\n        (sandbox / \\\"a.txt\\\").write_text(\\\"alpha\\\\nfoo bar\\\\nbeta\\\\n\\\", encoding=\\\"utf-8\\\")\\n        (sandbox / \\\"b.txt\\\").write_text(\\\"FOO bar\\\\nbaz\\\\n\\\", encoding=\\\"utf-8\\\")\\n        (sandbox / \\\"nested\\\" / \\\"c.md\\\").write_text(\\\"foo only here\\\\n\\\", encoding=\\\"utf-8\\\")\\n\\n    def test_should_return_files_with_matches_by_default(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(r\\\"foo\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"output_mode\\\"] == \\\"files_with_matches\\\"\\n        files = result[\\\"matches\\\"]\\n        assert any(f.endswith(\\\"a.txt\\\") for f in files)\\n        assert any(f.endswith(\\\"c.md\\\") for f in files)\\n        assert not any(f.endswith(\\\"b.txt\\\") for f in files)  # FOO is uppercase, default is case-sensitive\\n\\n    def test_should_return_content_with_line_numbers_in_content_mode(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(r\\\"foo\\\", output_mode=\\\"content\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"output_mode\\\"] == \\\"content\\\"\\n        lines = result[\\\"matches\\\"]\\n        assert any(\\\"foo bar\\\" in entry[\\\"line\\\"] and entry[\\\"line_number\\\"] == 2 for entry in lines)\\n\\n    def test_should_return_count_per_file_in_count_mode(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        (sandbox / \\\"many.txt\\\").write_text(\\\"foo\\\\nfoo\\\\nbar\\\\nfoo\\\\n\\\", encoding=\\\"utf-8\\\")\\n        result = component._grep_search(r\\\"foo\\\", output_mode=\\\"count\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"output_mode\\\"] == \\\"count\\\"\\n        counts = {entry[\\\"path\\\"]: entry[\\\"count\\\"] for entry in result[\\\"matches\\\"]}\\n        assert any(p.endswith(\\\"many.txt\\\") and c == 3 for p, c in counts.items())\\n\\n    def test_should_apply_glob_filter_to_grep(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(r\\\"foo\\\", glob=\\\"*.md\\\")\\n        files = result[\\\"matches\\\"]\\n        assert any(f.endswith(\\\"c.md\\\") for f in files)\\n        assert not any(f.endswith(\\\".txt\\\") for f in files)\\n\\n    def test_should_honor_case_insensitive_flag(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(r\\\"foo\\\", case_insensitive=True)\\n        files = result[\\\"matches\\\"]\\n        assert any(f.endswith(\\\"a.txt\\\") for f in files)\\n        assert any(f.endswith(\\\"b.txt\\\") for f in files)\\n\\n    def test_should_truncate_grep_output_at_default_line_limit(\\n        self, component: FileSystemToolComponent, sandbox: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        from lfx.components.files_and_knowledge import filesystem as fs_mod\\n\\n        monkeypatch.setattr(fs_mod, \\\"GREP_LINE_LIMIT\\\", 5)\\n        big = \\\"foo\\\\n\\\" * 20\\n        (sandbox / \\\"big.txt\\\").write_text(big, encoding=\\\"utf-8\\\")\\n        result = component._grep_search(r\\\"foo\\\", output_mode=\\\"content\\\", path=\\\"big.txt\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"truncated\\\"] is True\\n        assert len(result[\\\"matches\\\"]) == 5\\n\\n    def test_should_scope_grep_to_single_file_path(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(r\\\"foo\\\", path=\\\"a.txt\\\", output_mode=\\\"content\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert all(\\\"a.txt\\\" in entry[\\\"path\\\"] for entry in result[\\\"matches\\\"])\\n\\n    def test_should_return_structured_error_for_invalid_regex(self, component: FileSystemToolComponent) -> None:\\n        # Regex compilation only happens in opt-in regex mode; in literal\\n        # mode, an unbalanced bracket is just a substring (no error).\\n        result = component._grep_search(r\\\"[invalid\\\", is_regex=True)\\n        assert \\\"error\\\" in result\\n        assert \\\"regex\\\" in result[\\\"error\\\"].lower() or \\\"pattern\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_should_return_structured_error_when_scope_path_escapes(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(r\\\"foo\\\", path=\\\"../\\\")\\n        assert \\\"error\\\" in result\\n\\n\\nclass TestGetTools:\\n    \\\"\\\"\\\"Slices 22-23 \u2014 tool registration respects read_only flag (modern Tool Mode pattern).\\\"\\\"\\\"\\n\\n    async def test_should_register_all_five_tools_when_read_only_false(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        tools = await component._get_tools()\\n        names = {tool.name for tool in tools}\\n        assert names == {\\\"read_file\\\", \\\"write_file\\\", \\\"edit_file\\\", \\\"glob_search\\\", \\\"grep_search\\\"}\\n\\n    async def test_should_not_register_write_and_edit_tools_in_read_only_mode(self, sandbox: Path) -> None:\\n        component = FileSystemToolComponent(root_path=str(sandbox), read_only=True)\\n        tools = await component._get_tools()\\n        names = {tool.name for tool in tools}\\n        assert names == {\\\"read_file\\\", \\\"glob_search\\\", \\\"grep_search\\\"}\\n        assert \\\"write_file\\\" not in names\\n        assert \\\"edit_file\\\" not in names\\n\\n    async def test_registered_read_tool_invokes_read_file(self, component: FileSystemToolComponent) -> None:\\n        tools = {tool.name: tool for tool in await component._get_tools()}\\n        output = tools[\\\"read_file\\\"].invoke({\\\"path\\\": \\\"hello.txt\\\"})\\n        assert \\\"line1\\\" in str(output)\\n\\n    async def test_every_tool_must_have_non_empty_tags(self, component: FileSystemToolComponent) -> None:\\n        # The framework's update_tools_metadata flow (component_tool.py:343)\\n        # gates on `isinstance(tool, StructuredTool|BaseTool) AND tool.tags`.\\n        # A tool without tags falls through to a misleading TypeError that\\n        # claims a wrong type. Every tool MUST carry at least one tag matching\\n        # its name so the metadata-merge step can identify it.\\n        for tool in await component._get_tools():\\n            assert tool.tags, f\\\"Tool {tool.name!r} is missing tags\\\"\\n            assert tool.tags[0] == tool.name, f\\\"Tool {tool.name!r} first tag ({tool.tags[0]!r}) must match name\\\"\\n\\n\\nclass TestToolModeToggle:\\n    \\\"\\\"\\\"Slice 25 \u2014 modern UI contract: Tool Mode toggle is exposed in the UI.\\\"\\\"\\\"\\n\\n    def test_should_set_add_tool_output_flag_at_class_level(self) -> None:\\n        # Defensive runtime flag \u2014 read by Component._handle_tool_mode.\\n        assert getattr(FileSystemToolComponent, \\\"add_tool_output\\\", False) is True\\n\\n    def test_should_have_at_least_one_input_with_tool_mode_true(self, component: FileSystemToolComponent) -> None:\\n        # The frontend toggle visibility is gated by `any(input.tool_mode)` in\\n        # lfx.template.utils \u2014 without this, the \\\"Tool Mode\\\" header toggle does\\n        # not render even if add_tool_output is True.\\n        assert any(getattr(inp, \\\"tool_mode\\\", False) for inp in component.inputs)\\n\\n    def test_should_keep_root_path_visible_in_tool_mode(self, component: FileSystemToolComponent) -> None:\\n        # Frontend rule (parameter-filtering.ts :: isHidden): an input with\\n        # tool_mode=True is hidden when the Tool Mode toggle is ON. The\\n        # root_path field is component-level configuration and MUST remain\\n        # user-editable in both modes \u2014 guard against accidentally setting\\n        # tool_mode=True on it.\\n        root_path_input = next(inp for inp in component.inputs if inp.name == \\\"root_path\\\")\\n        assert getattr(root_path_input, \\\"tool_mode\\\", False) is False\\n\\n    def test_should_use_a_dedicated_hidden_synthetic_input_as_toggle_trigger(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        # The trigger must be hidden (show=False) so it does not pollute the\\n        # config UI. Pattern follows FileComponent.file_path_str.\\n        triggers = [\\n            inp for inp in component.inputs if getattr(inp, \\\"tool_mode\\\", False) and not getattr(inp, \\\"show\\\", True)\\n        ]\\n        assert len(triggers) >= 1, \\\"Expected at least one hidden input with tool_mode=True\\\"\\n\\n\\nclass TestBuildMetadata:\\n    \\\"\\\"\\\"Slice 24 \u2014 build_metadata returns introspective metadata (no I/O).\\\"\\\"\\\"\\n\\n    def test_should_return_sandbox_metadata_as_data(self, component: FileSystemToolComponent) -> None:\\n        result = component.build_metadata()\\n        assert result.data[\\\"root_path\\\"] == component.root_path\\n        assert result.data[\\\"read_only\\\"] is False\\n        assert set(result.data[\\\"tools_registered\\\"]) == {\\n            \\\"read_file\\\",\\n            \\\"write_file\\\",\\n            \\\"edit_file\\\",\\n            \\\"glob_search\\\",\\n            \\\"grep_search\\\",\\n        }\\n\\n    def test_should_reflect_read_only_in_tools_registered(self, sandbox: Path) -> None:\\n        component = FileSystemToolComponent(root_path=str(sandbox), read_only=True)\\n        result = component.build_metadata()\\n        assert result.data[\\\"read_only\\\"] is True\\n        assert set(result.data[\\\"tools_registered\\\"]) == {\\\"read_file\\\", \\\"glob_search\\\", \\\"grep_search\\\"}\\n\\n\\n# Note: TestRootPathAllowlist (Slice 27) was deleted with the refactor that\\n# replaced the legacy LANGFLOW_FS_TOOL_ALLOWED_ROOTS env var and the Astra cloud\\n# special-case with the AUTO_LOGIN-driven model. The boundary guarantee that\\n# class enforced (operator-controlled scope) is now provided by\\n# LANGFLOW_FS_TOOL_BASE_DIR + AUTO_LOGIN dispatch \u2014 covered by\\n# test_filesystem_isolation_integration.py.\\n\\n\\nclass TestGrepSearchReDoSGuard:\\n    \\\"\\\"\\\"Slice 28 \u2014 grep_search must not be DoS-able by a malicious regex.\\n\\n    The default mode is literal substring match. Regex mode is opt-in via\\n    `is_regex=True` and runs each match under a hard timeout so a\\n    catastrophic-backtracking pattern cannot pin a worker thread.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def _populate(self, sandbox: Path) -> None:\\n        # File whose contents would trigger catastrophic backtracking on the\\n        # naive `^(a+)+$` pattern under stdlib `re`.\\n        (sandbox / \\\"redos.txt\\\").write_text(\\\"a\\\" * 60 + \\\"X\\\\n\\\", encoding=\\\"utf-8\\\")\\n        (sandbox / \\\"lit.txt\\\").write_text(\\\"hello world\\\\nfoo.bar\\\\nbaz\\\\n\\\", encoding=\\\"utf-8\\\")\\n\\n    def test_default_mode_should_treat_pattern_as_literal_substring(self, component: FileSystemToolComponent) -> None:\\n        # `.` is a regex metachar but in literal mode it must match only a dot.\\n        result = component._grep_search(\\\"foo.bar\\\", path=\\\"lit.txt\\\", output_mode=\\\"content\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert any(\\\"foo.bar\\\" in entry[\\\"line\\\"] for entry in result[\\\"matches\\\"])\\n\\n    def test_default_literal_mode_should_not_match_regex_metachars(self, component: FileSystemToolComponent) -> None:\\n        # `h.llo` would match \\\"hello\\\" as a regex; in literal mode it must NOT.\\n        result = component._grep_search(\\\"h.llo\\\", path=\\\"lit.txt\\\", output_mode=\\\"content\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"matches\\\"] == []\\n\\n    def test_regex_mode_should_be_opt_in_and_compile_pattern(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(\\\"h.llo\\\", path=\\\"lit.txt\\\", output_mode=\\\"content\\\", is_regex=True)\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert any(\\\"hello\\\" in entry[\\\"line\\\"] for entry in result[\\\"matches\\\"])\\n\\n    def test_regex_mode_must_terminate_under_timeout_for_catastrophic_pattern(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        import time\\n\\n        # Stdlib `re` with `^(a+)+$` against 60 'a's followed by 'X' triggers\\n        # exponential backtracking \u2014 without a timeout this hangs the worker.\\n        # With our guard, it must return promptly with a structured error.\\n        start = time.monotonic()\\n        result = component._grep_search(r\\\"^(a+)+$\\\", path=\\\"redos.txt\\\", is_regex=True)\\n        elapsed = time.monotonic() - start\\n        assert elapsed < 5.0, f\\\"grep_search did not terminate promptly (took {elapsed:.1f}s)\\\"\\n        # Either the pattern was rejected up front, or the per-match timeout fired.\\n        assert \\\"error\\\" in result or result.get(\\\"truncated\\\") is True or result.get(\\\"matches\\\") == []\\n\\n\\nclass TestEditFileSizeProjection:\\n    \\\"\\\"\\\"Slice 29 \u2014 edit_file rejects empty old_string and projects size up front.\\n\\n    With `old_string=\\\"\\\"`, Python's `str.replace` inserts new_string between\\n    every character (and at both ends), producing roughly N*len(new_string)\\n    extra bytes. A small file plus a large new_string can blow far past\\n    MAX_FILE_SIZE_BYTES before the existing post-construction guard runs.\\n    \\\"\\\"\\\"\\n\\n    def test_should_reject_empty_old_string(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        # The reviewer-flagged DoS vector: with old_string=\\\"\\\", str.replace\\n        # inserts new_string between every character. The pre-fix code did\\n        # not reject empty old_string outright \u2014 it fell through to\\n        # current.count(\\\"\\\") == len(file)+1, then to the \\\"ambiguous matches\\\"\\n        # error path. That error message is misleading AND only blocks the\\n        # path coincidentally; with replace_all=True the unbounded\\n        # allocation would proceed. The fix MUST reject empty old_string\\n        # explicitly with a message that says \\\"empty\\\", not \\\"ambiguous\\\".\\n        result = component._edit_file(\\\"hello.txt\\\", old_string=\\\"\\\", new_string=\\\"X\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"empty\\\" in result[\\\"error\\\"].lower(), (\\n            f\\\"Expected 'empty' in error to distinguish from old 'ambiguous' rejection path. Got: {result['error']!r}\\\"\\n        )\\n        # File on disk must NOT have been modified.\\n        assert (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"line1\\\\nline2\\\\nline3\\\\n\\\"\\n\\n    def test_should_reject_empty_old_string_even_with_replace_all(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # The pre-fix code's \\\"ambiguous\\\" guard fired on empty old_string only\\n        # because `replace_all=False`. With `replace_all=True`, the\\n        # ambiguity check was bypassed and `current.replace(\\\"\\\", \\\"X\\\" * N)`\\n        # would balloon the file to N*(len+1)+len bytes BEFORE the\\n        # post-allocation size check. The fix MUST reject empty old_string\\n        # regardless of replace_all.\\n        result = component._edit_file(\\\"hello.txt\\\", old_string=\\\"\\\", new_string=\\\"X\\\", replace_all=True)\\n        assert \\\"error\\\" in result\\n        assert \\\"empty\\\" in result[\\\"error\\\"].lower(), f\\\"Got: {result['error']!r}\\\"\\n        # File on disk must NOT have been modified.\\n        assert (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"line1\\\\nline2\\\\nline3\\\\n\\\"\\n\\n    def test_should_still_allow_legitimate_replacements_within_limit(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # Sanity: a normal in-bounds edit still works after the new guard.\\n        result = component._edit_file(\\\"hello.txt\\\", old_string=\\\"line2\\\", new_string=\\\"LINE_TWO\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"line1\\\\nLINE_TWO\\\\nline3\\\\n\\\"\\n\\n\\nclass TestEditFileIdempotency:\\n    \\\"\\\"\\\"Slice 30 \u2014 re-running the same edit must not re-modify the file.\\n\\n    Idempotence here is \\\"second run is a structured no-op\\\": the first call\\n    succeeds, the second call returns a structured \\\"not found\\\" error (because\\n    old_string is gone after the first replacement), and the on-disk content\\n    is identical before and after the second call.\\n    \\\"\\\"\\\"\\n\\n    def test_should_be_idempotent_when_same_edit_runs_twice(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        first = component._edit_file(\\\"hello.txt\\\", old_string=\\\"line2\\\", new_string=\\\"LINE_TWO\\\")\\n        assert first[\\\"status\\\"] == \\\"ok\\\"\\n        assert first[\\\"replacements\\\"] == 1\\n        post_first = (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert post_first == \\\"line1\\\\nLINE_TWO\\\\nline3\\\\n\\\"\\n\\n        second = component._edit_file(\\\"hello.txt\\\", old_string=\\\"line2\\\", new_string=\\\"LINE_TWO\\\")\\n        assert \\\"error\\\" in second, f\\\"Expected structured error on re-run, got: {second}\\\"\\n        assert \\\"not found\\\" in second[\\\"error\\\"].lower()\\n\\n        # Disk state must be byte-identical to the post-first state \u2014 proves\\n        # the second call did not re-apply the edit nor corrupt the file.\\n        assert (sandbox / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == post_first\\n\\n    def test_should_be_idempotent_when_replace_all_runs_twice(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # Replace_all variant: a second run with no remaining matches must\\n        # still return \\\"not found\\\" rather than silently succeeding.\\n        (sandbox / \\\"repeat.txt\\\").write_text(\\\"foo\\\\nfoo\\\\nfoo\\\\n\\\", encoding=\\\"utf-8\\\")\\n        first = component._edit_file(\\\"repeat.txt\\\", old_string=\\\"foo\\\", new_string=\\\"bar\\\", replace_all=True)\\n        assert first[\\\"status\\\"] == \\\"ok\\\"\\n        assert first[\\\"replacements\\\"] == 3\\n        post_first = (sandbox / \\\"repeat.txt\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert post_first == \\\"bar\\\\nbar\\\\nbar\\\\n\\\"\\n\\n        second = component._edit_file(\\\"repeat.txt\\\", old_string=\\\"foo\\\", new_string=\\\"bar\\\", replace_all=True)\\n        assert \\\"error\\\" in second\\n        assert \\\"not found\\\" in second[\\\"error\\\"].lower()\\n        assert (sandbox / \\\"repeat.txt\\\").read_text(encoding=\\\"utf-8\\\") == post_first\\n\\n\\nclass TestGlobNestedDirectories:\\n    \\\"\\\"\\\"Slice 31 \u2014 glob_search descends through multiple nested directory levels.\\n\\n    Cross-platform: uses forward-slash glob patterns (Path.glob normalizes)\\n    and Path API for tree creation.\\n    \\\"\\\"\\\"\\n\\n    def test_should_find_file_in_deeply_nested_directory(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        deep = sandbox / \\\"a\\\" / \\\"b\\\" / \\\"c\\\" / \\\"d\\\"\\n        deep.mkdir(parents=True)\\n        (deep / \\\"leaf.py\\\").write_text(\\\"x = 1\\\\n\\\", encoding=\\\"utf-8\\\")\\n        result = component._glob_search(\\\"**/*.py\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert any(p.endswith(\\\"leaf.py\\\") for p in result[\\\"matches\\\"])\\n\\n    def test_should_find_files_across_multiple_nested_branches(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        for branch in (\\\"alpha/inner\\\", \\\"beta/inner\\\", \\\"gamma/inner\\\"):\\n            target = sandbox / Path(branch)\\n            target.mkdir(parents=True)\\n            (target / \\\"leaf.py\\\").write_text(\\\"x = 1\\\\n\\\", encoding=\\\"utf-8\\\")\\n        result = component._glob_search(\\\"**/*.py\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        leaf_matches = [p for p in result[\\\"matches\\\"] if p.endswith(\\\"leaf.py\\\")]\\n        # Three new branches must all be reachable via `**` traversal.\\n        assert len(leaf_matches) >= 3, f\\\"Expected >=3 leaf.py matches across branches, got: {leaf_matches}\\\"\\n\\n    def test_should_scope_nested_glob_to_subdirectory(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        # Confirms that descending traversal also respects the `path` scope \u2014\\n        # i.e., **/*.py inside `nested/` should not see siblings outside it.\\n        deep = sandbox / \\\"nested\\\" / \\\"deeper\\\" / \\\"deepest\\\"\\n        deep.mkdir(parents=True)\\n        (deep / \\\"scoped.py\\\").write_text(\\\"x = 1\\\\n\\\", encoding=\\\"utf-8\\\")\\n        (sandbox / \\\"outside.py\\\").write_text(\\\"x = 1\\\\n\\\", encoding=\\\"utf-8\\\")\\n        result = component._glob_search(\\\"**/*.py\\\", path=\\\"nested\\\")\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert any(p.endswith(\\\"scoped.py\\\") for p in result[\\\"matches\\\"])\\n        assert not any(p.endswith(\\\"outside.py\\\") for p in result[\\\"matches\\\"])\\n\\n\\nclass TestSandboxStructuredErrorAtPublicLevel:\\n    \\\"\\\"\\\"Slice 32 \u2014 sandbox violations surface as structured errors via public methods.\\n\\n    The agent never sees a raised PermissionError; it always sees a\\n    JSON-serializable dict with an `error` key. This locks in the contract\\n    for all three escape forms (`..` traversal, symlink-out, absolute-path-out).\\n    Cross-platform: uses tmp_path.parent for \\\"absolute path outside root\\\"\\n    instead of POSIX-only paths like /etc/passwd.\\n    \\\"\\\"\\\"\\n\\n    def test_read_file_should_return_structured_error_for_absolute_path_outside_root(\\n        self, component: FileSystemToolComponent, tmp_path: Path\\n    ) -> None:\\n        outside_abs = str(tmp_path.parent)\\n        result = component._read_file(outside_abs)\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_read_file_should_return_structured_error_for_symlink_escaping_root(\\n        self, component: FileSystemToolComponent, sandbox: Path, tmp_path: Path\\n    ) -> None:\\n        outside = tmp_path.parent / f\\\"{tmp_path.name}-public-escape.txt\\\"\\n        outside.write_text(\\\"secret\\\", encoding=\\\"utf-8\\\")\\n        symlink = sandbox / \\\"escape_link_public\\\"\\n        try:\\n            symlink.symlink_to(outside)\\n        except (OSError, NotImplementedError) as exc:\\n            # Windows without Developer Mode rejects unprivileged symlinks.\\n            # In that case the test premise can't be set up; skip rather than\\n            # fail spuriously, since the production guard is the same.\\n            pytest.skip(f\\\"Symlink creation unsupported in this environment: {exc}\\\")\\n        result = component._read_file(\\\"escape_link_public\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_write_file_should_return_structured_error_for_absolute_path_outside_root(\\n        self, component: FileSystemToolComponent, tmp_path: Path\\n    ) -> None:\\n        outside_abs = str(tmp_path.parent / \\\"should_not_be_created.txt\\\")\\n        result = component._write_file(outside_abs, \\\"x\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n        # And the side effect MUST NOT have happened.\\n        assert not (tmp_path.parent / \\\"should_not_be_created.txt\\\").exists()\\n\\n    def test_edit_file_should_return_structured_error_for_absolute_path_outside_root(\\n        self, component: FileSystemToolComponent, tmp_path: Path\\n    ) -> None:\\n        outside_abs = str(tmp_path.parent)\\n        result = component._edit_file(outside_abs, old_string=\\\"x\\\", new_string=\\\"y\\\")\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_glob_search_should_return_structured_error_for_absolute_scope_outside_root(\\n        self, component: FileSystemToolComponent, tmp_path: Path\\n    ) -> None:\\n        result = component._glob_search(\\\"*.txt\\\", path=str(tmp_path.parent))\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_grep_search_should_return_structured_error_for_absolute_scope_outside_root(\\n        self, component: FileSystemToolComponent, tmp_path: Path\\n    ) -> None:\\n        result = component._grep_search(\\\"foo\\\", path=str(tmp_path.parent))\\n        assert \\\"error\\\" in result\\n        assert \\\"escape\\\" in result[\\\"error\\\"].lower() or \\\"boundary\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestStructuredToolErrorEnvelope:\\n    \\\"\\\"\\\"Slice 33 \u2014 StructuredTool wrappers serialize errors as JSON envelopes.\\n\\n    The Tool Mode contract: the agent invokes a StructuredTool and receives a\\n    string. That string MUST be JSON-decodable into a dict whose `error` key\\n    explains the failure \u2014 never an unhandled Python exception that surfaces\\n    as a tool-call crash to the agent loop.\\n    \\\"\\\"\\\"\\n\\n    async def test_read_tool_wrapper_should_return_json_error_for_dotdot_escape(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        tools = {tool.name: tool for tool in await component._get_tools()}\\n        output = tools[\\\"read_file\\\"].invoke({\\\"path\\\": \\\"../escape.txt\\\"})\\n        payload = json.loads(output)\\n        assert \\\"error\\\" in payload\\n\\n    async def test_glob_tool_wrapper_should_return_json_error_for_dotdot_scope(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        tools = {tool.name: tool for tool in await component._get_tools()}\\n        output = tools[\\\"glob_search\\\"].invoke({\\\"pattern\\\": \\\"*.txt\\\", \\\"path\\\": \\\"../\\\"})\\n        payload = json.loads(output)\\n        assert \\\"error\\\" in payload\\n\\n    async def test_grep_tool_wrapper_should_return_json_error_for_dotdot_scope(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        tools = {tool.name: tool for tool in await component._get_tools()}\\n        output = tools[\\\"grep_search\\\"].invoke({\\\"pattern\\\": \\\"foo\\\", \\\"path\\\": \\\"../\\\"})\\n        payload = json.loads(output)\\n        assert \\\"error\\\" in payload\\n\\n    async def test_write_tool_wrapper_should_return_json_error_for_dotdot_escape(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        tools = {tool.name: tool for tool in await component._get_tools()}\\n        output = tools[\\\"write_file\\\"].invoke({\\\"path\\\": \\\"../escape.txt\\\", \\\"content\\\": \\\"x\\\"})\\n        payload = json.loads(output)\\n        assert \\\"error\\\" in payload\\n\\n    async def test_edit_tool_wrapper_should_return_json_error_for_dotdot_escape(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        tools = {tool.name: tool for tool in await component._get_tools()}\\n        output = tools[\\\"edit_file\\\"].invoke(\\n            {\\\"path\\\": \\\"../escape.txt\\\", \\\"old_string\\\": \\\"x\\\", \\\"new_string\\\": \\\"y\\\"},\\n        )\\n        payload = json.loads(output)\\n        assert \\\"error\\\" in payload\\n\\n\\nclass TestBug02GlobTruncationDropsNestedSilently:\\n    \\\"\\\"\\\"BUG-02 (T2-001) \u2014 `glob_search` silently drops nested results when truncated.\\n\\n    Scenario from the report: a flat sibling directory with 100+ matches fills\\n    the result cap entirely, and files in nested subdirectories are silently\\n    omitted with no signal beyond `truncated: True`. The agent has no way to\\n    learn which branches went unrepresented.\\n\\n    Fix contract: when truncation occurs, the response must enumerate the\\n    top-level branches under the search base whose matches were not surfaced,\\n    so the agent can narrow with a `path=` argument and recover them.\\n    \\\"\\\"\\\"\\n\\n    def test_should_signal_truncated_branches_when_flat_dir_fills_cap_and_nested_branch_is_dropped(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # Arrange \u2014 exactly the bug-report scenario.\\n        flat = sandbox / \\\"flat\\\"\\n        flat.mkdir()\\n        for i in range(110):\\n            (flat / f\\\"f{i:03d}.txt\\\").write_text(\\\"x\\\", encoding=\\\"utf-8\\\")\\n        deep = sandbox / \\\"deep\\\" / \\\"deeper\\\" / \\\"deepest\\\"\\n        deep.mkdir(parents=True)\\n        (deep / \\\"must_find_me.txt\\\").write_text(\\\"important\\\", encoding=\\\"utf-8\\\")\\n\\n        # Act\\n        result = component._glob_search(\\\"**/*.txt\\\")\\n\\n        # Assert \u2014 agent must NOT silently lose the nested branch.\\n        assert result[\\\"status\\\"] == \\\"ok\\\"\\n        assert result[\\\"truncated\\\"] is True\\n        # The nested branch must be discoverable from the response: either\\n        # `must_find_me.txt` is in matches, or `deep` is named in the\\n        # truncation signal so the agent knows where to look.\\n        nested_in_matches = any(\\\"must_find_me.txt\\\" in p for p in result[\\\"matches\\\"])\\n        truncated_branches = result.get(\\\"truncated_branches\\\", [])\\n        deep_in_signal = \\\"deep\\\" in truncated_branches\\n        assert nested_in_matches or deep_in_signal, (\\n            \\\"When truncation drops a whole branch, the response MUST surface \\\"\\n            \\\"either the file itself or the branch name. \\\"\\n            f\\\"matches sample={result['matches'][:3]}, \\\"\\n            f\\\"truncated_branches={truncated_branches}\\\"\\n        )\\n\\n    def test_should_emit_truncated_branches_field_when_truncated_is_true(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # Stricter: the structured-error contract for truncation is that\\n        # `truncated_branches` exists alongside `truncated: True`.\\n        flat = sandbox / \\\"flat\\\"\\n        flat.mkdir()\\n        for i in range(110):\\n            (flat / f\\\"f{i:03d}.txt\\\").write_text(\\\"x\\\", encoding=\\\"utf-8\\\")\\n        deep = sandbox / \\\"deep\\\"\\n        deep.mkdir()\\n        (deep / \\\"leaf.txt\\\").write_text(\\\"y\\\", encoding=\\\"utf-8\\\")\\n\\n        result = component._glob_search(\\\"**/*.txt\\\")\\n        assert result[\\\"truncated\\\"] is True\\n        assert \\\"truncated_branches\\\" in result, (\\n            \\\"When truncated=True the response MUST include `truncated_branches` \\\"\\n            f\\\"so the agent has a non-silent signal. Got keys: {list(result.keys())}\\\"\\n        )\\n        # Sorted, deterministic, top-level relative paths under the search base.\\n        assert isinstance(result[\\\"truncated_branches\\\"], list)\\n        assert result[\\\"truncated_branches\\\"] == sorted(result[\\\"truncated_branches\\\"])\\n\\n    def test_should_have_empty_truncated_branches_when_not_truncated(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        # Sanity: small result set must not falsely report truncated branches.\\n        (sandbox / \\\"a.txt\\\").write_text(\\\"x\\\", encoding=\\\"utf-8\\\")\\n        (sandbox / \\\"b.txt\\\").write_text(\\\"y\\\", encoding=\\\"utf-8\\\")\\n        result = component._glob_search(\\\"*.txt\\\")\\n        assert result[\\\"truncated\\\"] is False\\n        assert result.get(\\\"truncated_branches\\\", []) == []\\n\\n\\nclass TestEmptyRootPathDoesNotLeakCwd:\\n    \\\"\\\"\\\"Sub-path empty/None/whitespace must NOT make the tool read from CWD.\\n\\n    Original BUG-03 (UI-022): with the legacy ``required=True`` field, agents\\n    bypassing the UI could pass empty/None and land on ``Path(\\\"\\\").resolve()`` =\\n    process CWD. That contract is gone \u2014 empty sub_path is now a valid value\\n    meaning \\\"root of my namespace\\\". The remaining security guarantee is: it\\n    must resolve under ``<BASE>/<namespace>/``, NEVER under the host CWD.\\n    \\\"\\\"\\\"\\n\\n    def test_should_anchor_empty_sub_path_to_base_not_cwd_in_shared_mode(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        # Pre-condition: a marker file lives in CWD. If empty sub_path leaked\\n        # to CWD again, the agent could read it.\\n        cwd_dir = tmp_path / \\\"cwd\\\"\\n        cwd_dir.mkdir()\\n        marker = cwd_dir / \\\"leak.txt\\\"\\n        marker.write_text(\\\"must_not_leak\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.chdir(cwd_dir)\\n\\n        base = tmp_path / \\\"base\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(base))\\n\\n        component = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n        component._resolve_auto_login = lambda: True  # type: ignore[method-assign]\\n\\n        result = component._read_file(marker.name)\\n\\n        assert \\\"error\\\" in result, f\\\"Empty sub_path leaked to CWD: {result}\\\"\\n\\n    @pytest.mark.parametrize(\\\"blank_value\\\", [\\\"\\\", \\\"   \\\", None])\\n    def test_should_treat_blank_sub_path_as_namespace_root_in_shared_mode(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, blank_value\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(base))\\n\\n        component = FileSystemToolComponent(root_path=blank_value, read_only=False)\\n        component._resolve_auto_login = lambda: True  # type: ignore[method-assign]\\n\\n        result = component._write_file(\\\"hello.txt\\\", \\\"ok\\\")\\n\\n        assert result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, result\\n        assert (base / \\\"shared\\\" / \\\"hello.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"ok\\\"\\n\\n    @pytest.mark.parametrize(\\n        \\\"method_call\\\",\\n        [\\n            lambda c: c._read_file(\\\"a.txt\\\"),\\n            lambda c: c._write_file(\\\"a.txt\\\", \\\"x\\\"),\\n            lambda c: c._edit_file(\\\"a.txt\\\", old_string=\\\"x\\\", new_string=\\\"y\\\"),\\n            lambda c: c._glob_search(\\\"**/*\\\"),\\n            lambda c: c._grep_search(\\\"foo\\\"),\\n        ],\\n        ids=[\\\"read\\\", \\\"write\\\", \\\"edit\\\", \\\"glob\\\", \\\"grep\\\"],\\n    )\\n    def test_should_refuse_when_isolated_and_no_user_id(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, method_call\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(base))\\n\\n        component = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n        component._resolve_auto_login = lambda: False  # type: ignore[method-assign]\\n\\n        result = method_call(component)\\n\\n        assert \\\"error\\\" in result, f\\\"Isolated mode without user_id must refuse: {result}\\\"\\n        assert \\\"user\\\" in result[\\\"error\\\"].lower() or \\\"authenticated\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestResolveUserIdEndUser:\\n    \\\"\\\"\\\"Serving-plane: the end user owns files they write, so their id wins the sandbox namespace.\\n\\n    ``_resolve_user_id`` picks the namespace the sandbox tool reads/writes under. On a serving run\\n    the graph carries ``end_user_id`` (an identified end user); it must beat the executing service\\n    account. When absent (editor / anonymous / feature-off) it falls through to the SID (strict BC).\\n    \\\"\\\"\\\"\\n\\n    def test_end_user_wins_over_sid(self, component: FileSystemToolComponent) -> None:\\n        from types import SimpleNamespace\\n\\n        component._user_id = \\\"sid-1111\\\"\\n        component._vertex = SimpleNamespace(graph=SimpleNamespace(end_user_id=\\\"alice\\\", user_id=\\\"sid-1111\\\"))\\n        assert component._resolve_user_id() == \\\"alice\\\"\\n\\n    def test_falls_back_to_sid_without_end_user(self, component: FileSystemToolComponent) -> None:\\n        from types import SimpleNamespace\\n\\n        component._user_id = \\\"sid-1111\\\"\\n        component._vertex = SimpleNamespace(graph=SimpleNamespace(end_user_id=None, user_id=\\\"sid-1111\\\"))\\n        assert component._resolve_user_id() == \\\"sid-1111\\\"\\n\\n    def test_placeholder_end_user_is_ignored(self, component: FileSystemToolComponent) -> None:\\n        # A PlaceholderGraph stringifies a missing end user as \\\"None\\\"; it must not create a\\n        # spurious namespace \u2014 fall through to the SID.\\n        from types import SimpleNamespace\\n\\n        component._user_id = \\\"sid-1111\\\"\\n        component._vertex = SimpleNamespace(graph=SimpleNamespace(end_user_id=\\\"None\\\", user_id=\\\"sid-1111\\\"))\\n        assert component._resolve_user_id() == \\\"sid-1111\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_deny_list.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0b1d20decc97cd85c303ff469f5a168bd29a2a3a4ed8dcca02a4cd0d20b3cbdc\",\"content\":\"\\\"\\\"\\\"Regression for the unenforced credential deny-list (dead code).\\n\\n``filesystem.py`` defines ``_DENY_BASENAME_LITERALS`` / ``_PREFIXES`` /\\n``_SUFFIXES`` / ``_DENY_PATH_FRAGMENTS`` documented as the\\n\\\"default-deny inside an allowed root\\\" control, but no code referenced\\nthem: any ``.env`` / private key / ``.ssh`` file inside the sandbox was\\nfully readable, writable, editable, glob-able and grep-able.\\n\\nThe deny check must be pure-string and run before any I/O, so the agent\\ncannot distinguish a denied-existing file from a denied-absent one.\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\nSENTINEL_VALUE = \\\"sk-fake-secret-12345\\\"\\n\\n\\n@pytest.fixture\\ndef sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    shared = tmp_path / \\\"shared\\\"\\n    shared.mkdir(parents=True, exist_ok=True)\\n    (shared / \\\".env\\\").write_text(f\\\"API_KEY={SENTINEL_VALUE}\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (shared / \\\"id_rsa\\\").write_text(f\\\"FAKE PRIVATE KEY {SENTINEL_VALUE}\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (shared / \\\"secret.pem\\\").write_text(f\\\"-----BEGIN FAKE KEY----- {SENTINEL_VALUE}\\\\n\\\", encoding=\\\"utf-8\\\")\\n    ssh_dir = shared / \\\".ssh\\\"\\n    ssh_dir.mkdir()\\n    (ssh_dir / \\\"config\\\").write_text(f\\\"Host fakehost {SENTINEL_VALUE}\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (shared / \\\"notes.txt\\\").write_text(\\\"plain allowed file\\\\n\\\", encoding=\\\"utf-8\\\")\\n    return shared\\n\\n\\n@pytest.fixture\\ndef component(sandbox: Path, monkeypatch: pytest.MonkeyPatch) -> FileSystemToolComponent:  # noqa: ARG001\\n    c = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n    monkeypatch.setattr(c, \\\"_resolve_auto_login\\\", lambda: True)\\n    return c\\n\\n\\nDENIED_PATHS = [\\n    pytest.param(\\\".env\\\", id=\\\"literal-dotenv\\\"),\\n    pytest.param(\\\"id_rsa\\\", id=\\\"prefix-id_rsa\\\"),\\n    pytest.param(\\\"id_rsa.pub\\\", id=\\\"prefix-id_rsa-pub\\\"),\\n    pytest.param(\\\"secret.pem\\\", id=\\\"suffix-pem\\\"),\\n    pytest.param(\\\".ssh/config\\\", id=\\\"fragment-ssh\\\"),\\n    pytest.param(\\\".ENV\\\", id=\\\"literal-case-insensitive\\\"),\\n    pytest.param(\\\"ID_RSA\\\", id=\\\"prefix-case-insensitive\\\"),\\n    pytest.param(\\\"SECRET.PEM\\\", id=\\\"suffix-case-insensitive\\\"),\\n    pytest.param(\\\".SSH/config\\\", id=\\\"fragment-case-insensitive\\\"),\\n    pytest.param(\\\"nested/.aws/credentials\\\", id=\\\"fragment-nested-aws\\\"),\\n]\\n\\n\\nclass TestDenyListRead:\\n    @pytest.mark.parametrize(\\\"path\\\", DENIED_PATHS)\\n    def test_should_deny_read_when_path_matches_credential_pattern(\\n        self, component: FileSystemToolComponent, path: str\\n    ) -> None:\\n        result = component._read_file(path)\\n\\n        assert \\\"error\\\" in result, f\\\"deny-list did not fire for {path!r}; result={result!r}\\\"\\n        assert SENTINEL_VALUE not in json.dumps(result)\\n\\n    def test_should_deny_before_io_when_denied_file_does_not_exist(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\".netrc\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" not in result[\\\"error\\\"].lower(), (\\n            \\\"deny must fire before existence is observed, error was: \\\" + result[\\\"error\\\"]\\n        )\\n\\n    def test_should_still_read_allowed_file(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\"notes.txt\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\", f\\\"allowed file was blocked: {result!r}\\\"\\n\\n    def test_should_not_deny_when_literal_is_only_a_name_prefix(self, component: FileSystemToolComponent) -> None:\\n        result = component._read_file(\\\".env.local\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"denied\\\" not in result[\\\"error\\\"].lower(), \\\".env.local must not match the exact-literal rule\\\"\\n\\n\\nclass TestDenyListWrite:\\n    def test_should_deny_write_when_basename_matches_literal(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        result = component._write_file(\\\".pgpass\\\", \\\"db:5432:*:user:hunter2\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert not (sandbox / \\\".pgpass\\\").exists()\\n\\n    def test_should_deny_write_when_directory_matches_fragment(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        result = component._write_file(\\\".kube/config\\\", \\\"apiVersion: v1\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert not (sandbox / \\\".kube\\\").exists()\\n\\n\\nclass TestDenyListEdit:\\n    def test_should_deny_edit_when_path_matches_credential_pattern(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        result = component._edit_file(\\\".env\\\", old_string=SENTINEL_VALUE, new_string=\\\"changed\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert SENTINEL_VALUE in (sandbox / \\\".env\\\").read_text(encoding=\\\"utf-8\\\")\\n\\n\\nclass TestDenyListSymlinkAlias:\\n    \\\"\\\"\\\"A symlink whose own name is innocuous must not alias a denied target.\\n\\n    The deny check runs on the input string; ``.resolve()`` follows the link\\n    afterwards, so without a post-resolution check an ``alias -> .env`` symlink\\n    (which a shared-root workspace can acquire out-of-band) reads ``.env``.\\n    \\\"\\\"\\\"\\n\\n    def test_should_deny_read_when_symlink_aliases_a_denied_file(\\n        self, component: FileSystemToolComponent, sandbox: Path\\n    ) -> None:\\n        alias = sandbox / \\\"alias\\\"\\n        alias.symlink_to(sandbox / \\\".env\\\")\\n\\n        result = component._read_file(\\\"alias\\\")\\n\\n        assert \\\"error\\\" in result, f\\\"symlink alias bypassed the deny-list; result={result!r}\\\"\\n        assert SENTINEL_VALUE not in json.dumps(result)\\n\\n    def test_should_still_read_allowed_symlink_target(self, component: FileSystemToolComponent, sandbox: Path) -> None:\\n        alias = sandbox / \\\"notes_link\\\"\\n        alias.symlink_to(sandbox / \\\"notes.txt\\\")\\n\\n        result = component._read_file(\\\"notes_link\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\", f\\\"allowed symlink target was blocked: {result!r}\\\"\\n\\n\\nclass TestDenyListProtectedDirectoryBasename:\\n    \\\"\\\"\\\"A path whose final component IS a protected directory name must be denied.\\n\\n    Previously the basename was matched only against literal/prefix/suffix rules,\\n    never against ``_DENY_PATH_FRAGMENTS``. Requesting ``.ssh`` / ``.aws`` /\\n    ``.git`` directly therefore fell through to I/O and leaked a\\n    \\\"directory vs not-found\\\" existence signal, and a ``**/*`` glob could surface\\n    the protected directory entry itself even when its children were filtered.\\n    \\\"\\\"\\\"\\n\\n    PROTECTED_DIR_BASENAMES = [\\n        pytest.param(\\\".ssh\\\", id=\\\"ssh\\\"),\\n        pytest.param(\\\".aws\\\", id=\\\"aws\\\"),\\n        pytest.param(\\\".git\\\", id=\\\"git\\\"),\\n        pytest.param(\\\".SSH\\\", id=\\\"ssh-case-insensitive\\\"),\\n        pytest.param(\\\"nested/.aws\\\", id=\\\"nested-aws\\\"),\\n    ]\\n\\n    @pytest.mark.parametrize(\\\"path\\\", PROTECTED_DIR_BASENAMES)\\n    def test_should_deny_read_when_basename_is_protected_directory(\\n        self, component: FileSystemToolComponent, path: str\\n    ) -> None:\\n        result = component._read_file(path)\\n\\n        assert \\\"error\\\" in result, f\\\"deny-list did not fire for protected directory {path!r}; result={result!r}\\\"\\n        assert \\\"not found\\\" not in result[\\\"error\\\"].lower(), (\\n            \\\"deny must fire before existence is observed (no directory-vs-not-found leak), \\\"\\n            f\\\"error was: {result['error']}\\\"\\n        )\\n\\n\\nclass TestDenyListGlob:\\n    def test_should_omit_denied_files_when_globbing_workspace(self, component: FileSystemToolComponent) -> None:\\n        result = component._glob_search(\\\"**/*\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\"\\n        denied_hits = [m for m in result[\\\"matches\\\"] if Path(m).name in {\\\".env\\\", \\\"id_rsa\\\", \\\"secret.pem\\\", \\\"config\\\"}]\\n        assert denied_hits == [], f\\\"glob leaked denied files: {denied_hits}\\\"\\n        assert \\\"notes.txt\\\" in result[\\\"matches\\\"]\\n\\n    def test_should_omit_protected_directory_entry_when_globbing(self, component: FileSystemToolComponent) -> None:\\n        result = component._glob_search(\\\"**/*\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\"\\n        fragment_entries = [m for m in result[\\\"matches\\\"] if Path(m).name in {\\\".ssh\\\", \\\".aws\\\", \\\".git\\\"}]\\n        assert fragment_entries == [], f\\\"glob returned a protected directory entry: {fragment_entries}\\\"\\n\\n\\nclass TestDenyListGrep:\\n    def test_should_not_leak_denied_content_when_grepping_parent_directory(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        result = component._grep_search(SENTINEL_VALUE, output_mode=\\\"content\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\"\\n        assert result[\\\"matches\\\"] == [], f\\\"grep leaked denied file content: {result['matches']!r}\\\"\\n\\n    def test_should_not_list_denied_files_when_grepping_parent_directory(\\n        self, component: FileSystemToolComponent\\n    ) -> None:\\n        result = component._grep_search(SENTINEL_VALUE, output_mode=\\\"files_with_matches\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\"\\n        assert result[\\\"matches\\\"] == []\\n\\n    def test_should_still_grep_allowed_files(self, component: FileSystemToolComponent) -> None:\\n        result = component._grep_search(\\\"plain allowed\\\", output_mode=\\\"files_with_matches\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\"\\n        assert result[\\\"matches\\\"] == [\\\"notes.txt\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_force_isolation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bb70c07b29dc34163166a3cc932dceba77c7b5c5a26a00e8355ce277c94c35f4\",\"content\":\"\\\"\\\"\\\"B1 \u2014 `_force_isolation` flag on FileSystemToolComponent.\\n\\nThe agentic API surface (files_router, the agent's write tools) carries an\\nauthenticated user_id and must always resolve a per-user sandbox root \u2014\\neven when ``AUTO_LOGIN=True``. Today ``_validate_root`` returns the shared\\nroot whenever AUTO_LOGIN is True, so two distinct users in a multi-user\\ndeployment running default auth resolve to the same root and can read each\\nother's files. The new ``_force_isolation`` flag closes that gap without\\nchanging default behavior for any other caller (default False).\\n\\nCross-platform: only ``pathlib`` and a tmp_path fixture \u2014 no POSIX paths.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _make_component(\\n    *,\\n    monkeypatch: pytest.MonkeyPatch,\\n    base_dir: Path,\\n    auto_login: bool,\\n    user_id: str | None = None,\\n    force_isolation: bool = False,\\n    sub_path: str = \\\"\\\",\\n) -> FileSystemToolComponent:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(base_dir))\\n    component = FileSystemToolComponent(root_path=sub_path)\\n    component._resolve_auto_login = lambda: auto_login  # type: ignore[method-assign]\\n    if user_id is not None:\\n        component._user_id = user_id\\n    if force_isolation:\\n        component._force_isolation = True\\n    return component\\n\\n\\nclass TestForceIsolationOverridesAutoLogin:\\n    \\\"\\\"\\\"The flag forces the per-user root even under AUTO_LOGIN=True.\\\"\\\"\\\"\\n\\n    def test_should_write_to_per_user_root_when_force_isolation_and_auto_login_true(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            user_id=\\\"user-alice\\\",\\n            force_isolation=True,\\n        )\\n\\n        result = component._write_file(\\\"notes.md\\\", \\\"hello\\\")\\n\\n        assert result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, result\\n        # The file must NOT land in the shared root.\\n        assert not (base / \\\"shared\\\" / \\\"notes.md\\\").exists()\\n        # It must land under users/<hash(alice)>/.\\n        users_root = base / \\\"users\\\"\\n        assert users_root.exists(), \\\"users/ namespace should be materialized\\\"\\n        candidates = list(users_root.glob(\\\"*/notes.md\\\"))\\n        assert len(candidates) == 1, candidates\\n        assert candidates[0].read_text(encoding=\\\"utf-8\\\") == \\\"hello\\\"\\n\\n    def test_should_isolate_two_users_under_auto_login_when_force_isolation(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        alice = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            user_id=\\\"user-alice\\\",\\n            force_isolation=True,\\n        )\\n        bob = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            user_id=\\\"user-bob\\\",\\n            force_isolation=True,\\n        )\\n\\n        alice._write_file(\\\"secret.md\\\", \\\"alice-owned\\\")\\n        bob_path_resolved = bob._validate_path(\\\"secret.md\\\")\\n        alice_path_resolved = alice._validate_path(\\\"secret.md\\\")\\n\\n        # Different physical files = isolation holds even under AUTO_LOGIN.\\n        assert bob_path_resolved != alice_path_resolved\\n        assert not bob_path_resolved.exists(), \\\"bob must not see alice's file\\\"\\n        assert alice_path_resolved.read_text(encoding=\\\"utf-8\\\") == \\\"alice-owned\\\"\\n\\n    def test_should_raise_permission_error_when_force_isolation_without_user_id(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            user_id=None,\\n            force_isolation=True,\\n        )\\n\\n        with pytest.raises(PermissionError, match=\\\"requires an authenticated user\\\"):\\n            component._validate_root()\\n\\n\\nclass TestDefaultBehaviorUnchanged:\\n    \\\"\\\"\\\"No flag set \u21d2 AUTO_LOGIN dispatch is unchanged \u2014 backward compat.\\\"\\\"\\\"\\n\\n    def test_should_use_shared_root_when_force_isolation_default_and_auto_login_true(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            user_id=\\\"user-alice\\\",\\n            force_isolation=False,\\n        )\\n\\n        component._write_file(\\\"notes.md\\\", \\\"hello\\\")\\n\\n        assert (base / \\\"shared\\\" / \\\"notes.md\\\").read_text(encoding=\\\"utf-8\\\") == \\\"hello\\\"\\n        assert not (base / \\\"users\\\").exists() or not list((base / \\\"users\\\").glob(\\\"*\\\"))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_isolation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"146bb952a7604d213b7204999e94bf236f496ec3bcd2ed2e693f33aa607e8e24\",\"content\":\"\\\"\\\"\\\"Unit tests for the isolation config layer of the FileSystem tool.\\n\\nThe config layer owns ONE responsibility: turn environment configuration into a\\nfrozen ``IsolationConfig`` so the component code can treat it as immutable data.\\n\\nSingle env var: ``LANGFLOW_FS_TOOL_BASE_DIR``. Pepper file is auto-derived under\\n``<base>/.fs_pepper``. Behavior (shared vs isolated) is decided by the\\ncomponent at call time based on ``AUTO_LOGIN``, NOT by the config.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\nclass TestLoadIsolationConfig:\\n    \\\"\\\"\\\"``load_isolation_config`` reads env vars into a frozen ``IsolationConfig``.\\\"\\\"\\\"\\n\\n    def test_should_default_base_dir_under_default_config_dir_when_env_var_unset(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_isolation import load_isolation_config\\n\\n        config = load_isolation_config(env={}, default_config_dir=tmp_path)\\n\\n        assert config.base_dir == (tmp_path / \\\"fs_sandbox\\\").resolve()\\n\\n    def test_should_derive_pepper_path_under_base_dir(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_isolation import load_isolation_config\\n\\n        config = load_isolation_config(env={}, default_config_dir=tmp_path)\\n\\n        assert config.pepper_path == (tmp_path / \\\"fs_sandbox\\\" / \\\".fs_pepper\\\").resolve()\\n\\n    def test_should_override_base_dir_when_env_var_is_set(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_isolation import load_isolation_config\\n\\n        custom_base = tmp_path / \\\"custom_root\\\"\\n        env = {\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\": str(custom_base)}\\n\\n        config = load_isolation_config(env=env, default_config_dir=tmp_path)\\n\\n        assert config.base_dir == custom_base.resolve()\\n\\n    def test_should_track_pepper_path_under_overridden_base_dir(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_isolation import load_isolation_config\\n\\n        custom_base = tmp_path / \\\"custom_root\\\"\\n        env = {\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\": str(custom_base)}\\n\\n        config = load_isolation_config(env=env, default_config_dir=tmp_path)\\n\\n        assert config.pepper_path == (custom_base / \\\".fs_pepper\\\").resolve()\\n\\n    def test_should_treat_empty_base_dir_env_var_as_unset(self, tmp_path: Path) -> None:\\n        # Empty env var must NOT make the component fail closed at config-read\\n        # time \u2014 falling back to the default keeps OSS / desktop installs alive\\n        # when an operator clears the var without thinking.\\n        from lfx.components.files_and_knowledge._filesystem_isolation import load_isolation_config\\n\\n        env = {\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\": \\\"\\\"}\\n\\n        config = load_isolation_config(env=env, default_config_dir=tmp_path)\\n\\n        assert config.base_dir == (tmp_path / \\\"fs_sandbox\\\").resolve()\\n\\n    def test_should_be_immutable(self, tmp_path: Path) -> None:\\n        # The config is read once per call and threaded through every helper;\\n        # mutating it mid-flight would invite TOCTOU bugs where one operation\\n        # sees one base_dir and another sees a different one.\\n        from lfx.components.files_and_knowledge._filesystem_isolation import load_isolation_config\\n\\n        config = load_isolation_config(env={}, default_config_dir=tmp_path)\\n\\n        with pytest.raises((AttributeError, TypeError)):\\n            config.base_dir = tmp_path / \\\"other\\\"  # type: ignore[misc]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_isolation_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e730fc7767c5453dac249d8c9dcf0172beb602950494ba91c7ad19a897fdbb0b\",\"content\":\"\\\"\\\"\\\"End-to-end integration tests for AUTO_LOGIN-driven isolation in FileSystemToolComponent.\\n\\nThe dispatch table:\\n\\n    AUTO_LOGIN=True             \u2192 <BASE>/shared/<sub_path>/...\\n    AUTO_LOGIN=False + user     \u2192 <BASE>/users/<hash(user_id)>/<sub_path>/...\\n    AUTO_LOGIN=False + no user  \u2192 structured error\\n\\nThreats covered:\\n    T1 \u2014 User B reads user A's files via the same flow\\n    T2 \u2014 Anonymous run in multi-user mode (AUTO_LOGIN=False without user)\\n    T3 \u2014 Sub-path traversal attempts in either mode\\n    T4 \u2014 `.lfsig` reserved tree\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _make_component(\\n    *,\\n    monkeypatch: pytest.MonkeyPatch,\\n    base_dir: Path,\\n    auto_login: bool,\\n    user_id: str | None = None,\\n    sub_path: str = \\\"\\\",\\n    read_only: bool = False,\\n) -> FileSystemToolComponent:\\n    \\\"\\\"\\\"Build a component with the AUTO_LOGIN flag pinned for the test.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(base_dir))\\n\\n    component = FileSystemToolComponent(root_path=sub_path, read_only=read_only)\\n    # Per-instance override avoids pulling in the global settings service.\\n    component._resolve_auto_login = lambda: auto_login  # type: ignore[method-assign]\\n    if user_id is not None:\\n        component._user_id = user_id\\n    return component\\n\\n\\nclass TestSharedModeWhenAutoLoginTrue:\\n    \\\"\\\"\\\"Slice S3 \u2014 AUTO_LOGIN=True puts every file under <BASE>/shared/<sub>.\\\"\\\"\\\"\\n\\n    def test_should_create_files_inside_shared_namespace(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            sub_path=\\\"\\\",\\n        )\\n\\n        write_result = component._write_file(\\\"notes.md\\\", \\\"hello\\\")\\n\\n        assert write_result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, write_result\\n        assert (base / \\\"shared\\\" / \\\"notes.md\\\").read_text(encoding=\\\"utf-8\\\") == \\\"hello\\\"\\n\\n    def test_should_treat_root_path_as_subpath_under_shared(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            sub_path=\\\"projects/demo\\\",\\n        )\\n\\n        write_result = component._write_file(\\\"notes.md\\\", \\\"demo\\\")\\n\\n        assert write_result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, write_result\\n        assert (base / \\\"shared\\\" / \\\"projects\\\" / \\\"demo\\\" / \\\"notes.md\\\").exists()\\n\\n    def test_should_not_create_users_directory_in_shared_mode(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n            user_id=\\\"user-ignored\\\",\\n            sub_path=\\\"\\\",\\n        )\\n\\n        component._write_file(\\\"doc.txt\\\", \\\"x\\\")\\n\\n        # When AUTO_LOGIN=True we must not leak a users/ tree even if a\\n        # user_id happens to be available \u2014 that would mix the two layouts.\\n        assert not (base / \\\"users\\\").exists()\\n\\n    def test_should_serve_anonymous_calls_in_shared_mode(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n        # AUTO_LOGIN=True implies a single trusted operator; the absence of a\\n        # user_id is the norm, not an error.\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=tmp_path / \\\"base\\\",\\n            auto_login=True,\\n            user_id=None,\\n        )\\n\\n        result = component._write_file(\\\"hello.txt\\\", \\\"ok\\\")\\n\\n        assert result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, result\\n\\n\\nclass TestIsolatedModeWhenAutoLoginFalse:\\n    \\\"\\\"\\\"Slice S4 \u2014 AUTO_LOGIN=False scopes every call under <BASE>/users/<hash>/.\\\"\\\"\\\"\\n\\n    def test_should_create_files_inside_user_namespace(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-alice\\\",\\n            sub_path=\\\"\\\",\\n        )\\n\\n        write_result = component._write_file(\\\"notes.md\\\", \\\"hello\\\")\\n\\n        assert write_result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, write_result\\n        users_dir = base / \\\"users\\\"\\n        assert users_dir.exists()\\n        user_subdirs = list(users_dir.iterdir())\\n        assert len(user_subdirs) == 1\\n        assert (user_subdirs[0] / \\\"notes.md\\\").read_text(encoding=\\\"utf-8\\\") == \\\"hello\\\"\\n\\n    def test_should_treat_root_path_as_subpath_under_user_namespace(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-alice\\\",\\n            sub_path=\\\"projects/demo\\\",\\n        )\\n\\n        write_result = component._write_file(\\\"notes.md\\\", \\\"demo\\\")\\n\\n        assert write_result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, write_result\\n        user_subdirs = list((base / \\\"users\\\").iterdir())\\n        assert (user_subdirs[0] / \\\"projects\\\" / \\\"demo\\\" / \\\"notes.md\\\").exists()\\n\\n\\nclass TestRefusesAnonymousWhenAutoLoginFalse:\\n    \\\"\\\"\\\"Slice S5 \u2014 AUTO_LOGIN=False without user_id must fail closed.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        \\\"method_call\\\",\\n        [\\n            lambda c: c._read_file(\\\"a.txt\\\"),\\n            lambda c: c._write_file(\\\"a.txt\\\", \\\"x\\\"),\\n            lambda c: c._edit_file(\\\"a.txt\\\", old_string=\\\"x\\\", new_string=\\\"y\\\"),\\n            lambda c: c._glob_search(\\\"**/*\\\"),\\n            lambda c: c._grep_search(\\\"foo\\\"),\\n        ],\\n        ids=[\\\"read\\\", \\\"write\\\", \\\"edit\\\", \\\"glob\\\", \\\"grep\\\"],\\n    )\\n    def test_should_return_structured_error_for_each_tool(\\n        self,\\n        tmp_path: Path,\\n        monkeypatch: pytest.MonkeyPatch,\\n        method_call,\\n    ) -> None:\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=tmp_path / \\\"base\\\",\\n            auto_login=False,\\n            user_id=None,\\n        )\\n\\n        result = method_call(component)\\n\\n        assert \\\"error\\\" in result, f\\\"Expected structured error, got {result}\\\"\\n        assert \\\"user\\\" in result[\\\"error\\\"].lower() or \\\"authenticated\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestCrossUserIsolation:\\n    \\\"\\\"\\\"Threat T1 \u2014 two users on the same flow must never see each other's files.\\\"\\\"\\\"\\n\\n    def test_user_b_should_not_read_file_written_by_user_a(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n\\n        component_a = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-alice\\\",\\n        )\\n        component_a._write_file(\\\"secret.txt\\\", \\\"alice-only\\\")\\n\\n        component_b = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-bob\\\",\\n        )\\n        result = component_b._read_file(\\\"secret.txt\\\")\\n\\n        assert \\\"error\\\" in result, f\\\"User B SHOULD NOT see Alice's file: {result}\\\"\\n        assert \\\"not found\\\" in result[\\\"error\\\"].lower() or \\\"does not exist\\\" in result[\\\"error\\\"].lower()\\n\\n    def test_user_b_glob_should_not_list_files_written_by_user_a(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n\\n        component_a = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-alice\\\",\\n        )\\n        component_a._write_file(\\\"alice-doc.txt\\\", \\\"secret\\\")\\n\\n        component_b = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-bob\\\",\\n        )\\n        result = component_b._glob_search(\\\"**/*\\\")\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\", result\\n        assert \\\"alice-doc.txt\\\" not in result.get(\\\"matches\\\", [])\\n\\n    def test_user_b_cannot_escape_via_dotdot_to_user_a_namespace(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        base = tmp_path / \\\"base\\\"\\n\\n        component_a = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-alice\\\",\\n        )\\n        component_a._write_file(\\\"secret.txt\\\", \\\"alice\\\")\\n\\n        component_b = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=False,\\n            user_id=\\\"user-bob\\\",\\n        )\\n        result = component_b._read_file(\\\"../../secret.txt\\\")\\n\\n        assert \\\"error\\\" in result, f\\\"Path traversal escape not blocked: {result}\\\"\\n\\n\\nclass TestReservedSignatureDirectory:\\n    \\\"\\\"\\\"`.lfsig` is reserved in BOTH modes (future L3 sidecar hook).\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"path\\\", [\\\".lfsig\\\", \\\".lfsig/anything.json\\\", \\\"ok/.lfsig/x\\\"])\\n    def test_should_reject_lfsig_in_isolated_mode(\\n        self,\\n        tmp_path: Path,\\n        monkeypatch: pytest.MonkeyPatch,\\n        path: str,\\n    ) -> None:\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=tmp_path / \\\"base\\\",\\n            auto_login=False,\\n            user_id=\\\"user-alice\\\",\\n        )\\n\\n        result = component._read_file(path)\\n\\n        assert \\\"error\\\" in result, f\\\"`.lfsig` must be reserved, got: {result}\\\"\\n        assert \\\"reserved\\\" in result[\\\"error\\\"].lower() or \\\"lfsig\\\" in result[\\\"error\\\"].lower()\\n\\n    @pytest.mark.parametrize(\\\"path\\\", [\\\".lfsig\\\", \\\".lfsig/anything.json\\\", \\\"ok/.lfsig/x\\\"])\\n    def test_should_reject_lfsig_in_shared_mode(\\n        self,\\n        tmp_path: Path,\\n        monkeypatch: pytest.MonkeyPatch,\\n        path: str,\\n    ) -> None:\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=tmp_path / \\\"base\\\",\\n            auto_login=True,\\n        )\\n\\n        result = component._read_file(path)\\n\\n        assert \\\"error\\\" in result, f\\\"`.lfsig` must be reserved in shared mode too, got: {result}\\\"\\n        assert \\\"reserved\\\" in result[\\\"error\\\"].lower() or \\\"lfsig\\\" in result[\\\"error\\\"].lower()\\n\\n\\nclass TestSharedModeBoundaryEnforcement:\\n    \\\"\\\"\\\"Slice S7 \u2014 shared mode must enforce the same boundary rules as isolated.\\\"\\\"\\\"\\n\\n    def test_should_reject_dotdot_escape_in_shared_mode(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n        base = tmp_path / \\\"base\\\"\\n        # Drop a marker outside <BASE>/shared/ that traversal would expose.\\n        outside = tmp_path / \\\"outside.txt\\\"\\n        outside.write_text(\\\"compromised\\\", encoding=\\\"utf-8\\\")\\n\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=base,\\n            auto_login=True,\\n        )\\n\\n        result = component._read_file(\\\"../../outside.txt\\\")\\n\\n        assert \\\"error\\\" in result, f\\\"Traversal escape not blocked in shared mode: {result}\\\"\\n\\n    def test_should_reject_absolute_path_in_shared_mode(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n        component = _make_component(\\n            monkeypatch=monkeypatch,\\n            base_dir=tmp_path / \\\"base\\\",\\n            auto_login=True,\\n        )\\n\\n        result = component._read_file(\\\"/etc/passwd\\\")\\n\\n        assert \\\"error\\\" in result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_l2_binding_atomicity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"17f9ed151f9c5a2732ac0b6b996f20a103293945dbf95d40f5ef6284d9463c44\",\"content\":\"\\\"\\\"\\\"Regression for the L2 binding atomicity TOCTOU.\\n\\nIn isolated mode the L2 binding check (`_user_binding_error`) reads\\n``self._resolve_user_id()`` once, then ``_validate_root`` reads it again\\nto compute the namespace. If the live user_id shifts between the two\\nreads (component pool reuse across users, side-effecting property,\\nthreaded reentrancy), the binding check passes for user A while the\\nfile lands in user B's namespace.\\n\\nThe fix must ensure a single, atomic capture of ``user_id`` per tool\\ninvocation: the value read by the binding check is the same value used\\nby ``_validate_root`` for the same call.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge._filesystem_namespace import (\\n    compute_user_namespace,\\n    load_or_create_pepper,\\n)\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n\\n@pytest.fixture\\ndef base_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    return tmp_path\\n\\n\\n@pytest.fixture\\ndef component(base_dir: Path, monkeypatch: pytest.MonkeyPatch) -> FileSystemToolComponent:  # noqa: ARG001\\n    # base_dir fixture is consumed for its env-setting side effect.\\n    c = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n    # Isolated mode is the threat scenario: shared mode bypasses the L2\\n    # check entirely (binding is a no-op when AUTO_LOGIN is True).\\n    monkeypatch.setattr(c, \\\"_resolve_auto_login\\\", lambda: False)\\n    return c\\n\\n\\ndef test_should_use_consistent_user_id_within_a_single_tool_call(\\n    component: FileSystemToolComponent,\\n    base_dir: Path,\\n) -> None:\\n    \\\"\\\"\\\"Mutate ``self._user_id`` mid-call and assert no namespace cross-write.\\n\\n    Identity-shift TOCTOU: ``self._user_id`` is mutated between the L2\\n    binding check (which captures it) and ``_validate_root`` (which\\n    would read it again to compute the namespace). The fix must pin the\\n    value captured at the check so the path resolution sees the same\\n    identity even when the underlying attribute changed mid-call.\\n    \\\"\\\"\\\"\\n    component._user_id = \\\"alice\\\"\\n\\n    # Capture the user_id at _get_tools time (binding capture for \\\"alice\\\").\\n    tools = asyncio.run(component._get_tools())\\n    write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n\\n    # Simulate the concurrent mutation: wrap _write_file so it flips\\n    # ``self._user_id`` to \\\"bob\\\" right before the underlying write runs \u2014\\n    # exactly the window the bug requires. Without the L2 atomic capture,\\n    # _validate_root would now read \\\"bob\\\" and resolve bob's namespace,\\n    # silently writing alice's content there.\\n    real_write_file = component._write_file\\n\\n    def write_file_after_identity_shift(path: str, content: str) -> dict:\\n        component._user_id = \\\"bob\\\"\\n        return real_write_file(path, content)\\n\\n    component._write_file = write_file_after_identity_shift  # type: ignore[method-assign]\\n\\n    result_json = write_tool.func(\\\"alice_secret.txt\\\", \\\"alice's content\\\")\\n    result = json.loads(result_json)\\n\\n    pepper = load_or_create_pepper(base_dir / \\\".fs_pepper\\\")\\n    # compute_user_namespace already includes the \\\"users/<hash>\\\" prefix\\n    bob_dir = base_dir / compute_user_namespace(\\\"bob\\\", pepper=pepper)\\n    leaked = bob_dir / \\\"alice_secret.txt\\\"\\n\\n    assert not leaked.exists(), (\\n        f\\\"identity-shift TOCTOU: alice's write leaked into bob's namespace at {leaked!s}; result={result!r}\\\"\\n    )\\n\\n    # Acceptable outcomes: refused with a mismatch error, OR landed under alice.\\n    if \\\"error\\\" not in result:\\n        alice_dir = base_dir / compute_user_namespace(\\\"alice\\\", pepper=pepper)\\n        assert (alice_dir / \\\"alice_secret.txt\\\").exists(), (\\n            \\\"tool reported success but the file is not in alice's namespace\\\"\\n        )\\n\\n\\ndef test_should_refuse_when_binding_check_sees_different_user_than_capture(\\n    component: FileSystemToolComponent,\\n    base_dir: Path,  # noqa: ARG001\\n    monkeypatch: pytest.MonkeyPatch,  # noqa: ARG001\\n) -> None:\\n    \\\"\\\"\\\"Refuse when the live user_id no longer matches the captured one.\\n\\n    Sanity check: when the binding check itself sees a different user\\n    from the one captured at ``_get_tools()``, the call must be refused\\n    outright (this is the existing L2 contract \u2014 pin it in this file).\\n    \\\"\\\"\\\"\\n    component._user_id = \\\"alice\\\"\\n    tools = asyncio.run(component._get_tools())\\n    write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n\\n    # Component reused for bob: live user_id != bound user_id.\\n    component._user_id = \\\"bob\\\"\\n\\n    result = json.loads(write_tool.func(\\\"hello.txt\\\", \\\"hi\\\"))\\n    assert \\\"error\\\" in result\\n    assert \\\"mismatch\\\" in result[\\\"error\\\"].lower()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_namespace.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"14f7748e9d5638c412cfe9292a9cd78d86d1a58a0972752faaa97add5599cdfa\",\"content\":\"\\\"\\\"\\\"Unit tests for namespace derivation helpers used by FileSystemToolComponent.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n\\nclass TestComputeUserNamespace:\\n    \\\"\\\"\\\"Slice A1 \u2014 derive a stable, opaque per-user directory name.\\\"\\\"\\\"\\n\\n    def test_should_return_relative_users_path_when_user_id_is_provided(self) -> None:\\n        # Arrange\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        # Act\\n        namespace = compute_user_namespace(\\\"user-abc\\\", pepper=b\\\"pepper-bytes-32-len-aaaaaaaaaaaa\\\")\\n\\n        # Assert\\n        assert namespace.parts[0] == \\\"users\\\"\\n        assert len(namespace.parts) == 2\\n        assert not namespace.is_absolute()\\n\\n    def test_should_be_deterministic_when_called_with_same_inputs(self) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        pepper = b\\\"pepper-bytes-32-len-aaaaaaaaaaaa\\\"\\n        first = compute_user_namespace(\\\"user-abc\\\", pepper=pepper)\\n        second = compute_user_namespace(\\\"user-abc\\\", pepper=pepper)\\n\\n        assert first == second\\n\\n    def test_should_produce_different_hash_when_user_id_differs(self) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        pepper = b\\\"pepper-bytes-32-len-aaaaaaaaaaaa\\\"\\n        a = compute_user_namespace(\\\"user-A\\\", pepper=pepper)\\n        b = compute_user_namespace(\\\"user-B\\\", pepper=pepper)\\n\\n        assert a != b\\n\\n    def test_should_produce_different_hash_when_pepper_differs(self) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        a = compute_user_namespace(\\\"user-abc\\\", pepper=b\\\"pepper-AAAAAAAAAAAAAAAAAAAAAAAA\\\")\\n        b = compute_user_namespace(\\\"user-abc\\\", pepper=b\\\"pepper-BBBBBBBBBBBBBBBBBBBBBBBB\\\")\\n\\n        assert a != b\\n\\n    def test_should_return_empty_path_when_user_id_is_empty(self) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        namespace = compute_user_namespace(\\\"\\\", pepper=b\\\"pepper-bytes-32-len-aaaaaaaaaaaa\\\")\\n\\n        assert namespace == Path()\\n\\n    def test_should_produce_hash_segment_with_expected_length(self) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        namespace = compute_user_namespace(\\\"user-abc\\\", pepper=b\\\"pepper-bytes-32-len-aaaaaaaaaaaa\\\")\\n\\n        hash_segment = namespace.parts[1]\\n        # 32 hex chars = 128 bits \u2014 collision-free in practice, opaque to listing.\\n        assert len(hash_segment) == 32\\n        assert all(c in \\\"0123456789abcdef\\\" for c in hash_segment)\\n\\n    def test_should_reject_when_pepper_is_empty(self) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import compute_user_namespace\\n\\n        with pytest.raises(ValueError, match=\\\"pepper\\\"):\\n            compute_user_namespace(\\\"user-abc\\\", pepper=b\\\"\\\")\\n\\n\\nclass TestLoadOrCreatePepper:\\n    \\\"\\\"\\\"Slice A2 \u2014 pepper is auto-generated and persisted on first use.\\\"\\\"\\\"\\n\\n    def test_should_create_file_with_pepper_when_path_does_not_exist(self, tmp_path: Path) -> None:\\n        # Arrange\\n        from lfx.components.files_and_knowledge._filesystem_namespace import load_or_create_pepper\\n\\n        pepper_path = tmp_path / \\\".fs_pepper\\\"\\n\\n        # Act\\n        pepper = load_or_create_pepper(pepper_path)\\n\\n        # Assert\\n        assert pepper_path.exists()\\n        assert isinstance(pepper, bytes)\\n        assert len(pepper) >= 32\\n\\n    def test_should_return_same_pepper_when_called_twice(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import load_or_create_pepper\\n\\n        pepper_path = tmp_path / \\\".fs_pepper\\\"\\n\\n        first = load_or_create_pepper(pepper_path)\\n        second = load_or_create_pepper(pepper_path)\\n\\n        assert first == second\\n\\n    def test_should_create_parent_directories_when_missing(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import load_or_create_pepper\\n\\n        pepper_path = tmp_path / \\\"nested\\\" / \\\"deeper\\\" / \\\".fs_pepper\\\"\\n\\n        pepper = load_or_create_pepper(pepper_path)\\n\\n        assert pepper_path.exists()\\n        assert len(pepper) >= 32\\n\\n    def test_should_set_restrictive_mode_when_creating_new_pepper(self, tmp_path: Path) -> None:\\n        # Why this test: the pepper is the secret that anonymizes user_id\\n        # values across the filesystem. It MUST NOT be world-readable on POSIX\\n        # systems \u2014 even when the operator forgets to set up correct umask.\\n        import sys\\n\\n        if sys.platform == \\\"win32\\\":\\n            pytest.skip(\\\"POSIX-only file mode check; Windows ACLs tested separately.\\\")\\n\\n        from lfx.components.files_and_knowledge._filesystem_namespace import load_or_create_pepper\\n\\n        pepper_path = tmp_path / \\\".fs_pepper\\\"\\n        load_or_create_pepper(pepper_path)\\n\\n        mode = pepper_path.stat().st_mode & 0o777\\n        # Only the owner may read/write the pepper.\\n        assert mode == 0o600, f\\\"Expected mode 0o600, got {oct(mode)}\\\"\\n\\n    def test_should_reject_when_existing_pepper_is_too_short(self, tmp_path: Path) -> None:\\n        from lfx.components.files_and_knowledge._filesystem_namespace import load_or_create_pepper\\n\\n        pepper_path = tmp_path / \\\".fs_pepper\\\"\\n        pepper_path.write_bytes(b\\\"short\\\")  # Tampered/corrupted\\n\\n        with pytest.raises(ValueError, match=\\\"pepper\\\"):\\n            load_or_create_pepper(pepper_path)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_reserved_segment_case.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d66a7d28fc2f1f5188e5ade4f6e5cae8405b2d816757ab2cd57d2194a429ce37\",\"content\":\"\\\"\\\"\\\"Regression for the ``.lfsig`` reservation case-sensitivity bypass.\\n\\nThe reservation is enforced via case-sensitive equality at\\n``_validate_path``. APFS and NTFS treat ``.LFSIG`` and ``.lfsig`` as the\\nsame directory, so any uppercase / mixed-case variant bypasses the\\nreservation on those platforms.\\n\\nThe guard must reject every case variation regardless of host OS \u2014 flows\\nauthored on Linux must not silently break the reservation on macOS or\\nWindows.\\n\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n\\n@pytest.fixture\\ndef component(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> FileSystemToolComponent:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    c = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n    # Shared mode keeps the test focused on the reservation guard, not on\\n    # user-isolation plumbing.\\n    monkeypatch.setattr(c, \\\"_resolve_auto_login\\\", lambda: True)\\n    return c\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"variant\\\",\\n    [\\n        \\\".LFSIG\\\",\\n        \\\".LfSiG\\\",\\n        \\\".lfSIG\\\",\\n        \\\".LFSIG/poison.json\\\",\\n        \\\"subdir/.LFSIG/x\\\",\\n        \\\"subdir/.LfSig\\\",\\n    ],\\n)\\ndef test_should_reject_uppercase_reserved_segment_variants(component: FileSystemToolComponent, variant: str) -> None:\\n    \\\"\\\"\\\"write_file must refuse every case variant of the reserved segment.\\\"\\\"\\\"\\n    leaf = variant if \\\"/\\\" in variant else f\\\"{variant}/poison.json\\\"\\n    result = component._write_file(leaf, \\\"{}\\\")\\n\\n    assert \\\"error\\\" in result, f\\\"variant {leaf!r} bypassed the .lfsig reservation; result={result!r}\\\"\\n    assert \\\"reserved\\\" in result[\\\"error\\\"].lower()\\n\\n\\ndef test_lowercase_segment_remains_rejected(component: FileSystemToolComponent) -> None:\\n    \\\"\\\"\\\"The original (lowercase) reservation must still hold after the fix.\\\"\\\"\\\"\\n    result = component._write_file(\\\".lfsig/x.json\\\", \\\"{}\\\")\\n    assert \\\"error\\\" in result\\n    assert \\\"reserved\\\" in result[\\\"error\\\"].lower()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_toctou_symlink.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d91e6311b1451a061c7877eac9002946d981b96d6f8af7c40098e1e6e065d0f\",\"content\":\"\\\"\\\"\\\"Regression for the validate-then-open TOCTOU symlink race.\\n\\nA concurrent process can create a symlink at the validated target\\nbetween the validation step and the open(), causing the write to follow\\nthe symlink and land outside the sandbox.\\n\\nWe deterministically reproduce the race by patching ``os.open`` so that,\\nright before the real open runs, a malicious symlink is dropped at the\\ncandidate path. With ``O_NOFOLLOW`` semantics in the write helper this\\nopen must fail with ``ELOOP``; the file outside ``<BASE>`` must remain\\nuntouched.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n\\n@pytest.fixture\\ndef base_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path / \\\"fs\\\"))\\n    return tmp_path\\n\\n\\n@pytest.fixture\\ndef component(base_dir: Path, monkeypatch: pytest.MonkeyPatch) -> FileSystemToolComponent:  # noqa: ARG001\\n    # base_dir fixture is consumed for its env-setting side effect.\\n    c = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n    monkeypatch.setattr(c, \\\"_resolve_auto_login\\\", lambda: True)  # shared mode for simplicity\\n    return c\\n\\n\\n@pytest.mark.skipif(os.name == \\\"nt\\\", reason=\\\"symlink semantics differ on Windows\\\")\\ndef test_should_refuse_when_target_becomes_symlink_between_validation_and_open(\\n    component: FileSystemToolComponent, base_dir: Path\\n) -> None:\\n    \\\"\\\"\\\"``open()`` must not follow a symlink dropped after validation.\\n\\n    Validation passes (target does not exist); a concurrent process\\n    creates a symlink at the validated path; ``open()`` must NOT follow\\n    it.\\n    \\\"\\\"\\\"\\n    leak_target = base_dir / \\\"outside.txt\\\"\\n    leak_target.write_text(\\\"original\\\", encoding=\\\"utf-8\\\")\\n\\n    namespace_root = base_dir / \\\"fs\\\" / \\\"shared\\\"\\n    target_path = namespace_root / \\\"leak.txt\\\"\\n\\n    real_os_open = os.open\\n    raced = {\\\"done\\\": False}\\n\\n    def racing_os_open(path, flags, mode=0o777, *args, **kwargs):\\n        # Right before opening the validated target, drop a symlink at it\\n        # \u2014 exactly the TOCTOU window. Only race once so the eventual\\n        # error path's open (e.g. for logging) is not also racing.\\n        if not raced[\\\"done\\\"] and isinstance(path, (str, os.PathLike)) and str(path) == str(target_path):\\n            raced[\\\"done\\\"] = True\\n            namespace_root.mkdir(parents=True, exist_ok=True)\\n            target_path.symlink_to(leak_target)\\n        return real_os_open(path, flags, mode, *args, **kwargs)\\n\\n    with patch(\\\"os.open\\\", racing_os_open):\\n        result = json.loads(json.dumps(component._write_file(\\\"leak.txt\\\", \\\"stolen\\\")))\\n\\n    # The file OUTSIDE the namespace MUST remain untouched.\\n    assert leak_target.read_text(encoding=\\\"utf-8\\\") == \\\"original\\\", (\\n        f\\\"TOCTOU: the write followed a symlink created mid-call and clobbered a file outside <BASE>; result={result!r}\\\"\\n    )\\n    # If the tool reports success, the result must be a regular file inside\\n    # the namespace \u2014 never a symlink.\\n    if \\\"error\\\" not in result:\\n        assert target_path.exists()\\n        assert not target_path.is_symlink()\\n    # Confirm the race actually fired (otherwise the test is trivially passing).\\n    assert raced[\\\"done\\\"], \\\"the racing fixture never triggered; the test is not actually exercising the bug\\\"\\n\\n\\n@pytest.mark.skipif(os.name == \\\"nt\\\", reason=\\\"symlink semantics differ on Windows\\\")\\ndef test_should_refuse_to_read_through_symlink_dropped_mid_call(\\n    component: FileSystemToolComponent, base_dir: Path\\n) -> None:\\n    \\\"\\\"\\\"Reads must not follow a symlink dropped after validation.\\n\\n    Same race as the write case: a symlink dropped at the validated read\\n    target must not be followed to a file outside ``<BASE>``.\\n    \\\"\\\"\\\"\\n    secret_outside = base_dir / \\\"outside_secret.txt\\\"\\n    secret_outside.write_text(\\\"TOP SECRET\\\", encoding=\\\"utf-8\\\")\\n\\n    namespace_root = base_dir / \\\"fs\\\" / \\\"shared\\\"\\n    namespace_root.mkdir(parents=True, exist_ok=True)\\n    target_path = namespace_root / \\\"innocent.txt\\\"\\n    target_path.write_text(\\\"decoy\\\", encoding=\\\"utf-8\\\")  # validation sees a regular file\\n\\n    real_os_open = os.open\\n    raced = {\\\"done\\\": False}\\n\\n    def racing_os_open(path, flags, mode=0o777, *args, **kwargs):\\n        if not raced[\\\"done\\\"] and isinstance(path, (str, os.PathLike)) and str(path) == str(target_path):\\n            raced[\\\"done\\\"] = True\\n            target_path.unlink()\\n            target_path.symlink_to(secret_outside)\\n        return real_os_open(path, flags, mode, *args, **kwargs)\\n\\n    with patch(\\\"os.open\\\", racing_os_open):\\n        result = component._read_file(\\\"innocent.txt\\\")\\n\\n    # Either the read is refused (preferred) or it returns the decoy\\n    # content; it MUST NOT return the secret outside <BASE>.\\n    if \\\"error\\\" not in result:\\n        assert \\\"TOP SECRET\\\" not in result.get(\\\"content\\\", \\\"\\\"), (\\n            f\\\"TOCTOU: the read followed a symlink to a file outside <BASE>; result={result!r}\\\"\\n        )\\n    assert raced[\\\"done\\\"], \\\"the racing fixture never triggered\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/tools/test_filesystem_tool_binding.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"882bd5c8e15ba7591e70cd6b9a0c235ceafc76257e8c7ab794e54ca29d92e2ae\",\"content\":\"\\\"\\\"\\\"Layer-2 (L2) tool-binding tests for FileSystemToolComponent.\\n\\nThe goal is to ensure that StructuredTool closures captured at ``_get_tools()``\\ntime refuse to operate after the component instance's user_id has changed \u2014\\nthe threat being instance reuse across user sessions.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _build_component(\\n    *,\\n    monkeypatch: pytest.MonkeyPatch,\\n    base_dir: Path,\\n    user_id: str,\\n) -> FileSystemToolComponent:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(base_dir))\\n    component = FileSystemToolComponent(root_path=\\\"\\\", read_only=False)\\n    # Tool binding only matters when isolation is active (AUTO_LOGIN=False).\\n    component._resolve_auto_login = lambda: False  # type: ignore[method-assign]\\n    component._user_id = user_id\\n    return component\\n\\n\\ndef _get_tools_sync(component: FileSystemToolComponent) -> list:\\n    return asyncio.run(component._get_tools())\\n\\n\\nclass TestToolBindingL2:\\n    \\\"\\\"\\\"Slice E \u2014 captured tools must refuse calls after user_id mutation.\\\"\\\"\\\"\\n\\n    def test_should_return_error_when_read_tool_called_after_user_change(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        # Arrange \u2014 build tools while bound to alice, then \\\"swap\\\" identity.\\n        component = _build_component(monkeypatch=monkeypatch, base_dir=tmp_path / \\\"base\\\", user_id=\\\"alice\\\")\\n        component._write_file(\\\"doc.txt\\\", \\\"alice-only\\\")  # owned by alice\\n        tools = _get_tools_sync(component)\\n        read_tool = next(t for t in tools if t.name == \\\"read_file\\\")\\n\\n        # Act \u2014 masquerade as bob and try to use the captured tool.\\n        component._user_id = \\\"bob\\\"\\n        raw = read_tool.func(\\\"doc.txt\\\")\\n\\n        # Assert \u2014 the closure must refuse before invoking the implementation.\\n        result = json.loads(raw)\\n        assert \\\"error\\\" in result, f\\\"Expected mismatch error, got: {result}\\\"\\n        assert \\\"mismatch\\\" in result[\\\"error\\\"].lower() or \\\"user\\\" in result[\\\"error\\\"].lower()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"tool_name\\\", \\\"args\\\"),\\n        [\\n            (\\\"read_file\\\", (\\\"doc.txt\\\",)),\\n            (\\\"write_file\\\", (\\\"new.txt\\\", \\\"x\\\")),\\n            (\\\"edit_file\\\", (\\\"doc.txt\\\", \\\"alice-only\\\", \\\"bob-was-here\\\")),\\n            (\\\"glob_search\\\", (\\\"**/*\\\",)),\\n            (\\\"grep_search\\\", (\\\"alice\\\",)),\\n        ],\\n    )\\n    def test_should_return_error_when_any_tool_called_after_user_change(\\n        self,\\n        tmp_path: Path,\\n        monkeypatch: pytest.MonkeyPatch,\\n        tool_name: str,\\n        args: tuple,\\n    ) -> None:\\n        component = _build_component(monkeypatch=monkeypatch, base_dir=tmp_path / \\\"base\\\", user_id=\\\"alice\\\")\\n        component._write_file(\\\"doc.txt\\\", \\\"alice-only\\\")\\n        tools = _get_tools_sync(component)\\n        tool = next(t for t in tools if t.name == tool_name)\\n\\n        component._user_id = \\\"bob\\\"\\n        raw = tool.func(*args)\\n\\n        result = json.loads(raw)\\n        assert \\\"error\\\" in result, f\\\"Tool {tool_name} did not refuse cross-user call: {result}\\\"\\n\\n    def test_should_allow_tool_call_when_user_id_did_not_change(\\n        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n    ) -> None:\\n        # Sanity: same user, captured tool keeps working.\\n        component = _build_component(monkeypatch=monkeypatch, base_dir=tmp_path / \\\"base\\\", user_id=\\\"alice\\\")\\n        component._write_file(\\\"doc.txt\\\", \\\"alice-only\\\")\\n        tools = _get_tools_sync(component)\\n        read_tool = next(t for t in tools if t.name == \\\"read_file\\\")\\n\\n        raw = read_tool.func(\\\"doc.txt\\\")\\n        result = json.loads(raw)\\n\\n        assert result.get(\\\"status\\\") == \\\"ok\\\", f\\\"Same-user call broke: {result}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/utilities/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/components/utilities/test_current_date.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fdf8e231ac37102fd724c78db0cc1191b731904d15fa94ef1f7aa0333a150968\",\"content\":\"\\\"\\\"\\\"Tests for CurrentDateComponent tool schema optimization.\\\"\\\"\\\"\\n\\nimport json\\n\\nfrom lfx.base.tools.component_tool import ComponentToolkit\\nfrom lfx.components.utilities.current_date import CurrentDateComponent\\nfrom lfx.io.schema import MAX_OPTIONS_FOR_TOOL_ENUM\\n\\n\\nclass TestCurrentDateToolSchema:\\n    \\\"\\\"\\\"Tests to verify tool schema doesn't waste tokens on large option lists.\\\"\\\"\\\"\\n\\n    def test_should_not_include_enum_when_options_exceed_limit(self):\\n        \\\"\\\"\\\"Verify schema uses string type instead of enum for large option lists.\\\"\\\"\\\"\\n        # Arrange\\n        component = CurrentDateComponent()\\n        # Populate options via update_build_config\\n        build_config = {\\\"timezone\\\": {\\\"options\\\": []}}\\n        component.update_build_config(build_config, \\\"\\\", \\\"timezone\\\")\\n        component.inputs[0].options = build_config[\\\"timezone\\\"][\\\"options\\\"]\\n        toolkit = ComponentToolkit(component)\\n\\n        # Act\\n        tools = toolkit.get_tools()\\n        tool = tools[0]\\n        schema = tool.args_schema.model_json_schema()\\n\\n        # Assert\\n        assert len(component.inputs[0].options) > MAX_OPTIONS_FOR_TOOL_ENUM\\n        assert \\\"enum\\\" not in json.dumps(schema)\\n        assert schema[\\\"properties\\\"][\\\"timezone\\\"][\\\"type\\\"] == \\\"string\\\"\\n\\n    def test_should_have_default_value_in_schema(self):\\n        \\\"\\\"\\\"Verify schema includes default value when enum is skipped.\\\"\\\"\\\"\\n        # Arrange\\n        component = CurrentDateComponent()\\n        toolkit = ComponentToolkit(component)\\n\\n        # Act\\n        tools = toolkit.get_tools()\\n        schema = tools[0].args_schema.model_json_schema()\\n\\n        # Assert\\n        assert schema[\\\"properties\\\"][\\\"timezone\\\"][\\\"default\\\"] == \\\"UTC\\\"\\n\\n    def test_should_reduce_schema_size_significantly(self):\\n        \\\"\\\"\\\"Verify schema size is reasonable (not wasting tokens).\\\"\\\"\\\"\\n        # Arrange\\n        component = CurrentDateComponent()\\n        toolkit = ComponentToolkit(component)\\n        max_acceptable_chars = 500  # Before fix was ~16000\\n\\n        # Act\\n        tools = toolkit.get_tools()\\n        schema_str = json.dumps(tools[0].args_schema.model_json_schema())\\n\\n        # Assert\\n        assert len(schema_str) < max_acceptable_chars\\n\\n\\nclass TestCurrentDateFunctionality:\\n    \\\"\\\"\\\"Tests to verify component still works correctly.\\\"\\\"\\\"\\n\\n    def test_should_return_utc_time_by_default(self):\\n        \\\"\\\"\\\"Verify component returns UTC time when using default timezone.\\\"\\\"\\\"\\n        # Arrange\\n        component = CurrentDateComponent()\\n\\n        # Act\\n        result = component.get_current_date()\\n\\n        # Assert\\n        assert \\\"UTC\\\" in result.text\\n\\n    def test_should_return_time_in_specified_timezone(self):\\n        \\\"\\\"\\\"Verify component respects timezone selection.\\\"\\\"\\\"\\n        # Arrange\\n        component = CurrentDateComponent()\\n        component.timezone = \\\"America/New_York\\\"\\n\\n        # Act\\n        result = component.get_current_date()\\n\\n        # Assert\\n        assert \\\"America/New_York\\\" in result.text or \\\"EST\\\" in result.text or \\\"EDT\\\" in result.text\\n\\n    def test_should_handle_invalid_timezone_gracefully(self):\\n        \\\"\\\"\\\"Verify component returns error for invalid timezone.\\\"\\\"\\\"\\n        # Arrange\\n        component = CurrentDateComponent()\\n        component.timezone = \\\"Invalid/Timezone\\\"\\n\\n        # Act\\n        result = component.get_current_date()\\n\\n        # Assert\\n        assert \\\"Error\\\" in result.text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/config/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/config/test_environments.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1d165c13a805634d8d022dcab6a942e6c88fcbd8ebd799bac699e9f95bb8d72d\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx.config.environments \u2014 environment resolution.\\n\\nAll tests run entirely in-process; no real Langflow instance or SDK required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\nfrom lfx.config.environments import (\\n    ConfigError,\\n    LangflowEnvironment,\\n    _find_config_file,\\n    _load_config,\\n    _parse_env_block,\\n    _parse_toml,\\n    _parse_yaml,\\n    resolve_environment,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n_MINIMAL_YAML = \\\"\\\"\\\"\\\\\\nenvironments:\\n  local:\\n    url: http://localhost:7860\\n    api_key_env: MY_LOCAL_KEY\\n\\n  staging:\\n    url: https://staging.example.com\\n    api_key_env: MY_STAGING_KEY\\n\\ndefaults:\\n  environment: local\\n\\\"\\\"\\\"\\n\\n_MINIMAL_TOML = \\\"\\\"\\\"\\\\\\n[environments.local]\\nurl = \\\"http://localhost:7860\\\"\\napi_key_env = \\\"MY_LOCAL_KEY\\\"  # pragma: allowlist secret\\n\\n[environments.staging]\\nurl = \\\"https://staging.example.com\\\"\\napi_key_env = \\\"MY_STAGING_KEY\\\"  # pragma: allowlist secret\\n\\n[defaults]\\nenvironment = \\\"local\\\"\\n\\\"\\\"\\\"\\n\\n_NO_DEFAULT_YAML = \\\"\\\"\\\"\\\\\\nenvironments:\\n  staging:\\n    url: https://staging.example.com\\n    api_key_env: MY_STAGING_KEY\\n\\\"\\\"\\\"\\n\\n\\ndef _write(tmp_path: Path, name: str, content: str) -> Path:\\n    p = tmp_path / name\\n    p.parent.mkdir(parents=True, exist_ok=True)\\n    p.write_text(content, encoding=\\\"utf-8\\\")\\n    return p\\n\\n\\n# ---------------------------------------------------------------------------\\n# LangflowEnvironment\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLangflowEnvironment:\\n    def test_fields_stored(self):\\n        e = LangflowEnvironment(name=\\\"staging\\\", url=\\\"https://x.com\\\", api_key=\\\"key123\\\")  # pragma: allowlist secret\\n        assert e.name == \\\"staging\\\"\\n        assert e.url == \\\"https://x.com\\\"\\n        assert e.api_key == \\\"key123\\\"  # pragma: allowlist secret\\n\\n    def test_api_key_may_be_none(self):\\n        e = LangflowEnvironment(name=\\\"local\\\", url=\\\"http://localhost:7860\\\", api_key=None)\\n        assert e.api_key is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# _parse_yaml\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestParseYaml:\\n    def test_parses_valid_yaml(self, tmp_path):\\n        path = _write(tmp_path, \\\"e.yaml\\\", _MINIMAL_YAML)\\n        result = _parse_yaml(_MINIMAL_YAML, path)\\n        assert \\\"environments\\\" in result\\n        assert \\\"local\\\" in result[\\\"environments\\\"]\\n\\n    def test_raises_on_invalid_yaml(self, tmp_path):\\n        path = _write(tmp_path, \\\"e.yaml\\\", \\\":\\\\n  - invalid: [\\\")\\n        with pytest.raises(ConfigError, match=\\\"Invalid YAML\\\"):\\n            _parse_yaml(\\\":\\\\n  - invalid: [\\\", path)\\n\\n    def test_raises_when_top_level_not_mapping(self, tmp_path):\\n        path = _write(tmp_path, \\\"e.yaml\\\", \\\"- item1\\\\n- item2\\\\n\\\")\\n        with pytest.raises(ConfigError, match=\\\"mapping\\\"):\\n            _parse_yaml(\\\"- item1\\\\n- item2\\\\n\\\", path)\\n\\n    def test_returns_dict(self, tmp_path):\\n        path = _write(tmp_path, \\\"e.yaml\\\", \\\"key: value\\\\n\\\")\\n        result = _parse_yaml(\\\"key: value\\\\n\\\", path)\\n        assert isinstance(result, dict)\\n\\n\\n# ---------------------------------------------------------------------------\\n# _parse_toml\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestParseToml:\\n    def test_parses_valid_toml(self, tmp_path):\\n        path = _write(tmp_path, \\\"e.toml\\\", _MINIMAL_TOML)\\n        result = _parse_toml(path)\\n        assert \\\"environments\\\" in result\\n        assert \\\"local\\\" in result[\\\"environments\\\"]\\n\\n    def test_raises_on_invalid_toml(self, tmp_path):\\n        path = _write(tmp_path, \\\"e.toml\\\", \\\"not = valid = toml\\\\n\\\")\\n        with pytest.raises(ConfigError):\\n            _parse_toml(path)\\n\\n    def test_raises_on_missing_file(self, tmp_path):\\n        path = tmp_path / \\\"missing.toml\\\"\\n        with pytest.raises(ConfigError, match=\\\"Cannot read\\\"):\\n            _parse_toml(path)\\n\\n\\n# ---------------------------------------------------------------------------\\n# _parse_env_block\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestParseEnvBlock:\\n    def test_minimal_block_with_url(self, tmp_path, monkeypatch):\\n        monkeypatch.setenv(\\\"MY_KEY\\\", \\\"secret123\\\")  # pragma: allowlist secret\\n        block = {\\\"url\\\": \\\"http://localhost:7860\\\", \\\"api_key_env\\\": \\\"MY_KEY\\\"}  # pragma: allowlist secret\\n        path = tmp_path / \\\"e.yaml\\\"\\n        result = _parse_env_block(\\\"local\\\", block, path)\\n        assert result.url == \\\"http://localhost:7860\\\"\\n        assert result.api_key == \\\"secret123\\\"  # pragma: allowlist secret\\n        assert result.name == \\\"local\\\"\\n\\n    def test_missing_url_raises(self, tmp_path):\\n        path = tmp_path / \\\"e.yaml\\\"\\n        with pytest.raises(ConfigError, match=r\\\"missing.*'url'\\\"):\\n            _parse_env_block(\\\"local\\\", {\\\"api_key_env\\\": \\\"FOO\\\"}, path)  # pragma: allowlist secret\\n\\n    def test_not_a_dict_raises(self, tmp_path):\\n        path = tmp_path / \\\"e.yaml\\\"\\n        with pytest.raises(ConfigError, match=\\\"mapping\\\"):\\n            _parse_env_block(\\\"local\\\", \\\"not a dict\\\", path)\\n\\n    def test_missing_env_var_returns_none(self, tmp_path, monkeypatch):\\n        monkeypatch.delenv(\\\"MISSING_KEY\\\", raising=False)\\n        path = tmp_path / \\\"e.yaml\\\"\\n        result = _parse_env_block(\\\"local\\\", {\\\"url\\\": \\\"http://x\\\", \\\"api_key_env\\\": \\\"MISSING_KEY\\\"}, path)\\n        assert result.api_key is None\\n\\n    def test_literal_api_key_in_block(self, tmp_path):\\n        path = tmp_path / \\\"e.yaml\\\"\\n        block = {\\\"url\\\": \\\"http://x\\\", \\\"api_key\\\": \\\"direct-key\\\"}  # pragma: allowlist secret\\n        result = _parse_env_block(\\\"local\\\", block, path)\\n        assert result.api_key == \\\"direct-key\\\"  # pragma: allowlist secret\\n\\n    def test_no_key_field_api_key_is_none(self, tmp_path):\\n        path = tmp_path / \\\"e.yaml\\\"\\n        result = _parse_env_block(\\\"local\\\", {\\\"url\\\": \\\"http://x\\\"}, path)\\n        assert result.api_key is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# _find_config_file\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFindConfigFile:\\n    def test_override_file_returned_when_it_exists(self, tmp_path):\\n        p = _write(tmp_path, \\\"my.yaml\\\", _MINIMAL_YAML)\\n        assert _find_config_file(p) == p\\n\\n    def test_override_missing_raises(self, tmp_path):\\n        missing = tmp_path / \\\"missing.yaml\\\"\\n        with pytest.raises(ConfigError, match=\\\"not found\\\"):\\n            _find_config_file(missing)\\n\\n    def test_finds_lfx_yaml_in_cwd(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        p = _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        assert _find_config_file(None) == p\\n\\n    def test_finds_lfx_yml_in_cwd(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        p = _write(tmp_path, \\\".lfx/environments.yml\\\", _MINIMAL_YAML)\\n        assert _find_config_file(None) == p\\n\\n    def test_walks_up_to_parent(self, tmp_path, monkeypatch):\\n        parent_yaml = _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        child = tmp_path / \\\"subdir\\\"\\n        child.mkdir()\\n        monkeypatch.chdir(child)\\n        # No .git boundary, so should walk up to tmp_path\\n        result = _find_config_file(None)\\n        assert result == parent_yaml\\n\\n    def test_stops_at_git_boundary(self, tmp_path, monkeypatch):\\n        # Create .git in cwd so the walk stops there\\n        cwd = tmp_path / \\\"project\\\"\\n        cwd.mkdir()\\n        (cwd / \\\".git\\\").mkdir()\\n        # Parent has a YAML config \u2014 should NOT be found (stopped by .git boundary)\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        monkeypatch.chdir(cwd)\\n        # Also check no TOML fallback\\n        result = _find_config_file(None)\\n        assert result is None\\n\\n    def test_toml_fallback_when_no_yaml(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        p = _write(tmp_path, \\\"langflow-environments.toml\\\", _MINIMAL_TOML)\\n        assert _find_config_file(None) == p\\n\\n    def test_returns_none_when_nothing_found(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        # Create a git boundary so it doesn't walk up further\\n        (tmp_path / \\\".git\\\").mkdir()\\n        assert _find_config_file(None) is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# _load_config\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoadConfig:\\n    def test_loads_yaml_environments(self, tmp_path, monkeypatch):\\n        monkeypatch.setenv(\\\"MY_LOCAL_KEY\\\", \\\"local-key\\\")  # pragma: allowlist secret\\n        monkeypatch.setenv(\\\"MY_STAGING_KEY\\\", \\\"staging-key\\\")  # pragma: allowlist secret\\n        p = _write(tmp_path, \\\"e.yaml\\\", _MINIMAL_YAML)\\n        envs, default = _load_config(p)\\n        assert \\\"local\\\" in envs\\n        assert \\\"staging\\\" in envs\\n        assert default == \\\"local\\\"\\n        assert envs[\\\"local\\\"].url == \\\"http://localhost:7860\\\"\\n        assert envs[\\\"local\\\"].api_key == \\\"local-key\\\"  # pragma: allowlist secret\\n\\n    def test_loads_toml_environments(self, tmp_path, monkeypatch):\\n        monkeypatch.setenv(\\\"MY_LOCAL_KEY\\\", \\\"local-key\\\")  # pragma: allowlist secret\\n        p = _write(tmp_path, \\\"e.toml\\\", _MINIMAL_TOML)\\n        envs, default = _load_config(p)\\n        assert \\\"local\\\" in envs\\n        assert default == \\\"local\\\"\\n\\n    def test_no_defaults_returns_none(self, tmp_path):\\n        p = _write(tmp_path, \\\"e.yaml\\\", _NO_DEFAULT_YAML)\\n        _, default = _load_config(p)\\n        assert default is None\\n\\n    def test_missing_env_var_does_not_raise_in_load(self, tmp_path, monkeypatch):\\n        monkeypatch.delenv(\\\"MY_LOCAL_KEY\\\", raising=False)\\n        p = _write(tmp_path, \\\"e.yaml\\\", _MINIMAL_YAML)\\n        # _load_config does NOT raise for missing env vars \u2014 just returns None for api_key\\n        envs, _ = _load_config(p)\\n        assert envs[\\\"local\\\"].api_key is None\\n\\n    def test_malformed_environments_key_raises(self, tmp_path):\\n        bad_yaml = \\\"environments: not_a_mapping_but_a_string\\\\n\\\"\\n        p = _write(tmp_path, \\\"e.yaml\\\", bad_yaml)\\n        with pytest.raises(ConfigError, match=\\\"mapping\\\"):\\n            _load_config(p)\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_environment \u2014 inline mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestResolveInlineMode:\\n    def test_target_returns_inline_env(self):\\n        result = resolve_environment(None, target=\\\"http://localhost:7860\\\")\\n        assert result.url == \\\"http://localhost:7860\\\"\\n        assert result.name == \\\"__inline__\\\"\\n        assert result.api_key is None\\n\\n    def test_target_with_api_key(self):\\n        result = resolve_environment(None, target=\\\"http://localhost:7860\\\", api_key=\\\"mykey\\\")  # pragma: allowlist secret\\n        assert result.api_key == \\\"mykey\\\"  # pragma: allowlist secret\\n\\n    def test_target_with_env_name_uses_env_name_as_label(self):\\n        result = resolve_environment(\\\"staging\\\", target=\\\"http://localhost:7860\\\", api_key=\\\"k\\\")  # pragma: allowlist secret\\n        assert result.name == \\\"staging\\\"\\n        assert result.url == \\\"http://localhost:7860\\\"\\n\\n    def test_target_ignores_environments_file(self, tmp_path):\\n        # Even if environments_file is given, --target bypasses it entirely\\n        result = resolve_environment(\\n            None,\\n            target=\\\"http://localhost:7860\\\",\\n            environments_file=str(tmp_path / \\\"missing.yaml\\\"),\\n        )\\n        assert result.url == \\\"http://localhost:7860\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_environment \u2014 config file mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestResolveConfigMode:\\n    def test_named_env_resolved(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        monkeypatch.setenv(\\\"MY_STAGING_KEY\\\", \\\"staging-secret\\\")  # pragma: allowlist secret\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        result = resolve_environment(\\\"staging\\\")\\n        assert result.url == \\\"https://staging.example.com\\\"\\n        assert result.api_key == \\\"staging-secret\\\"  # pragma: allowlist secret\\n        assert result.name == \\\"staging\\\"\\n\\n    def test_default_env_used_when_no_env_given(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        monkeypatch.setenv(\\\"MY_LOCAL_KEY\\\", \\\"local-secret\\\")  # pragma: allowlist secret\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        result = resolve_environment(None)\\n        assert result.url == \\\"http://localhost:7860\\\"\\n        assert result.api_key == \\\"local-secret\\\"  # pragma: allowlist secret\\n\\n    def test_explicit_environments_file_used(self, tmp_path, monkeypatch):\\n        monkeypatch.setenv(\\\"MY_LOCAL_KEY\\\", \\\"local-key\\\")  # pragma: allowlist secret\\n        p = _write(tmp_path, \\\"custom/env.yaml\\\", _MINIMAL_YAML)\\n        result = resolve_environment(\\\"local\\\", environments_file=str(p))\\n        assert result.url == \\\"http://localhost:7860\\\"\\n\\n    def test_api_key_override_applied(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        monkeypatch.setenv(\\\"MY_LOCAL_KEY\\\", \\\"config-key\\\")  # pragma: allowlist secret\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        result = resolve_environment(\\\"local\\\", api_key=\\\"override-key\\\")  # pragma: allowlist secret\\n        assert result.api_key == \\\"override-key\\\"  # pragma: allowlist secret\\n\\n    def test_missing_env_var_returns_none_api_key(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        monkeypatch.delenv(\\\"MY_LOCAL_KEY\\\", raising=False)\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        result = resolve_environment(\\\"local\\\")\\n        # Missing env var yields None \u2014 caller decides whether to treat this as error\\n        assert result.api_key is None\\n\\n    def test_unknown_env_name_raises(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        with pytest.raises(ConfigError, match=r\\\"'production'.*not found\\\"):\\n            resolve_environment(\\\"production\\\")\\n\\n    def test_no_default_and_no_env_name_raises(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _NO_DEFAULT_YAML)\\n        with pytest.raises(ConfigError, match=\\\"No --env given\\\"):\\n            resolve_environment(None)\\n\\n    def test_toml_file_also_works(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        monkeypatch.setenv(\\\"MY_LOCAL_KEY\\\", \\\"local-secret\\\")  # pragma: allowlist secret\\n        _write(tmp_path, \\\"langflow-environments.toml\\\", _MINIMAL_TOML)\\n        result = resolve_environment(\\\"local\\\")\\n        assert result.url == \\\"http://localhost:7860\\\"\\n        assert result.api_key == \\\"local-secret\\\"  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_environment \u2014 no config file fallbacks\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestResolveNoConfigFallbacks:\\n    def test_langflow_url_env_var_used_as_fallback(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        (tmp_path / \\\".git\\\").mkdir()  # stop file walk here\\n        monkeypatch.setenv(\\\"LANGFLOW_URL\\\", \\\"http://fallback:7860\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_API_KEY\\\", \\\"fallback-key\\\")  # pragma: allowlist secret\\n        result = resolve_environment(None)\\n        assert result.url == \\\"http://fallback:7860\\\"\\n        assert result.api_key == \\\"fallback-key\\\"  # pragma: allowlist secret\\n        assert result.name == \\\"__env__\\\"\\n\\n    def test_lfx_url_env_var_used_as_fallback(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        (tmp_path / \\\".git\\\").mkdir()\\n        monkeypatch.delenv(\\\"LANGFLOW_URL\\\", raising=False)\\n        monkeypatch.setenv(\\\"LFX_URL\\\", \\\"http://lfx-fallback:7860\\\")\\n        monkeypatch.setenv(\\\"LFX_API_KEY\\\", \\\"lfx-key\\\")  # pragma: allowlist secret\\n        result = resolve_environment(None)\\n        assert result.url == \\\"http://lfx-fallback:7860\\\"\\n        assert result.api_key == \\\"lfx-key\\\"  # pragma: allowlist secret\\n\\n    def test_named_env_without_config_raises_clear_error(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        (tmp_path / \\\".git\\\").mkdir()\\n        monkeypatch.delenv(\\\"LANGFLOW_URL\\\", raising=False)\\n        monkeypatch.delenv(\\\"LFX_URL\\\", raising=False)\\n        with pytest.raises(ConfigError, match=r\\\"'staging'.*no config file\\\"):\\n            resolve_environment(\\\"staging\\\")\\n\\n    def test_no_env_no_config_no_env_vars_raises(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        (tmp_path / \\\".git\\\").mkdir()\\n        monkeypatch.delenv(\\\"LANGFLOW_URL\\\", raising=False)\\n        monkeypatch.delenv(\\\"LFX_URL\\\", raising=False)\\n        with pytest.raises(ConfigError, match=\\\"No --env\\\"):\\n            resolve_environment(None)\\n\\n    def test_missing_explicit_environments_file_raises(self, tmp_path):\\n        missing = tmp_path / \\\"missing.yaml\\\"\\n        with pytest.raises(ConfigError, match=\\\"not found\\\"):\\n            resolve_environment(\\\"staging\\\", environments_file=str(missing))\\n\\n    def test_inline_api_key_override_with_env_var_url(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        (tmp_path / \\\".git\\\").mkdir()\\n        monkeypatch.setenv(\\\"LANGFLOW_URL\\\", \\\"http://fallback:7860\\\")\\n        monkeypatch.delenv(\\\"LANGFLOW_API_KEY\\\", raising=False)\\n        # api_key arg should override the env-var based key\\n        result = resolve_environment(None, api_key=\\\"override-key\\\")  # pragma: allowlist secret\\n        # In fallback mode, api_key_inline takes precedence\\n        assert result.api_key == \\\"override-key\\\"  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# Error message quality\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestErrorMessages:\\n    def test_unknown_env_message_lists_available(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _MINIMAL_YAML)\\n        with pytest.raises(ConfigError, match=\\\"local\\\") as exc_info:\\n            resolve_environment(\\\"typo-env\\\")\\n        assert \\\"staging\\\" in str(exc_info.value)\\n\\n    def test_no_config_message_suggests_init(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        (tmp_path / \\\".git\\\").mkdir()\\n        monkeypatch.delenv(\\\"LANGFLOW_URL\\\", raising=False)\\n        monkeypatch.delenv(\\\"LFX_URL\\\", raising=False)\\n        with pytest.raises(ConfigError, match=\\\"lfx init\\\"):\\n            resolve_environment(\\\"staging\\\")\\n\\n    def test_no_default_message_shows_available(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        _write(tmp_path, \\\".lfx/environments.yaml\\\", _NO_DEFAULT_YAML)\\n        with pytest.raises(ConfigError, match=\\\"staging\\\"):\\n            resolve_environment(None)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/custom/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/custom/component/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/custom/component/test_component_instance_attributes.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"576b00ce198c3ba63cfde0632295039d1bb760006e8308ea114dd5d00478610b\",\"content\":\"import pytest\\nfrom lfx.components.input_output.chat import ChatInput\\nfrom lfx.schema.message import Message\\n\\n\\n@pytest.fixture\\ndef chat_input_instances():\\n    \\\"\\\"\\\"Create two instances of ChatInput for testing.\\\"\\\"\\\"\\n    chat1 = ChatInput()\\n    chat2 = ChatInput()\\n    return chat1, chat2\\n\\n\\ndef test_input_value_independence(chat_input_instances):\\n    \\\"\\\"\\\"Test that input_value is independent between instances.\\\"\\\"\\\"\\n    chat1, chat2 = chat_input_instances\\n\\n    # Set different input values\\n    chat1.build(input_value=\\\"Hello from chat1\\\")\\n    chat2.build(input_value=\\\"Hello from chat2\\\")\\n\\n    # Verify values are different\\n    assert chat1.input_value != chat2.input_value\\n    assert chat1.input_value == \\\"Hello from chat1\\\"\\n    assert chat2.input_value == \\\"Hello from chat2\\\"\\n\\n\\ndef test_sender_name_independence(chat_input_instances):\\n    \\\"\\\"\\\"Test that sender_name is independent between instances.\\\"\\\"\\\"\\n    chat1, chat2 = chat_input_instances\\n\\n    # Set different sender names\\n    chat1.build(sender_name=\\\"Alice\\\")\\n    chat2.build(sender_name=\\\"Bob\\\")\\n\\n    # Verify values are different\\n    assert chat1.sender_name != chat2.sender_name\\n    assert chat1.sender_name == \\\"Alice\\\"\\n    assert chat2.sender_name == \\\"Bob\\\"\\n\\n\\ndef test_multiple_attributes_independence(chat_input_instances):\\n    \\\"\\\"\\\"Test that multiple attributes are independent between instances.\\\"\\\"\\\"\\n    chat1, chat2 = chat_input_instances\\n\\n    # Set multiple attributes for chat1\\n    chat1.build(input_value=\\\"Message 1\\\", sender_name=\\\"Alice\\\", background_color=\\\"blue\\\", text_color=\\\"white\\\")\\n\\n    # Set different attributes for chat2\\n    chat2.build(input_value=\\\"Message 2\\\", sender_name=\\\"Bob\\\", background_color=\\\"red\\\", text_color=\\\"black\\\")\\n\\n    # Verify all attributes are independent\\n    assert chat1.input_value != chat2.input_value\\n    assert chat1.sender_name != chat2.sender_name\\n    assert chat1.background_color != chat2.background_color\\n    assert chat1.text_color != chat2.text_color\\n\\n\\n@pytest.mark.asyncio\\nasync def test_message_output_independence(chat_input_instances):\\n    \\\"\\\"\\\"Test that message outputs are independent between instances.\\\"\\\"\\\"\\n    chat1, chat2 = chat_input_instances\\n\\n    # Configure different messages\\n    chat1.build(\\n        input_value=\\\"Hello from chat1\\\",\\n        sender_name=\\\"Alice\\\",\\n        should_store_message=False,  # Prevent actual message storage\\n    )\\n    chat2.build(\\n        input_value=\\\"Hello from chat2\\\",\\n        sender_name=\\\"Bob\\\",\\n        should_store_message=False,  # Prevent actual message storage\\n    )\\n\\n    # Get messages from both instances\\n    message1 = await chat1.message_response()\\n    message2 = await chat2.message_response()\\n\\n    # Verify messages are different\\n    assert isinstance(message1, Message)\\n    assert isinstance(message2, Message)\\n    assert message1.text != message2.text\\n    assert message1.sender_name != message2.sender_name\\n\\n\\n@pytest.mark.asyncio\\nasync def test_status_independence(chat_input_instances):\\n    \\\"\\\"\\\"Test that status attribute is independent between instances.\\\"\\\"\\\"\\n    chat1, chat2 = chat_input_instances\\n\\n    # Configure and run messages\\n    chat1.build(input_value=\\\"Status test 1\\\", sender_name=\\\"Alice\\\", should_store_message=False)\\n    chat2.build(input_value=\\\"Status test 2\\\", sender_name=\\\"Bob\\\", should_store_message=False)\\n\\n    # Generate messages to update status\\n    await chat1.message_response()\\n    await chat2.message_response()\\n\\n    # Verify status values are different\\n    assert chat1.status != chat2.status\\n    assert chat1.status.text == \\\"Status test 1\\\"\\n    assert chat2.status.text == \\\"Status test 2\\\"\\n\\n\\ndef test_files_independence(chat_input_instances):\\n    \\\"\\\"\\\"Test that files attribute is independent between instances.\\\"\\\"\\\"\\n    chat1, chat2 = chat_input_instances\\n\\n    # Set different files\\n    files1 = [\\\"file1.txt\\\", \\\"file2.txt\\\"]\\n    files2 = [\\\"file3.txt\\\", \\\"file4.txt\\\"]\\n\\n    chat1.build(files=files1)\\n    chat2.build(files=files2)\\n\\n    # Verify files are independent\\n    assert chat1.files != chat2.files\\n    assert chat1.files == files1\\n    assert chat2.files == files2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/custom/component/test_component_to_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c9a1055717c8f2521d7e728f259c985c15ca342f6e92e3a8b6aaa22f8c19dc22\",\"content\":\"from collections.abc import Callable\\n\\nimport pytest\\n\\n\\n@pytest.mark.skip(\\\"Temporarily disabled\\\")\\nasync def test_component_to_toolkit():\\n    from lfx.components.agents.agent import AgentComponent\\n    from lfx.components.tools.calculator import CalculatorToolComponent\\n\\n    calculator_component = CalculatorToolComponent()\\n    agent_component = AgentComponent().set(tools=[calculator_component])\\n\\n    tools = await agent_component.to_toolkit()\\n    assert len(tools) == 1\\n    tool = tools[0]\\n\\n    assert tool.name == \\\"Call_Agent\\\"\\n\\n    # After removing the depre";
